['Here is an example of how you might implement this in C with a basic structure for the PHY layer configuration and the functions for managing it. Please note that this is just an example, and does not cover all your requirements like thread safety, error handling, etc. You would need to expand on this to meet your needs.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int cell_identity;
    char frequency_band[10];  // Assume frequency band is represented as a string, like "2G", "3G", etc.
    float bandwidth;
    float transmit_power;
} PHYLayerConfig;

typedef struct {
    PHYLayerConfig* phy_layer_configs;
    int size;
    pthread_mutex_t mutex;
} ManagedArray;

ManagedArray managed_array = {NULL, 0};

void init_managed_array() {
    pthread_mutex_init(&managed_array.mutex, NULL);
}

int add_config(PHYLayerConfig phy_layer_config) {
    pthread_mutex_lock(&managed_array.mutex);
    ++managed_array.size;
    managed_array.phy_layer_configs = realloc(managed_array.phy_layer_configs, managed_array.size * sizeof(PHYLayerConfig));
    if (managed_array.phy_layer_configs == NULL) {
        --managed_array.size;
        pthread_mutex_unlock(&managed_array.mutex);
        return -1;  // Failed to allocate memory
    }

    managed_array.phy_layer_configs[managed_array.size-1] = phy_layer_config;
    pthread_mutex_unlock(&managed_array.mutex);
    return 0; // Successfully added config
}

int save_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file == NULL) {
        perror("Error opening file for writing.");
        return -1;  // Failed to open the file
    }

    pthread_mutex_lock(&managed_array.mutex);
    fwrite(managed_array.phy_layer_configs, sizeof(PHYLayerConfig), managed_array.size, file);
    pthread_mutex_unlock(&managed_array.mutex);

    fclose(file);
    return 0; // Successfully saved to file
}

int load_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");

    if (file == NULL) {
        perror("Error opening file for reading.");
        return -1;  // Failed to open the file
    }

    pthread_mutex_lock(&managed_array.mutex);
    fseek(file, 0L, SEEK_END);
    long size = ftell(file);
    rewind(file);

    managed_array.size = size / sizeof(PHYLayerConfig);
    managed_array.phy_layer_configs = malloc(managed_array.size * sizeof(PHYLayerConfig));
    if (managed_array.phy_layer_configs == NULL) {
        --managed_array.size;
        pthread_mutex_unlock(&managed_array.mutex);
        return -1;  // Failed to allocate memory
    }

    fread(managed_array.phy_layer_configs, sizeof(PHYLayerConfig), managed_array.size, file);
    pthread_mutex_unlock(&managed_array.mutex);

    fclose(file);
    return 0; // Successfully loaded from file
}
```
']

