void customErrorHandling(char* message, FILE* logFile) {
    pthread_mutex_lock(&lock);
    fprintf(logFile, "ERROR: %s\n", message);
    pthread_mutex_unlock(&lock);
    exit(1); // or any appropriate error handling mechanism 
