void allocateMemoryAndInitialize(int maxRecords, FILE* logFile) {
    long *offsetValues = malloc(maxRecords * sizeof(long));
    int *keys = malloc(maxRecords * sizeof(int));
    Record *records = malloc(maxRecords * sizeof(Record));

    if (offsetValues == NULL || keys == NULL || records == NULL) {
        customErrorHandling("Memory allocation failed", logFile);
    }

    for (int i = 0; i < maxRecords; ++i) {
        offsetValues[i] = rand_gen(); // Using random number generator from external library
        keys[i] = i;

        records[i].value = i * 10;
        records[i].offset = &(offsetValues[i]);
        records[i].key = &(keys[i]);
    }

    // Handle the resources in a thread-safe manner.
    pthread_mutex_lock(&lock);
    free(offsetValues);
    free(keys);
    free(records);
    pthread_mutex_unlock(&lock);
