['Here's a basic example of how you could implement this in C. Please note that error checking has been left out for brevity. Also, note that your requirements regarding handling large files effectively are somewhat vague. This code does assume a typical case where lines from the log file can fit into memory, and it reads the entire file at once:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void process_log(char *input_file, char *output_file, char *rules, int detailed_logs) {
    FILE *in = fopen(input_file, "r");
    if (in == NULL) {
        printf("Failed to open input file.\n");
        return;
    }

    // Get the size of the file.
    fseek(in, 0L, SEEK_END);
    long numbytes = ftell(in);

    // Reset the file position indicator to the start of the file.
    fseek(in, 0L, SEEK_SET);	

    // Allocate memory for the entire content.
    char *buffer = (char*)calloc(numbytes + 1, sizeof(char));	

    if(buffer == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    // Read file contents into buffer.
    fread(buffer, sizeof(char), numbytes, in);
    fclose(in);

    FILE *out = fopen(output_file, "w");
    if (out == NULL) {
        printf("Failed to open output file.\n");
        return;
    }

    // Parse and process the log lines based on 'rules'. 
    // This is a placeholder as you didn't specify how metrics are extracted from the logs.
    char *p = strtok(buffer, "\n");
    while (p != NULL) {
        fprintf(out, "Processed: %s\n", p);  // Replace with actual processing
        if (detailed_logs) {
            fprintf(out, "%s\n", p);  // If detailed logs are requested, write raw log entry.
        }
        p = strtok(NULL, "\n");
    }

    free(buffer);
    fclose(out);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        printf("Usage: %s <input_file> <output_file> <rules> <detailed_logs>\n", argv[0]);
        return 1;
    }

    process_log(argv[1], argv[2], argv[3], atoi(argv[4]));
    return 0;
}
```
This code assumes that the metrics extraction rules are not complex and can be easily implemented by parsing each line of the log file. The detailed logs flag is just a boolean to indicate whether or not raw log lines should be written to the output file. If you want more specific behavior, like different metrics for different types of logs, you'll need to add that yourself. 

Also note that this code does not handle cases where the log files are too large to fit into memory entirely - it would require a more complex approach to read and process the file in chunks rather than all at once.
