['```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    const EVP_MD *md;
} HashAlgorithm;

int parseConfig(const char *configPath, HashAlgorithm *algorithms) {
    FILE *file = fopen(configPath, "r");
    if (file == NULL) {
        printf("Error opening config file.\n");
        return -1;
    }

    char line[256];
    int numAlgos = 0;
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "#", 1) == 0 || strlen(line) < 3) continue;
        const EVP_MD *md = EVP_get_digestbyname(line);
        if (md == NULL) {
            printf("Invalid hash algorithm in config: %s\n", line);
            continue;
        }
        algorithms[numAlgos].md = md;
        numAlgos++;
    }

    fclose(file);
    return numAlgos;
}

void cryptoOperations(const HashAlgorithm *algorithms, int numAlgos) {
    ERR_load_crypto_strings();
    OpenSSL_add_all_digests();

    for (int i = 0; i < numAlgos; i++) {
        EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
        if (mdctx == NULL) handleErrors();

        if(1 != EVP_DigestInit_ex(mdctx, algorithms[i].md, NULL)) handleErrors();
        /* perform cryptographic operations */
        /* ... */
    }
}

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}
```
