#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/times.h>
#include <pthread.h>

// Logger interface, you need to provide this part
extern void logger_log(const char* message); 

typedef struct record {
    int value;
    unsigned long offset;
    int key;
} record_t;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processStringAndAllocate(char *str, const char* options, size_t maxRecords) {
    struct tms startTime; 
    times(&startTime);

    pthread_mutex_lock(&lock);

    logger_log("Starting memory allocation.");

    // Allocate arrays for 'long' offset values and 'int' keys.
    unsigned long* offsets = (unsigned long*)malloc(sizeof(unsigned long) * maxRecords);
    if (offsets == NULL) {
        logger_log("Failed to allocate memory for offsets.");
        return NULL;
    }

    int* keys = (int*)malloc(sizeof(int) * maxRecords);
    if (keys == NULL) {
        logger_log("Failed to allocate memory for keys.");
        free(offsets);
        return NULL;
    }

    // Allocate and initialize array of 'record' structures.
    record_t* records = malloc(sizeof(record_t) * maxRecords);
    if (records == NULL) {
        logger_log("Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize each record with a reference to its corresponding key and offset.
    for (size_t i = 0; i < maxRecords; ++i) {
        records[i].value = rand(); // Random number generation
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    logger_log("Memory allocation complete.");

    struct EVP_CIPHER_CTX *ctx;

    // Use OpenSSL library to perform specified operation based on command line options.
    if (strcmp(options, "encrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();

        // Perform encryption with the OpenSSL library...
        EVP_EncryptInit_ex(ctx, /* Add your cipher type here */);
    } else if (strcmp(options, "decrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();

        // Perform decryption with the OpenSSL library...
        EVP_DecryptInit_ex(ctx, /* Add your cipher type here */);
    } else {
        logger_log("Invalid options provided.");
        return NULL;
    }

    pthread_mutex_unlock(&lock);

    struct tms endTime; 
    times(&endTime);

    double totalExec = (double)(endTime.tms_utime - startTime.tms_utime) / sysconf(_SC_CLK_TCK);
    logger_log("Total execution time: ");
    char buffer[10];
    sprintf(buffer, "%lf", totalExec);
    logger_log(buffer);

    return ctx; // Return a pointer to the cipher object.
}
```
Please note that this code is just an example and you need to complete it with your own specific requirements regarding OpenSSL usage, error handling, random number generation, external library integration and other aspects of your project. The logger_log function call should be replaced with your logging mechanism if you're using one.
