    sem_t mutex, overflow;
} threadpool;

void *worker(void *arg) {
    threadpool *tp = (threadpool *) arg;
    while (1) {
        sem_wait(&tp->mutex);
        if (*tp->tasks <= 0) {
            break;
        }
        (*tp->tasks)--;
        printf("Processing task...\n"); // replace with actual work 
        sem_post(&tp->overflow);
    }
    return NULL;
}

void init(threadpool *tp, int threads) {
    tp->tasks = (int *) malloc(sizeof(int));
    *tp->tasks = 0;
    sem_init(&tp->mutex, 0, 1);
    sem_init(&tp->overflow, 0, threads);
}

void add_task(threadpool *tp) {
    sem_wait(&tp->overflow);
    sem_wait(&tp->mutex);
    (*tp->tasks)++;
    sem_post(&tp->mutex);
    sem_post(&tp->overflow);
}

void destroy(threadpool *tp, int threads) {
    for (int i = 0; i < threads; ++i) {
        add_task(tp);
    }
    for (int i = 0; i < threads; ++i) {
        sem_wait(&tp->overflow);
    }
}
``` 

In this code, a `threadpool` struct is defined that contains a pointer to the current number of tasks, two semaphores: `mutex` for thread safety and `overflow` for resource management. The `worker` function represents threads in the pool and waits on the `overflow` semaphore until a task is available. It then processes the task (simulated by printing "Processing task...") and signals to the `overflow` semaphore that it has finished, allowing another task to be processed. The `init` function initializes the threadpool with a given number of threads, each running the `worker` function. The `add_task` function adds tasks to the pool by increasing the task count and signaling the `overflow` semaphore, which allows a worker thread to process it. Finally, the `destroy` function signals all workers that there are no more tasks (by adding as many tasks as threads), then waits for all workers to finish.
']

