['```cpp
void increment_shared(std::vector<std::shared_ptr<int>>& vec, std::pair<int, int> p) {
    if (p.first < vec.size()) {
        if (!vec[p.first]) {
            vec[p.first] = std::make_shared<int>(0);
        }
        *vec[p.first] += p.second;
    } else {
        for (std::vector<std::shared_ptr<int>>::size_type i = vec.size(); i < p.first; ++i) {
            vec.push_back(nullptr);
        }
        if (!vec[p.first]) {
            vec.push_back(std::make_shared<int>(0));
        }
        *vec[p.first] += p.second;
    }
}
```
