using boost::asio::ip::tcp;
namespace ssl = boost::asio::ssl;
typedef ssl::stream<tcp::socket> ssl_socket;

class session {
public:
    session(boost::asio::io_service& io_service, boost::asio::ssl::context& context) : socket_(io_service, context) {}

    std::string get(const std::string &server, const std::string &path) {
        try {
            // Set up SSL connection
            socket_.set_verify_mode(boost::asio::ssl::verify_peer);
            socket_.set_verify_callback(boost::bind(&session::verify_certificate, this, _1, _2));

            tcp::resolver resolver(socket_.get_io_service());
            tcp::resolver::query query(server, "443");
            tcp::resolver::iterator endpoint_iterator = resolver.resolve(query);
            boost::asio::connect(socket_.lowest_layer(), endpoint_iterator);

            socket_.handshake(ssl::stream_base::client);

            // Send HTTP GET request
            boost::asio::streambuf request;
            std::ostream request_stream(&request);
            request_stream << "GET " << path << " HTTP/1.0\r\n";
            request_stream << "Host: " << server << "\r\n";
            request_stream << "Accept: */*\r\n";
            request_stream << "Connection: close\r\n\r\n";

            boost::asio::write(socket_, request);

            // Read the response
            boost::asio::streambuf response;
            boost::system::error_code error;
            for (;;) {
                size_t len = boost::asio::read(socket_, response, boost::asio::transfer_at_least(1), error);

                if (response.size() >= 4 && std::equal(response.end()-4, response.end(), "\r\n\r\n")) break;
            }

            return std::string(boost::asio::buffer_cast<const char*>(response.data()), boost::asio::buffer_size(response.data()));
        } catch (std::exception& e) {
            // Handle exception here
            std::cout << "Exception: " << e.what() << "\n";
            return "";
        }
    }
private:
    ssl_socket socket_;
};
```

