```cpp
#include <iostream>
#include <fstream>
#include <mutex>
#include <thread>
#include <vector>

enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

class CustomLogger {
public:
    static LogLevel log_level;
    std::ofstream out;
    std::mutex mtx;

    CustomLogger() : out("log.txt", std::ios::app) {}
    ~CustomLogger() { out.close(); }

    void debug(const std::string& msg) {
        if (log_level <= LogLevel::DEBUG) log(msg, "DEBUG");
    }

    void info(const std::string& msg) {
        if (log_level <= LogLevel::INFO) log(msg, "INFO");
    }

    void warning(const std::string& msg) {
        if (log_level <= LogLevel::WARNING) log(msg, "WARNING");
    }

    void error(const std::string& msg) {
        if (log_level <= LogLevel::ERROR) log(msg, "ERROR");
    }

private:
    void log(const std::string& msg, const std::string& level) {
        std::lock_guard<std::mutex> lock(mtx);
        out << '[' << level << "]: " << msg << '\n';
    }
};
CustomLogger::LogLevel CustomLogger::log_level = LogLevel::INFO;  // default log level

void readConfigFile() {
    std::ifstream in("config.txt");
    if (in) {
        int num;
        in >> num;
        CustomLogger::log_level = static_cast<LogLevel>(num);
    }
}

int main() {
    readConfigFile();

    CustomLogger logger1, logger2;

    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back([&](){
            logger1.debug("This is a debug message");
            logger1.info("This is an info message");
            logger2.warning("This is a warning message");
            logger2.error("This is an error message");
        });
    }
    for (auto& thread : threads) thread.join();
}
