}

public class PhysicsEngineParameters
{
    public float Gravity { get; set; }
}

public class UserInterfaceLayout
{
    public string Theme { get; set; }
}

public static class ConfigurationLoader
{
    private static Dictionary<string, object> cache = new Dictionary<string, object>();

    public static T LoadConfig<T>(string path) where T : class
    {
        if (cache.ContainsKey(path)) return cache[path] as T;

        string jsonString;
        try 
        {
            jsonString = File.ReadAllText(path);
        } 
        catch (Exception ex) when (ex is ArgumentNullException || ex is ArgumentOutOfRangeException || ex is IOException || ex is UnauthorizedAccessException)
        {
            throw new Exception("Failed to load configuration file", ex);
        }

        try 
        {
            T config = JsonConvert.DeserializeObject<T>(jsonString);
            cache[path] = config;
            return config;
        } 
        catch (Exception ex) when (ex is ArgumentNullException || ex is JsonReaderException || ex is JsonSerializationException)
        {
            throw new Exception("Failed to parse configuration file", ex);
        }
    }
}
```
