public ActionResult UpdateElement(string userId, string sessionToken, int sectionId, int elementId, string htmlContent)
{
    // Authenticate the user with a service class
    var authService = new AuthService();
    if (!authService.ValidateSessionToken(userId, sessionToken))
        return Unauthorized();

    lock (_lockObject)  // Ensure only one update at a time
    {
        // Update the element's HTML content using a service class
        var pageUpdateService = new PageUpdateService();
        if (!pageUpdateService.UpdateElement(sectionId, elementId, htmlContent))
            return InternalServerError();

        // Cache the updated content to optimize future requests
        var cacheService = new CacheService();
        cacheService.CacheElement(sectionId, elementId, htmlContent);
    }

    return Ok(new { refreshPage = true });  // Indicate that the page should be refreshed
}
