```java
import java.io.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.common.base.Throwables;
import com.github.rholder.retry.*;

public class StateLoader {
    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);
    private static final int MAX_ATTEMPTS = 3;

    public MoSTState loadStateFromFile(String filePath) {
        Retryer<Object> retryer = RetryerBuilder.<Object>newBuilder()
            .retryIfResult(null)
            .withStopStrategy(StopStrategies.stopAfterAttempt(MAX_ATTEMPTS))
            .build();

        try {
            return retryer.call(() -> {
                FileInputStream fis = new FileInputStream(filePath);
                ObjectInputStream ois = new ObjectInputStream(fis);

                MoSTState state;
                try {
                    Object obj = ois.readObject();

                    if (!(obj instanceof MoSTState)) {
                        throw new ClassCastException("File contains an object that is not of type MoSTState");
                    }

                    state = (MoSTState) obj;
                } finally {
                    ois.close();
                }

                return state;
            });
        } catch (ExecutionException | RetryException e) {
            logger.error("Failed to load state from file: " + filePath, Throwables.getRootCause(e));

            return null;
        }
    }
}
