["Here is a simple JavaScript solution that meets your requirements using standard library functions:

```javascript
// Create Graph class
class Graph {
  constructor() {
    this.vertices = {};
  }

  addVertex(vertex) {
    if (!this.vertices[vertex]) {
      this.vertices[vertex] = [];
      // Set random properties upon insertion
      for (let i = 0; i < 5; ++i) {
        const propertyName = 'property' + i;
        this.vertices[vertex][propertyName] = Math.random();
      }
    }
  }

  addEdge(vertex1, vertex2) {
    if (!this.vertices[vertex1]) this.addVertex(vertex1);
    if (!this.vertices[vertex2]) this.addVertex(vertex2);

    this.vertices[vertex1].push(vertex2);
    this.vertices[vertex2].push(vertex1);
  }
}

// Create GraphDB class
class GraphDB {
  constructor() {
    this.graph = new Graph();
    this.isPaused = false;
    this.dataStream = null;
  }

  processDataStream(stream) {
    this.dataStream = stream;

    // Pause and resume functionality
    let pauseToken, resumeToken;
    const self = this;

    pauseToken = setInterval(() => {
      if (!self.isPaused && !this.dataStream.done) {
        clearInterval(pauseToken);

        // Collect data from a stream and add vertices/edges to the graph
        const data = this.dataStream.next().value;
        for (let i = 0; i < data.length - 1; ++i) {
          self.graph.addVertex(data[i]);
          self.graph.addEdge(data[i], data[i + 1]);
        }

        pauseToken = setInterval(() => {
          if (!self.isPaused && !this.dataStream.done) {
            clearInterval(pauseToken);

            const data = this.dataStream.next().value;
            for (let i = 0; i < data.length - 1; ++i) {
              self.graph.addVertex(data[i]);
              self.graph.addEdge(data[i], data[i + 1]);
            }

            pauseToken = setInterval(() => {
              if (!self.isPaused && !this.dataStream.done) {
                clearInterval(pauseToken);
                const data = this.dataStream.next().value;

                for (let i = 0; i < data.length - 1; ++i) {
                  self.graph.addVertex(data[i]);
                  self.graph.addEdge(data[i], data[i + 1]);
                }
              }
            }, 0);
          }
        }, 0);
      } else if (self.isPaused && this.dataStream.done) {
        clearInterval(pauseToken);
      }
    }, 0);

    return {
      pause: () => {
        self.isPaused = true;
        clearInterval(pauseToken);
      },
      resume: () => {
        self.isPaused = false;
        pauseToken = setInterval(() => {
          if (!self.isPaused && !this.dataStream.done) {
            clearInterval(pauseToken);

            const data = this.dataStream.next().value;
            for (let i = 0; i < data.length - 1; ++i) {
              self.graph.addVertex(data[i]);
              self.graph.addEdge(data[i], data[i + 1]);
            }
          }
        }, 0);
      }
    };
  }
}
```
