["Below is a basic example of a JavaScript module loader using promises that could be extended to handle more advanced scenarios such as caching, error handling, dependency management etc. However, note that this code does not include any kind of optimization or advanced features like fallbacks, version control or dependency resolution etc. It's just a starting point and you will need to add these features yourself based on your requirements:

```javascript
class ModuleLoader {
    constructor() {
        this.loadedModules = {};
    }

    loadModule(url) {
        return new Promise((resolve, reject) => {
            if (this.loadedModules[url]) {
                resolve(this.loadedModules[url]);
            } else {
                let script = document.createElement('script');
                script.src = url;
                script.onload = () => {
                    this.loadedModules[url] = window[getModuleNameFromUrl(url)];
                    resolve(this.loadedModules[url]);
                };
                script.onerror = (e) => reject(e);
                document.body.appendChild(script);
            }
        });
    }
}

function getModuleNameFromUrl(url) {
  const splitPath = url.split('/');
  let moduleFile = splitPath[splitPath.length - 1];
  return moduleFile.substring(0, moduleFile.indexOf('.'));
}
```
You can use it like this:

