```python
class UserManager:
    def __init__(self):
        self.users = {}  # Stores email -> Profile mapping

    def add_or_update_user(self, profile):
        if profile['email'] in self.users:
            print('Updating existing user...')
            self.users[profile['email']].update(profile)
        else:
            print('Adding new user...')
            self.users[profile['email']] = Profile(**profile)

    def assign_generic_pic_url(self):
        for profile in self.users.values():
            if not profile.picture_url:
                profile.picture_url = 'https://via.placeholder.com/150'  # Generic placeholder URL

class Profile:
    def __init__(self, email, picture_url=None):
        self.email = email
        self.picture_url = picture_url or 'https://via.placeholder.com/150'

    def update(self, new_profile):
        for key, value in new_profile.items():
            if hasattr(self, key) and getattr(self, key) != value:
                setattr(self, key, value)
