['Here's a simple implementation using std::chrono for timing, std::mutex for thread safety, and std::atomic_int for atomic operations to protect the cooldown timer. This example uses two attacks - attack 1 if energy is available else attack 2. However, it can be extended with more complex logic for selecting between multiple attacks or adding different types of attacks based on resources.

```C++
#include <iostream>
#include <chrono>
#include <thread>
#include <atomic>
#include <mutex>

class Character {
public:
    void performAttack(bool isActive, int energy) {
        static std::atomic_int cooldown{0}; //cooldown timer
        static std::chrono::time_point<std::chrono::system_clock> lastAttackTime; // time of the last attack
        static constexpr int ATTACK_COOLDOWN = 9; 

        if(!isActive) {
            log("Character is inactive, cannot perform an attack.");
            return;
        }

        std::lock_guard<std::mutex> guard(attackMutex); // locking to prevent concurrent access from multiple threads

        auto now = std::chrono::system_clock::now();
        int elapsedTime = std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count(); //calculating time since the last attack

        if (elapsedTime < cooldown) { 
            log("Cooldown not yet finished.");
            return;
        }

        if (energy < 5) { // energy threshold for using special attacks can be adjusted as needed
            log("Insufficient energy points, cannot perform an attack.");
            return;
        }

        lastAttackTime = now;
        cooldown = ATTACK_COOLDOWN; 

        std::thread t([&]() { // using a separate thread to simulate the time taken for performing the attack
            std::this_thread::sleep_for(std::chrono::seconds(1)); 
            --cooldown;
        });

        t.detach();

        if (energy >= 5) { //attack selection based on energy
            log("Performing special attack.");
            return;
        } else {
            log("Performing basic attack.");
            return;
        }
    }

private:
   std::mutex attackMutex; 

   void log(const std::string& message) { //log function
      std::cout << message << std::endl;
   }
};
```
To use it:
```C++
int main() {
    Character character;
    character.performAttack(true, 5);
    return 0;
}
```
Please replace the energy threshold and attack selection logic as needed according to your game's requirements. Also, make sure you are using multithreading correctly in your actual code to avoid race conditions or data corruption.
']

