using System;

public class RandomValueGenerator {
    private float minValue = Single.MinValue;
    private float maxValue = Single.MaxValue;

    public float GetRandomFloat() {
        Random rand = new Random();
        double fraction = (rand.NextDouble() * (maxValue - minValue)) + minValue;

        if ((float)fraction > maxValue) 
            return maxValue;

        if ((float)fraction < minValue) 
            return minValue;

        return (float) fraction;
    }

    public int GetRandomInt() {
        Random rand = new Random();
        double fraction = (rand.NextDouble() * (maxValue - minValue)) + minValue;

        if ((int)Math.Round(fraction) > maxValue) 
            return (int)maxValue;

        if ((int)Math.Round(fraction) < minValue) 
            return (int)minValue;

        return (int) Math.Round(fraction);
    }

    public void AdjustRange(float newMin, float newMax) {
        if (newMin <= newMax) {
            this.minValue = newMin;
            this.maxValue = newMax;
        } else {
            Console.WriteLine("Invalid range. Minimum value cannot be greater than maximum value.");
        }
    }

    public float GetAdjustedValue(float value) {
        if (value > maxValue) {
            while (value > maxValue) {
                value -= (maxValue - minValue);
            }
        } else if (value < minValue) {
            while (value < minValue) {
                value += (maxValue - minValue);
            }
        }

        return value;
    }

    public override string ToString() {
        return $"Current range is from {minValue} to {maxValue}";
    }
}
