['Here is an example of how you might approach creating such a function in C. This solution does not handle special or space characters directly due to limitations of the question and `sprintf`, but it can be extended to do so if required:

```c
#include <string.h>
#include <ctype.h>

char* modifyExtension(const char *filename) {
    static char newFilename[256];  // Create a static array for the result
    strncpy(newFilename, filename, sizeof(newFilename)-1);  // Copy the original filename to the buffer

    if (strlen(filename) >= sizeof(newFilename)) {  // Truncate the string if it is too long
        newFilename[sizeof(newFilename)-1] = '\0';
    }

    char *dotPos = strrchr(newFilename, '.');  // Find the last dot in the filename

    int count = 0;
    for (int i=0; newFilename[i]; i++) {
        if (isalnum((unsigned char)newFilename[i])) {
            count += newFilename[i];  // Add ASCII value of character to the count
        }
    }

    char sequence[6];  // Buffer for the sequence number, plus one extra spot for null terminator
    sprintf(sequence, "%05d", count % 100000);  // Generate sequence number

    if (dotPos) {  // If filename has an extension, append number after it
        strcat(newFilename, sequence);  
    } else {  // If no extension, add ".ext" followed by the number
        sprintf(newFilename+strlen(newFilename), ".ext%s", sequence);
    }

    return newFilename;
}
```
This function first copies the filename into a static buffer. It then determines whether the filename has an extension, and if so, appends the sequence number to it. If there is no dot in the filename, it appends ".ext" followed by the sequence number. The `%05d` format specifier ensures that the number always occupies at least 5 digits, adding leading zeros as necessary.
']

