#include <openssl/aes.h>
#include <pthread.h>

static pthread_once_t once = PTHREAD_ONCE_INIT;
static pthread_mutex_t *lockarray;

void crypto_init(void) {
    OpenSSL_add_all_algorithms();

    lockarray = OPENSSL_malloc(CRYPTO_num_locks() * sizeof(pthread_mutex_t));
    for (int i = 0; i < CRYPTO_num_locks(); i++) {
        pthread_mutex_init(&lockarray[i], NULL);
    }

    CRYPTO_set_id_callback(NULL); // optional, but useful
    CRYPTO_set_locking_callback(lock_cb);
}

void crypto_deinit(void) {
    if (lockarray != NULL) {
        for (int i = 0; i < CRYPTO_num_locks(); i++) {
            pthread_mutex_destroy(&lockarray[i]);
        }

        OPENSSL_free(lockarray);
    }

    EVP_cleanup();
}

void lock_cb(int mode, int n, const char *file, int line) {
    if (mode & CRYPTO_LOCK) {
        pthread_mutex_lock(&(lockarray[n]));
    } else {
        pthread_mutex_unlock(&(lockarray[n]));
    }
}

void add_crypto_primitives() {
    if (pthread_once(&once, crypto_init) != 0) {
        // handle error here
    }

    // Add ciphers and digest algorithms
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha3_256());
