#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES256_CBC_Context;

AES256_CBC_Context* create_aes256_cbc(const char *password, const unsigned char *salt) {
    if (password == NULL || salt == NULL) return NULL;

    AES256_CBC_Context *context = malloc(sizeof(*context));
    if (context == NULL) return NULL;

    // Generate secure random IV
    if (!RAND_bytes(context->iv, sizeof(context->iv))) {
        free(context);
        return NULL;
    }

    // Derive encryption key with PBKDF2
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, strlen((char*)salt), 10000, EVP_aes_256_cbc(), sizeof(context->key), context->key)) {
        free(context);
        return NULL;
    }

    // Initialize cipher context
    if (!(context->ctx = EVP_CIPHER_CTX_new())) {
        free(context);
        return NULL;
    }

    if (EVP_EncryptInit_ex(context->ctx, EVP_aes_256_cbc(), NULL, context->key, context->iv) <= 0 || 
        EVP_CIPHER_CTX_set_padding(context->ctx, 1) <= 0) {
        free(context);
        return NULL;
    }

    return context;
}

void cleanup_aes256_cbc(AES256_CBC_Context *context) {
    if (context == NULL) return;

    EVP_CIPHER_CTX_free(context->ctx);
    OPENSSL_cleanse(context, sizeof(*context));
    free(context);
}
