public class WebsiteManager {
    private string WebConfigPath(string directory) {
        return Path.Combine(directory, "web.config");
    }

    public async Task<Process> AddAndStartWebsiteAsync(string directory, string siteName) {
        if (!File.Exists(WebConfigPath(directory))) {
            Console.WriteLine($"Warning: web.config missing in {siteName}");
            return null;
        }

        var uri = new UriBuilder("http", Environment.MachineName, 80) { Path = siteName };
        ProcessStartInfo startInfo = new ProcessStartInfo {
            FileName = "dotnet", // replace this with your .NET runtime
            Arguments = $"{uri} --urls={uri}"
        };

        try {
            var process = Process.Start(startInfo);
            await process.WaitForExitAsync();
            Console.WriteLine($"Success: website started at {uri}");
            return process;
        } catch (Exception ex) {
            Console.Error.WriteLine(ex.Message);
            return null;
        }
    }

    public async Task AddAndStartWebsitesAsync(string[] directories, string[] siteNames) {
        if (directories.Length != siteNames.Length) {
            throw new ArgumentException("Directories and Sitenames arrays must be of the same length");
        }

        var tasks = Enumerable.Range(0, directories.Length).Select(i => AddAndStartWebsiteAsync(directories[i], siteNames[i]));
        await Task.WhenAll(tasks);
    }
}
