    pthread_mutex_t lock;
    Configuration *config;
    Connection *connection;
    CallbackHandler *callback;
} Session;

int initializeSession(Session *session) {
    if (pthread_mutex_init(&session->lock, NULL) != 0) {
        return -1; // Could not initialize lock
    }

    if (session->config == NULL || session->connection == NULL || session->callback == NULL) {
        pthread_mutex_destroy(&session->lock);
        return -2; // Session is not properly initialized
    }

    if (!isConfigurationValid(session->config)) {
        pthread_mutex_destroy(&session->lock);
        return -3; // Configuration is invalid
    }

    if (!isConnectionEstablished(session->connection)) {
        pthread_mutex_destroy(&session->lock);
        return -4; // Connection could not be established
    }

    if (!isCallbackHandlerValid(session->callback)) {
        pthread_mutex_destroy(&session->lock);
        return -5; // Callback handler is invalid
    }

    return 0; // Session successfully initialized
}

bool isConfigurationValid(Configuration *config) {
