            {
                var fileTransferUtility = new TransferUtility(s3Client);

                // Upload a file, file name is used as the object key name.
                var uploadRequest = new TransferUtilityUploadRequest
                {
                    BucketName = bucketName,
                    FilePath = filePath,
                    Key = Path.GetFileName(filePath)
                };

                // Optionally set any optional metadata
                uploadRequest.Metadata["x-amz-meta-title"] = "someTitle";

                var startTime = DateTime.UtcNow; 
                fileTransferUtility.Upload(uploadRequest);
                var endTime = DateTime.UtcNow;

                // Generate and store metadata record
                var newMetadataRecord = new FileMetadata()
                {
                    FilePath = filePath,
                    UploadTime = (endTime - startTime)
                };

                metadataRecords.Add(newMetadataRecord);
            }
        }
        catch (AmazonS3Exception e)
        {
            Console.WriteLine("Error encountered on server. Message:'{0}' when writing an object", e.Message);
        }
        catch (Exception e)
        {
            Console.WriteLine("Unknown error encountered on server. Message:'{0}' when writing an object", e.Message);
        }

        return metadataRecords;
    }
}
```
This code assumes that you have set up your AWS credentials correctly and that the files specified by the file paths exist. Note that in a real-world application, you should add more robust error handling to deal with potential network issues and other exceptions. Also, please replace `your_bucket_name` and `RegionEndpoint.USEast1` with your actual bucket name and region endpoint respectively.
']

['```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;

public class MessageProcessor
{
    private static readonly TimeSpan CacheRefreshInterval = TimeSpan.FromMinutes(10);

    private ConcurrentDictionary<string, string> cache = 
        new ConcurrentDictionary<string, string>();
    private DateTime lastCacheRefresh;
    private ReaderWriterLockSlim cacheLock = new ReaderWriterLockSlim();

    public string DecryptAndHashMessage(string encryptedBase64String, byte[] key, byte[] iv)
    {
        try
        {
            var messageBytes = Convert.FromBase64String(encryptedBase64String);
            string hashed;

            cacheLock.EnterUpgradeableReadLock();
            try
            {
                if (DateTime.UtcNow - lastCacheRefresh > CacheRefreshInterval)
                {
                    RefreshCache();
                }

                var decryptedMessage = DecryptTripleDes(messageBytes, key, iv);
                hashed = BitConverter.ToString(MD5.Create().ComputeHash(decryptedMessage));
            }
            finally
            {
                cacheLock.ExitUpgradeableReadLock();
            }

            return hashed;
        }
        catch (Exception ex)
        {
            // handle exception
            throw;
        }
    }

    private void RefreshCache()
    {
        cacheLock.EnterWriteLock();
        try
        {
            if (DateTime.UtcNow - lastCacheRefresh > CacheRefreshInterval)
            {
                cache = new ConcurrentDictionary<string, string>();
                lastCacheRefresh = DateTime.UtcNow;
            }
        }
        finally
        {
            cacheLock.ExitWriteLock();
        }
    }

    private byte[] DecryptTripleDes(byte[] encryptedMessage, byte[] key, byte[] iv)
    {
        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            var transform = tripleDes.CreateDecryptor(key, iv);

            return transform.TransformFinalBlock(encryptedMessage, 0, encryptedMessage.Length);
        }
    }
}
```
