Write a C# function that loads data from a compressed binary file and deserializes it into a custom data structure. The function should handle different compression formats (e.g., GZIP, LZ4) dynamically based on the file extension. Additionally, implement a caching mechanism to avoid redundant deserialization for files that have been loaded recently. Ensure that the solution is efficient in terms of memory usage and load time, considering the potential size of the files.

```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Runtime.Serialization.Formatters.Binary;

public class DataDeserializer
{
    private static readonly TimeSpan CacheTtl = TimeSpan.FromMinutes(10);
    private static readonly Dictionary<string, DateTime> LastAccessed = new();
    private static readonly ConcurrentDictionary<string, object> Cache = new();

    public T Deserialize<T>(string filePath) where T : class
    {
        if (Cache.TryGetValue(filePath, out var cached))
        {
            return cached as T;
        }

        var accessedTime = LastAccessed.ContainsKey(filePath) ? LastAccessed[filePath] : DateTime.MinValue;

        if ((DateTime.UtcNow - accessedTime) > CacheTtl)
        {
            object result = DeserializeFromBinaryFile(filePath);
            LastAccessed[filePath] = DateTime.UtcNow;
            Cache[filePath] = result;
            return result as T;
        }

        throw new InvalidOperationException("Data is too old, please reload.");
    }

    private object DeserializeFromBinaryFile(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        using (var decompressionStream = GetDecompressionStream(stream, Path.GetExtension(filePath)))
        {
            var formatter = new BinaryFormatter();
            return formatter.Deserialize(decompressionStream);
        }
    }

    private Stream GetDecompressionStream(Stream stream, string extension)
    {
        switch (extension.ToLower())
        {
            case ".gz":
                return new GZipStream(stream, CompressionMode.Decompress);
            case ".lz4":
                // Implement LZ4 decompression logic
                throw new NotImplementedException("LZ4 decompression not implemented yet.");
            default:
                return stream;
        }
    }
}
```

