const crypto = require('crypto');
const https = require('https');
const fs = require('fs');

// Initialize ciphers and hashes
const cipherMap = new Map();
cipherMap.set('AES', 'aes-256-cbc'); // use your own key here
cipherMap.set('CAMELLIA', 'camellia-128-ecb'); // use your own key here
const digestMap = new Map();
digestMap.set('MD5', 'md5');
