async function uploadAndEncrypt(url, cipherName = 'AES', hashName = 'SHA') {
    let file;
    try {
        file = fs.createWriteStream("./tempFile");
        https.get(url, function (response) {
            response.pipe(file);
            file.on('finish', function () {
                file.close(); // close() is async, call callback after close completes.
            });
        }).on('error', function (err) { // Handle errors
            fs.unlink("./tempFile"); // Delete the file async. (But we don't check the result)
            console.error(err.message);
        });
    } catch (e) {
        console.log(`Error during upload: ${e}`);
        return null;
    }

    try {
        let encryptedFilePath = './encryptedFile'; // Temporary path
        const cipher = crypto.createCipheriv(cipherMap.get(cipherName), 'mySecretKey'); // Use your own key here
        const input = fs.createReadStream('./tempFile');
        const output = fs.createWriteStream(encryptedFilePath);

        input.pipe(cipher).pipe(output);

        let hash = crypto.createHash(digestMap.get(hashName));
        return new Promise((resolve, reject) => {
            output.on('finish', function () { 
                resolve(encryptedFilePath);
            });

            // Feed data to the hashing function and get digest in hex format
            hash.setEncoding('hex');

            input.pipe(hash).pipe(output);
        }).catch((error) => {
            console.log(`Error during encryption: ${error}`);
            return null;
        });
    } finally {
        fs.unlink("./tempFile"); // Delete the file async. (But we don't check the result)
    }
}
```
