using System;
using System.Collections.Generic;
using UnityEngine;

public class ResourceManager
{
    private float minRange = 0f;
    private float maxRange = 1f;

    public void AdjustRange(float newMin, float newMax)
    {
        if (newMin == newMax)
            throw new ArgumentException("The minimum and maximum values cannot be the same.");

        minRange = newMin;
        maxRange = newMax;

        // Handle case where range crosses the existing boundary by wrapping around
        if (minRange > maxRange)
        {
            float temp = minRange;
            minRange = maxRange;
            maxRange = temp;
        }
    }

    public float GetAdjustedValue(float value)
    {
        // Wrap values that fall outside the range back into the range
        if (value < minRange)
            return maxRange - (minRange - value);

        if (value > maxRange)
            return minRange + (value - maxRange);

        return value;
    }

    public float GetRandomFloat()
    {
        System.Random rand = new System.Random();
        double val = rand.NextDouble();
        return (float)(minRange + val * (maxRange - minRange));
    }

    public int GetRandomInt()
    {
        System.Random rand = new System.Random();
        return rand.Next((int)Math.Ceiling(minRange), (int)Math.Floor(maxRange));
    }

    public override string ToString()
    {
        return $"Current range: [{minRange}, {maxRange}]";
    }
}
