import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.xml.bind.*;

public class FileProcessor {
    private final ConcurrentHashMap<String, String> hashCache = new ConcurrentHashMap<>();
    private static final long DEFAULT_CACHE_REFRESH_INTERVAL = 1000; // 1 second
    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private volatile long cacheRefreshInterval = DEFAULT_CACHE_REFRESH_INTERVAL;

    public FileProcessor(long cacheRefreshInterval) {
        this.cacheRefreshInterval = cacheRefreshInterval > 0 ? cacheRefreshInterval : DEFAULT_CACHE_REFRESH_INTERVAL;
        scheduler.scheduleAtFixedRate(this::refreshCache, 0, this.cacheRefreshInterval, TimeUnit.MILLISECONDS);
    }

    private void refreshCache() {
        hashCache.clear();
    }

    public List<String> processAndCacheFiles(String[] filenames) {
        List<String> hashes = new ArrayList<>();
        for (String filename : filenames) {
            String hash = hashCache.computeIfAbsent(filename, this::getMD5Hash);
            hashes.add(hash);
        }
        return hashes;
    }

    private String getMD5Hash(String filename) {
        try (FileInputStream fis = new FileInputStream(Paths.get(filename).toFile())){
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int numOfBytesRead;
            while ((numOfBytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, numOfBytesRead);
            }
            byte[] digest = md.digest();
            return DatatypeConverter.printHexBinary(digest).toLowerCase();
        } catch (IOException | NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to process file: " + filename, e);
        }
    }
}
```
This code creates a thread that periodically clears the cache. The actual implementation of how many digits are appended to the filename would depend on your specific use case and might involve additional logic or an external library. Also note that this code does not handle any exceptions gracefully, for instance by returning some default value instead of throwing an exception. If you need help with handling exceptions, please let me know.
