["Sure, here's an example of how you might implement this in C:

```c
#include <stdlib.h>
#define MAX_SESSIONS 100 // Change as needed

typedef struct session {
    int id;
    struct session *next;
} Session;

int manageSession(Session **head, int *count, int newId) {
    Session *newSession = (Session *)malloc(sizeof(Session));

    if(newSession == NULL) return -1; // Out of memory

    newSession->id = newId;
    newSession->next = *head;
    *head = newSession;
    (*count)++;

    while(*count > MAX_SESSIONS){
        Session *temp = *head, *prev = NULL;

        // Traverse to the last node in the list
        while(temp->next != NULL){
            prev = temp;
            temp = temp->next;
        }

        if (prev != NULL) 
            prev->next = NULL;

        free(temp);
        (*count)--;
    }

    // Ensure list is sorted in ascending order by session ID
    Session *current, *index;
    int tempId;

    for (current = *head; current != NULL; current = current->next) {
        for (index = current->next; index != NULL; index = index->next) {
            if (current->id > index->id) {
                tempId = current->id;
                current->id = index->id;
                index->id = tempId;
            }
        }
    }

    return 0; // Success
}
```
This function creates a new session node with the provided session ID and inserts it at the head of the linked list. If adding the new session would exceed the maximum number of sessions, the function removes the oldest session (at the end of the list) to make room for the new one. The function then sorts the list in ascending order by session ID.
"]

