["Here's a basic example for this task using OpenSSL library.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} aes256cbc_context;

int initialize(aes256cbc_context *ctx, const char* password, int pass_len, const unsigned char *salt) {
    if (ctx == NULL || password == NULL || salt == NULL) return 0; // Null pointers check

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char *)password, pass_len, 10000, ctx->key, ctx->iv)) {
        return 0; // Error during key derivation
    }

    if (!RAND_bytes(ctx->iv, sizeof(ctx->iv))) {
        return 0; // Error generating secure random IV
    }

    EVP_CIPHER_CTX_init(ctx->ctx);
    return 1;
}

void cleanup(aes256cbc_context *ctx) {
    if (ctx == NULL) return; // Null pointer check

    OPENSSL_cleanse(ctx->key, sizeof(ctx->key));
    OPENSSL_cleanse(ctx->iv, sizeof(ctx->iv));
    EVP_CIPHER_CTX_free(ctx->ctx);
}
```
This code first initializes a new cipher context, then derives the key and IV using PBKDF2. The key and IV are securely wiped from memory after they're no longer needed to avoid potential memory dumps revealing sensitive information. 

