#include <string.h>

typedef struct {
    int id;
    long offset;
    double value;
} Record;

void* allocate_and_initialize(int max_records, FILE* log_file) {
    // Lock to ensure thread safety
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    Record** records = malloc(sizeof(Record*) * max_records);
    long* offsets = calloc(max_records, sizeof(long));
    int* keys = malloc(sizeof(int) * max_records);
    double* values = calloc(max_records, sizeof(double));

    // Check for allocation failures
    if(!records || !offsets || !keys || !values) {
        handle_error("Memory allocation failed", log_file);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(0));
    for(int i = 0; i < max_records; ++i) {
        records[i] = malloc(sizeof(Record));

        // Check for allocation failure
        if(!records[i]) {
            handle_error("Memory allocation failed", log_file);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i]->id = i;
        offsets[i] = rand();  // Using openssl library for random number generation
        keys[i] = RAND_bytes(keys + i, sizeof(int));  // Generating cryptographic secure random numbers
        values[i] = (double)rand() / (double)RAND_MAX;  // Initializing with a random double value

        records[i]->offset = offsets + i;
        records[i]->value = values + i;
    }

    pthread_mutex_unlock(&lock);
    return (void*)records;
}
