// Define the structure for the Octree node
typedef struct Node {
    char* data;
    struct Node** children;
} Node;

Node* octreeInit(int featureSize, int numLeafNodes, int dataCapacity) {
    // Allocate memory dynamically for the root node of the octree
    Node* root = (Node*)malloc(sizeof(Node));

    if(root == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Allocate memory for the data in each node of the octree
    root->data = (char*)malloc((featureSize + 1) * sizeof(char));  // Allow space for null terminator

    if(root->data == NULL) {
        printf("Memory allocation failed\n");
        free(root);
        return NULL;
    }

    // Allocate memory for the children of each node of the octree
    root->children = (Node**)malloc(numLeafNodes * sizeof(Node*));

    if(root->children == NULL) {
        printf("Memory allocation failed\n");
        free(root->data);
        free(root);
        return NULL;
    }

    // Update the octree's capacity
    int totalCapacity = numLeafNodes * dataCapacity;  // Example, actual calculation may vary based on your specific needs

    printf("Octree initialized with %d nodes. Total capacity: %d\n", numLeafNodes, totalCapacity);

    return root;
