typedef struct Record {
    int id;
    long offset;
    int key;
    double value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Record *records = NULL;
int recordCount = 0, capacity = 10;

void init() {
    srand(time(NULL));  /* Seed random number generator */
}

/* Allocate memory and initialize a new record */
Record* createRecord(int id, long offset, int key, double value) {
    Record *record = (Record*) malloc(sizeof(Record));
    if (record == NULL) {
        logError("Memory allocation failed");
        return NULL;
    }

    record->id = id;
    record->offset = offset;
    record->key = key;
    record->value = value;

    return record;
}

void addRecord(int id, long offset, int key, double value) {
    pthread_mutex_lock(&lock); /* Acquire lock */

    if (recordCount >= capacity) {
        capacity *= 2;  /* Increase capacity when reaching limit */

        Record *temp = realloc(records, capacity * sizeof(Record));
        if (temp == NULL) {
            logError("Reallocation failed");
            pthread_mutex_unlock(&lock);
            return;
        } else {
            records = temp;
        }
    }

    Record* record = createRecord(id, offset, key, value);
    if (record == NULL) {
        logError("Failed to create new record");
        pthread_mutex_unlock(&lock);
        return;
    }

    records[recordCount++] = *record;

    free(record);  /* Free dynamically allocated memory */

    pthread_mutex_unlock(&lock);  /* Release lock */
}

void readConfigFile(char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        logError("Failed to open configuration file");
        return;
    }

    int id, key;
    long offset;
    double value;

    while (!feof(file)) {  /* Read from the config file */
        if (fscanf(file, "%d %ld %d %lf", &id, &offset, &key, &value) != 4) {
            logError("Configuration file format incorrect");
            return;
        }

        addRecord(id, offset, key, value);
    }

    fclose(file);  /* Close the config file */
}
```
