```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#define SALT_LEN 8 // This is a placeholder, usually should be high enough to avoid collisions

typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES256_CTX;

AES256_CTX* aes256_init(const char* password, const unsigned char* salt, size_t iterations) {
    if (password == NULL || salt == NULL || strlen(password) == 0 || SALT_LEN <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    AES256_CTX* aes = malloc(sizeof(*aes));
    if (aes == NULL) {
        fprintf(stderr, "Failed to allocate memory for context\n");
        return NULL;
    }

    // Generating secure, non-repeating IV. The length of the IV is determined by EVP_CIPHER_CTX_iv_length 
    if (RAND_bytes(aes->iv, sizeof(aes->iv)) <= 0) {
        fprintf(stderr, "Failed to generate secure random bytes\n");
        free(aes);
        return NULL;
    }

    // Deriving key using PBKDF2
    if (PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, SALT_LEN, iterations, EVP_MAX_KEY_LENGTH, aes->key) <= 0) {
        fprintf(stderr, "Failed to generate key\n");
        free(aes);
        return NULL;
    }

    // Initializing cipher context
    aes->ctx = EVP_CIPHER_CTX_new();
    if (aes->ctx == NULL) {
        fprintf(stderr, "Failed to create new cipher context\n");
        free(aes);
        return NULL;
    }

    // Initialize the cipher with key and IV
    EVP_EncryptInit_ex(aes->ctx, EVP_aes_256_cbc(), NULL, aes->key, aes->iv);

    return aes;
}

void aes256_cleanup(AES256_CTX* ctx) {
    if (ctx == NULL) {
        return;
    }
    EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_cleanse(ctx->key, sizeof(ctx->key));
    OPENSSL_cleanse(ctx->iv, sizeof(ctx->iv));
    free(ctx);
}
```

Note: The key derivation function PKCS5_PBKDF2_HMAC_SHA1 uses SHA1 hashing which is less secure than modern standards like SHA256 or SHA3. If you plan to use this for real-world applications, consider switching to a more secure option such as PBKDF2_HMAC_SHA256.
']

