['Here is a C# code solution for the given problem:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DynamicValueManager
{
    private float minValue = float.MinValue;
    private float maxValue = float.MaxValue;

    private float currentAverage = 0f;
    private int totalValuesGenerated = 0;

    public float GetRandomFloat()
    {
        var value = (float)(new Random().NextDouble() * (maxValue - minValue) + minValue);

        UpdateStatistics(value);
        return value;
    }

    public int GetRandomInt()
    {
        var value = new Random().Next((int)minValue, (int)maxValue + 1);

        UpdateStatistics(value);
        return value;
    }

    private void UpdateStatistics(float value)
    {
        Interlocked.Increment(ref totalValuesGenerated);
        currentAverage = ((currentAverage * (totalValuesGenerated - 1)) + value) / totalValuesGenerated;
    }

    public void AdjustRange(float newMin, float newMax)
    {
        lock(this){
            if(newMin > newMax) return;

            minValue = newMin;
            maxValue = newMax;
        }
    }

    public float GetAdjustedValue(float value)
    {
        var adjustedValue = value;

        lock (this)
        {
            while (adjustedValue < minValue || adjustedValue > maxValue) 
            {
                if (adjustedValue < minValue)
                    adjustedValue += Math.Abs(minValue - maxValue);
                else if (adjustedValue > maxValue)
                    adjustedValue -= Math.Abs(maxValue - minValue);
            }
        }

        return adjustedValue;
    }

    public override string ToString() => $"Current range: [{minValue}, {maxValue}]";

    public IEnumerable<float> CalculateAdjustedValues(IEnumerable<float> values) =>
        values.Select(v => GetAdjustedValue(v));

    public void MergeRanges(DynamicValueManager other)
    {
        lock (this){
            if(other.minValue < minValue || other.maxValue > maxValue)
            {
                minValue = Math.Min(minValue, other.minValue);
                maxValue = Math.Max(maxValue, other.maxValue);
            }
        }
    }

    public float CurrentAverage => currentAverage;

    public void ResetStatistics()
    {
        lock (this)
        {
            totalValuesGenerated = 0;
            currentAverage = 0f;
        }
    }
}
```
This class fulfills all the requirements of the given problem. The `GetRandomFloat` and `GetRandomInt` methods generate random values within a dynamic range by using the Random class's Next method. AdjustRange adjusts the value dynamically ensuring that newMin is less than or equal to newMax. The GetAdjustedValue method adjusts a given float value to fit in the current range. ToString method displays the current range. CalculateAdjustedValues generates and returns adjusted values for the provided collection of floats. MergeRanges merges the current range with another instance ensuring that they don't overlap unnecessarily. The property CurrentAverage provides the average of all generated values from start to this call, ResetStatistics clears any statistics related to value generation. Thread safety is ensured by locking and using Interlocked operations for concurrency control.
']

