typedef struct {
    void* data;
} Element;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    Element** elements;
} HashTable;

int hash(void* data, size_t capacity) {
    // Replace this with your actual hash function.
