}

HashTable* hashTableResize(HashTable* table, size_t maxElements, void* data) {
    pthread_mutex_lock(&table->mutex); // Ensure thread safety

    if (table->count >= maxElements) {
        printf("[Warning] Hash Table is close to its maximum capacity\n");
        pthread_mutex_unlock(&table->mutex); 
        return table; // don't resize if we are at or over the limit
    }

    size_t newCapacity = maxElements * 2; // double the capacity when it is about to reach maximum.
    Element** tempElements = malloc(sizeof(Element*) * newCapacity);
    for (size_t i = 0; i < newCapacity; ++i) {
        tempElements[i] = NULL;
    }

    printf("[Info] Resizing Hash Table from %zu to %zu\n", table->capacity, newCapacity);

    for (size_t i = 0; i < table->capacity; ++i) { // rehash all existing elements
        if (table->elements[i] != NULL) {
            int index = hash(table->elements[i]->data, newCapacity); 
            while (tempElements[index] != NULL) {  // handle collisions
                index = (index + 1) % newCapacity;
            }
            tempElements[index] = table->elements[i];  // insert element into new location
        }
    }

    free(table->elements); // free old elements memory
    table->elements = tempElements; 
    table->capacity = newCapacity;

    pthread_mutex_unlock(&table->mutex);

    return table;
}
```
Remember to adapt the code according to your actual requirements and handle edge cases. Also, this implementation assumes that your hash function (`hash()`) and external string processing library is available in `external_string_library.h`. If they aren't, you need to include them appropriately and provide a proper implementation for them.
