['Here is the C part of the solution with DNS resolution and MD5 hash calculation:
```C
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <sys/resource.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#define CHUNK 1024

u_char* resolveDNS(const char *hostname) {
    struct hostent *he;
    u_char* ip = (u_char*)malloc(INET6_ADDRSTRLEN);

    if ((he=gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        exit(1);
    }

    struct in_addr **addr_list = (struct in_addr **)he->h_addr_list;

    for(int i = 0; addr_list[i] != NULL; i++) {
        strcpy((char *)ip, inet_ntoa(*addr_list[i]));
        return ip;
    }

    free(ip);
    exit(1);
}

unsigned char* calculateMD5(const char *filename) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[CHUNK];

    FILE *inFile = fopen (filename, "rb");

    if (inFile == NULL) {
        printf ("%s can't be opened.\n", filename);
        exit(1);
    }

    MD5_Init (&mdContext);

    while ((bytes = fread (data, 1, CHUNK, inFile)) != 0) {
        MD5_Update (&mdContext, data, bytes);
    }

    MD5_Final (hash, &mdContext);

    fclose(inFile);

    return hash;
}
```
