    int RNTI;
    struct CRC_INDICATION_REL8_TAG { bool CRCFLAG; } CRC_INDICATION_REL8_TAG;
};

class DynamicNFAPduList {
private:
    float minValue, maxValue;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
public:
    DynamicNFAPduList(float minVal=0.0f, float maxVal=1.0f) : minValue(minVal), maxValue(maxVal) {}
    ~DynamicNFAPduList() = default;

    void addElement(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        pdus.push_back(pdu);
        validate();
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> getAllElements() const { return pdus; }

    NFAPI_CRC_INDICATION_PDU_T& operator[](size_t index) { 
        if (index >= pdus.size()) throw std::out_of_range("Index out of range");
        return pdus[index]; 
    }

    float GetRandomFloat() const { return minValue + static_cast<float>(rand()) / (static_cast<float>(RAND_MAX/(maxValue - minValue))); }

    int GetRandomInt() const { return rand() % static_cast<int>((maxValue-minValue)+1) + static_cast<int>(minValue); }

    void AdjustRange(float newMin, float newMax) {
        if (newMin > newMax) throw std::invalid_argument("Invalid range");
        minValue = newMin; maxValue = newMax;
    }

    float GetAdjustedValue(float value) const {
        while (value < minValue || value > maxValue) 
            value -= static_cast<int>((value-minValue)/(maxValue-minValue))*(maxValue-minValue);

        return value;
    }

    std::string toString() const { 
        return "Min Value: " + std::to_string(minValue) + ", Max Value: " + std::to_string(maxValue); 
    }

private:
    void validate() {
        std::vector<int> rnti;
        for (auto& pdu : pdus) {
            if (std::find(rnti.begin(), rnti.end(), pdu.RNTI) != rnti.end()) 
                throw std::runtime_error("Inconsistent RNTI value found");
            else 
                rnti.push_back(pdu.RNTI);
        }
    }
};
```
