```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Data.SqlClient;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using System.Data;

public class StringProcessor
{
    private ConcurrentDictionary<string, string> cache = new ConcurrentDictionary<string, string>();
    private readonly TimeSpan refreshPeriod = TimeSpan.FromMinutes(5);
    private DateTime lastRefreshTime = DateTime.MinValue;
    private object lockObject = new object();

    public async Task<DataTableReader> ProcessBatchOfStringsAsync(string[] strings, string connectionString)
    {
        await EnsureCacheUpToDateAsync(strings, connectionString);

        using (SqlConnection conn = new SqlConnection(connectionString))
        using (SqlCommand cmd = new SqlCommand("SELECT * FROM Hashes", conn))
        {
            await conn.OpenAsync();
            return await cmd.ExecuteReaderAsync();
        }
    }

    private async Task EnsureCacheUpToDateAsync(string[] strings, string connectionString)
    {
        if (DateTime.UtcNow - lastRefreshTime < refreshPeriod) 
            return;

        lock (lockObject)
        {
            // Check again within the locked section to prevent unnecessary updates
            if (DateTime.UtcNow - lastRefreshTime < refreshPeriod) 
                return;

            foreach (string str in strings)
            {
                string hash = ComputeHash(str);
                cache[str] = hash;
                SaveToDbAsync(hash, connectionString).Wait(); // Fire and forget
            }

            lastRefreshTime = DateTime.UtcNow;
        }
    }

    private async Task SaveToDbAsync(string hash, string connectionString)
    {
        using (SqlConnection conn = new SqlConnection(connectionString))
        using (SqlCommand cmd = new SqlCommand("INSERT INTO Hashes VALUES (@hash)", conn))
        {
            await conn.OpenAsync();

            cmd.Parameters.AddWithValue("@hash", hash);

            await cmd.ExecuteNonQueryAsync();
        }
    }

    private string ComputeHash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
                sb.Append(hashBytes[i].ToString("X2"));

            return sb.ToString();
        }
    }
}
``` 
This code uses the `ConcurrentDictionary` class to safely manage the cache of MD5 hashes, and locks with a lock object to ensure thread safety when checking for updates or updating the cache. It also uses asynchronous operations whenever possible to avoid blocking the main thread while waiting for database responses. It handles exceptions by letting them bubble up and being caught where they are handled appropriately in your calling code.
']

