['Here is a sample code that fulfills all your requirements but needs to be adapted into an existing library. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <assert.h>

typedef struct {
    pthread_mutex_t lock;
} StringManager;

void InitStringManager(StringManager* manager) {
    assert(manager != NULL);
    pthread_mutex_init(&manager->lock, NULL);
}

size_t CopyStringWithLimit(char *src, size_t limit, char **dst) {
    static StringManager manager;
    static int isInitialized = 0;

    if (!isInitialized) {
        InitStringManager(&manager);
        isInitialized = 1;
    }

    // Lock the resource for mutual exclusion
    pthread_mutex_lock(&manager.lock);

    size_t srcLength = strlen(src);

    if (srcLength > limit) {
        pthread_mutex_unlock(&manager.lock);
        return 0;
    }

    // Measure time and memory consumption
    struct timeval start, end;
    gettimeofday(&start, NULL);

    if (*dst == NULL) {
        *dst = malloc(limit + 1);
    } else {
        void* tempPtr = realloc(*dst, limit + 1);

        // Check for allocation errors
        if (tempPtr == NULL) {
            pthread_mutex_unlock(&manager.lock);
            return 0;
        }

        *dst = tempPtr;
    }

    gettimeofday(&end, NULL);
    size_t memoryUsed = limit + 1;
    double timeTakenInMicroseconds = 
                 (end.tv_sec - start.tv_sec) * 1000000 + end.tv_usec - start.tv_usec;

    // Logging allocations and reallocations
    printf("Allocated/Reallocated memory: %zu bytes, time taken: %f microseconds\n", 
           memoryUsed, timeTakenInMicroseconds);

    strncpy(*dst, src, limit);
    (*dst)[limit] = '\0'; // Ensure null termination

    pthread_mutex_unlock(&manager.lock);

    return srcLength;
}
```

This code uses a `StringManager` struct to hold the mutex lock for mutual exclusion. The `CopyStringWithLimit()` function checks if the source string length exceeds the limit before copying it into the destination buffer. It also measures time and memory consumption of allocation/reallocation using `gettimeofday()`. 

Please note that this is a basic implementation, you might need to adjust it according to your specific requirements, such as using a more sophisticated logging system or adding error handling mechanisms for various edge cases. Also, please integrate this function into an existing library, ensuring minimal impact on the library's performance under high concurrency by minimizing unnecessary reallocations and allocations.
