['Here is a sample implementation in C# based on your requirements:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DynamicValueManager
{
    private float minValue = float.MinValue;
    private float maxValue = float.MaxValue;

    // For the current average calculation
    private long totalValues = 0;
    private int generatedValuesCount = 0;

    private object lockObject = new object();

    public void AdjustRange(float newMin, float newMax)
    {
        lock (lockObject)
        {
            if (newMin <= newMax)
            {
                minValue = newMin;
                maxValue = newMax;
            }
        }
    }

    public void ResetStatistics()
    {
        lock(lockObject)
        {
            totalValues = 0;
            generatedValuesCount = 0;
        }
    }

    public float GetRandomFloat()
    {
        var value = minValue + (float)(new Random().NextDouble() * (maxValue - minValue));

        lock(lockObject)
        {
            ++generatedValuesCount;
            totalValues += (long)value;
        }

        return value;
    }

    public float GetAdjustedValue(float value)
    {
        if (value < minValue || value > maxValue)
        {
            var range = maxValue - minValue + 1;

            while (value < minValue)
                value += range;

            while (value > maxValue)
                value -= range;
        }

        return value;
    }

    public override string ToString()
    {
        lock(lockObject)
        {
            return $"Current Range: [{minValue}, {maxValue}]";
        }
    }

    public float CurrentAverage 
    {
        get
        {
            lock(lockObject)
            {
                if (generatedValuesCount > 0)
                    return (float)(totalValues / (double)generatedValuesCount);

                return 0;
            }
        }
    }

    public List<float> GenerateUniqueValues(int count)
    {
        var values = new HashSet<float>();

        while (values.Count < count)
        {
            float value = GetRandomFloat();

            lock(lockObject)
                if (!values.Contains(value))
                    values.Add(value);
        }

        return values.ToList();
    }

    public void MergeRanges(DynamicValueManager other)
    {
        if (other == null) 
            throw new ArgumentNullException(nameof(other));

        lock(lockObject)
        {
            minValue = Math.Min(minValue, other.minValue);
            maxValue = Math.Max(maxValue, other.maxValue);
        }
    }

    public IEnumerable<float> CalculateAdjustedValues(IEnumerable<float> values)
    {
        return values?.Select(v => GetAdjustedValue(v));
    }
}
```
This class includes methods to generate random float and integer values, adjust the range of generated values, calculate the average of all generated values, merge ranges from another instance, generate unique values within the current range, and reset statistics related to generated values. All operations are thread-safe to allow concurrent access and modifications to the range and value generation process.
