    if (initialized) {
        return 0;
    }

    /* Initialize OpenSSL */
    if (_initialize_openssl() != 0) {
        fprintf(stderr, "Failed to initialize OpenSSL\n");
        return -1;
    }

    initialized = 1;
    return 0;
}

void deinitialize() {
    static int deinitialized = 0;

    if (deinitialized) {
