['Here is a basic implementation of this function in C with POSIX threads (pthreads). Note that error checking has been kept minimal to focus on core functionality. This code does not include any logging mechanism, but it provides a good starting point for such a task.

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Simple session structure
typedef struct Session {
    int id;
    time_t timestamp; // Time of insertion
    struct Session *next;
} Session;

// Global lock for thread-safe operations on the list and count
pthread_mutex_t sessionMutex = PTHREAD_MUTEX_INITIALIZER;

int addSession(Session **list, int *count, int maxCount, int id) {
    Session *newSession = malloc(sizeof(Session));
    if (newSession == NULL) return -1; // out of memory

    newSession->id = id;
    newSession->timestamp = time(NULL); // current time

    pthread_mutex_lock(&sessionMutex);

    (*count)++;
    if(*count > maxCount){
        Session *prev, *current;
        for (current = *list, prev = NULL; 
             current->next != NULL && newSession->id < current->next->id; 
             prev = current, current = current->next) { }

        if(prev == NULL){ // New session is oldest, no need to remove anything
            free(*list);
            *list = newSession;
        } else {
            prev->next = newSession;
            free(current);
            (*count)--;
        }
    } else if(*count > 0) { // Insertion in between or at the end
        Session **indirect = list;
        while ((*indirect)->id < id){
            indirect = &((*indirect)->next);
        }
        newSession->next = *indirect;
        *indirect = newSession;
    } else { // First insertion
        newSession->next = NULL;
        *list = newSession;
    }

    pthread_mutex_unlock(&sessionMutex);
    return 0;
}
```
This function uses a lock to ensure that only one thread at a time can modify the session list and count. For large-scale deployments, you would likely want to use a more efficient data structure such as a self-balancing binary search tree or a skip list for better performance under concurrent access and when dealing with large amounts of data. Also consider using a logging mechanism to store session activities in a persistent storage system like a database.
']

