#include "boost/thread.hpp"

class SensorNode {
public:
    std::string sensorId;
    boost::any calibrationParams;  // use Boost.Any for any type of calibration params
    std::vector<double> timeSeriesData;
};

class SensorDataManager {
private:
    rocksdb::DB* db;
    rocksdb::Options options;
    std::shared_mutex mutex_;  // lock shared across threads when reading, exclusive when writing
    std::map<std::string, SensorNode> nodes_;
public:
    SensorDataManager() {
        options.create_if_missing = true;
        rocksdb::Status status = rocksdb::DB::Open(options, "/tmp/testrocksdb", &db);
        assert(status.ok());
    }

    ~SensorDataManager() { delete db; }

    void addNode(const std::string& sensorId) {
        SensorNode node{sensorId};
        boost::unique_lock<std::shared_mutex> lock(mutex_);  // exclusive lock
        nodes_.insert({sensorId, node});
    }

    void addTimeSeriesData(const std::string& sensorId, double data) {
        boost::upgrade_lock<std::shared_mutex> lock(mutex_);  // shared lock
        SensorNode& node = nodes_.at(sensorId);
        boost::upgrade_to_unique_lock<std::shared_mutex> uniqueLock(lock);  // upgrade to exclusive lock
        node.timeSeriesData.push_back(data);
    }

    void saveToStorage() {
        std::string key = "SensorConfig";
        boost::shared_lock<std::shared_mutex> lock(mutex_);  // shared lock
        rocksdb::Status status = db->Put(rocksdb::WriteOptions(), key, serializeNodes());
        assert(status.ok());
    }

    void loadFromStorage() {
        std::string value;
        std::string key = "SensorConfig";
        rocksdb::Status status = db->Get(rocksdb::ReadOptions(), key, &value);
        boost::unique_lock<std::shared_mutex> lock(mutex_);  // exclusive lock
        nodes_ = deserializeNodes(value);
    }

    std::string serializeNodes() { /* implement your serialization logic here */ }
    std::map<std::string, SensorNode> deserializeNodes(const std::string& value) { /* implement your deserialization logic here */ }
};
