['Below is the C# code for the task as provided:

```csharp
using System;

public class RandomValueGenerator {
    private float minValue, maxValue;
    private Random rand;

    public RandomValueGenerator(float min, float max) {
        this.minValue = min;
        this.maxValue = max;
        this.rand = new Random();
    }

    public void InitializeRandomWithSeed(int seed) {
        rand = new Random(seed);
    }

    public float GetRandomFloat() {
        return (float)(minValue + rand.NextDouble() * (maxValue - minValue));
    }

    public int GetRandomInt() {
        return rand.Next((int)Math.Ceiling(minValue), (int)Math.Floor(maxValue + 1));
    }

    public override string ToString() {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
```
