        _minInt = 0;
        _maxInt = 100;
    }

    public void InitializePRNG(int seed)
    {
        lock (_prngInstances)
        {
            if (!_prngInstances.ContainsKey(seed))
                _prngInstances[seed] = new Random(seed);
        }
    }

    public void SetRange(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        lock (_prngInstances)
        {
            _minFloat = minFloat;
            _maxFloat = maxFloat;
            _minInt = minInt;
            _maxInt = maxInt;
        }
    }

    public float GetRandomFloat(int seed)
    {
        lock (_prngInstances)
        {
            if (!_prngInstances.ContainsKey(seed)) return 0.0f;

            var random = _prngInstances[seed];
            return (float)(random.NextDouble() * (_maxFloat - _minFloat) + _minFloat);
        }
    }

    public int GetRandomInt(int seed)
    {
        lock (_prngInstances)
        {
            if (!_prngInstances.ContainsKey(seed)) return 0;

            var random = _prngInstances[seed];
            return random.Next(_minInt, _maxInt + 1);
        }
    }

    public override string ToString() => $"Float range: [{_minFloat}, {_maxFloat}], Int range: [{_minInt}, {_maxInt}]";

    // Incomplete implementation for logging and other performance optimizations.
    private void Log(string message) => Console.WriteLine(message);
}
```
In this code, we use a dictionary to manage multiple PRNG instances with different seeds. To ensure thread safety, we lock on the shared dictionary object whenever accessing or modifying it. For simplicity's sake, logging and performance optimizations are omitted here. A full implementation would need to consider these factors in depth.
