#include <pthread.h>

typedef struct {
    size_t size;
    size_t writeIndex;
    size_t readIndex;
    int isFull;
    void *buffer;
    pthread_mutex_t lock;
} CircularBuffer;

int circularBufferInitialize(CircularBuffer *cbuf, size_t size) {
    if (pthread_mutex_init(&cbuf->lock, NULL) != 0) {
        return -1;
    }

    cbuf->buffer = malloc(size);
    if (!cbuf->buffer) {
        pthread_mutex_destroy(&cbuf->lock);
        return -1;  // Could not allocate buffer.
    }

    cbuf->size = size;
    cbuf->writeIndex = 0;
    cbuf->readIndex = 0;
    cbuf->isFull = 0;
    return 0;
}
