    uint16_t port;
} Address;

void freeAddresses(Address** addresses, int size) {
    for (int i = 0; i < size; ++i) {
        if ((*addresses)[i].ip != NULL) {
            free((*addresses)[i].ip);
        }
    }

    free(*addresses);
}

void printAddress(const Address* address) {
    printf("IP: %s, Port: %d\n", address->ip, ntohs(address->port));
}

int main() {
    FILE *file = fopen("config.txt", "r");

    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    Address* addresses = malloc(1000 * sizeof(Address));
    int size = 0, malformedEntries = 0, sameIPEntries = 0;
    char line[256];

    if (addresses == NULL) {
        perror("Error allocating memory");
        return EXIT_FAILURE;
    }

    while (fgets(line, sizeof(line), file)) {
        Address address;

        char* ip = strtok(line, ":");
        if (ip == NULL) continue;  // Skip invalid entries.

        char* portStr = strtok(NULL, "\n");
        if (portStr == NULL) continue;  // Skip invalid entries.

        address.ip = malloc((strlen(ip) + 1) * sizeof(char));
        strcpy(address.ip, ip);

        int port = atoi(portStr);
        address.port = htons(port);

        if (size > 0 && strcmp(addresses[size - 1].ip, address.ip) == 0) {
            printf("Malformed Entry: %s\n", line);
            ++malformedEntries;
            continue;
        }

        if ((strlen(ip) < 7 || strlen(ip) > 39) && inet_addr(ip) == -1) {
            printf("Malformed IP Address: %s\n", line);
            ++malformedEntries;
            continue;
        } 

        if (size == 1000) {
            printf("Maximum limit reached.\n");
            break;
        }

        addresses[size] = address;
        ++size;
    }

    fclose(file);

    for (int i = 0; i < size; ++i) {
        printAddress(&addresses[i]);
    }

    freeAddresses(&addresses, size);

    printf("Malformed entries: %d\n", malformedEntries);

    return EXIT_SUCCESS;
}
```
This solution uses a dynamically allocated array of `struct Address` to store the network addresses. It reads each line from the configuration file, tokenizes it into IP and port, validates the address and stores it in an instance of struct `Address` which is then added to the array. Finally, it frees all dynamically allocated memory before terminating the program using a helper function.
']

