#include <stdio.h>
#include <stdlib.h>
#include <openssl/md5.h>
#include <string.h>
#include <sys/stat.h>

#define CHUNK_SIZE 4096 // 4KB chunk size for file read
#define MAX_ENTRIES 1000

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    int port;
} Address;

Address* addresses[MAX_ENTRIES];
int addressCount = 0;

void cleanup() {
    for (int i = 0; i < addressCount; ++i) {
        free(addresses[i]);
    }
}

// Validate and print an IP:port entry
void validateAndPrint(char* line) {
    Address addr;
    if (sscanf(line, "%[^:]:%d", addr.ip, &addr.port) == 2 && addressCount < MAX_ENTRIES) {
        addresses[addressCount] = malloc(sizeof(Address));
        *addresses[addressCount] = addr;
        ++addressCount;
    } else {
        printf("Invalid line: %s\n", line);
    }
}

// Calculate the MD5 hash of a file
char* calculateMD5Hash(const char* filename, FILE* log) {
    unsigned char c[CHUNK_SIZE];
    int n;
    MD5_CTX mdContext;
    unsigned char digest[16];

    if (!(log)) {
        printf("Failed to open file for logging.\n");
        return NULL;
    }

    FILE* inFile = fopen (filename, "rb");

    if (inFile == NULL) {
        fprintf(log, "Failed to open input file '%s'\n", filename);
        return NULL;
    }

    MD5_Init(&mdContext);
    while ((n = fread(c, 1, sizeof c, inFile)) > 0) {
        MD5_Update(&mdContext, c, n);
    }

    MD5_Final(digest, &mdContext);

    char* mdString = malloc(33 * sizeof(char)); // 16 bytes of data to hex = 32 chars + null terminator

    for (int i = 0; i < 16; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    fclose(inFile);

    return mdString;
}
```
