        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "";
    }
}

void logMessage(loglevel level, const char* file, int line, const char* func, const char *format, ...) {
    pthread_mutex_lock(&mutex);

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    va_list argptr;
    va_start(argptr, format);
    vsnprintf(buffer[currentBuffer], MAX_LOG_LENGTH, format, argptr);
    va_end(argptr);

    printf("[%s][%s] %s:%d in %s -> %s\n", timestamp, logLevelToString(level), file, line, func, buffer[currentBuffer]);

    currentBuffer = (currentBuffer + 1) % NUM_BUFFERS;

    pthread_mutex_unlock(&mutex);
}
