EVP_CIPHER* cipher_selector(const char *input) {
    if (strcmp(input, "ECB") == 0) return EVP_aes_256_ecb();
    else if (strcmp(input, "EDE") == 0) return EVP_aes_256_cbc();
    else if (strcmp(input, "EDE3") == 0) return EVP_aes_256_ecb();
