bool validate_oauth2(const char *json_string) {
    json_error_t error;
    json_t *root = json_loads(json_string, 0, &error);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        printf("Error: Invalid JSON format.\n");
        return false;
    }

    if(strcmp(json_string(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        printf("Error: Invalid access token or expires_in value.\n");
        return false;
    }

