    BUF_MEM *bufferPtr;
    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new_mem_buf((void*)json_string(access_token), -1);
    bio = BIO_push(b64, bio);

    char in[500]={0}, out[500]={0};
    int len;
    while ((len = BIO_read(bio, in, sizeof(in))) > 0) {
        // check if the string is a valid base64 here
    }

    BIO_free_all(bio);

    json_t *refresh_token = json_object_get(root, "refresh_token");
    json_t *scope = json_object_get(root, "scope");
    json_t *issued_at = json_object_get(root, "issued_at");

    if((refresh_token && !json_is_string(refresh_token)) || (scope && !json_is_string(scope)) || 
       (issued_at && !json_is_integer(issued_at))) {
        printf("Error: Invalid JSON format.\n");
        return false;
    }

    json_decref(root);
    return true;
}
