```csharp
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <limits.h>
#include <float.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    float CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
   NFAPI_CRC_INDICATION_PDU_T data;
   struct node *next;
};

typedef struct DynamicValueManager {
    pthread_mutex_t mutex;  // Used for thread safety
    float minValue;
    float maxValue;
} DynamicValueManager;

DynamicValueManager* dvm = NULL;

float GetRandomFloat() {
    srand(time(NULL));
    return ((float) rand() / (float) RAND_MAX) * (dvm->maxValue - dvm->minValue) + dvm->minValue;
}

int GetRandomInt() {
    srand(time(NULL));
    return rand() % (int)(dvm->maxValue - dvm->minValue + 1) + (int)dvm->minValue;
}

void AdjustRange(float newMin, float newMax) {
    pthread_mutex_lock(&dvm->mutex);

    if(newMin < newMax && newMin >= dvm->minValue && newMax <= dvm->maxValue){
        dvm->minValue = newMin;
        dvm->maxValue = newMax;
    }

    pthread_mutex_unlock(&dvm->mutex);
}

float GetAdjustedValue(float value) {
    float adjustedValue = value;

    if (value < dvm->minValue){
        while (adjustedValue < dvm->minValue) {
            adjustedValue += abs(dvm->maxValue - dvm->minValue);
        }
    } else if (value > dvm->maxValue){
        while (adjustedValue > dvm->maxValue) {
            adjustedValue -= abs(dvm->maxValue - dvm->minValue);
        }
    }

    return adjustedValue;
}

// Initialize the Dynamic Value Manager with default values.
void initializeDynamicValueManager() {
    if (dvm == NULL) {
        dvm = malloc(sizeof(DynamicValueManager));
        pthread_mutex_init(&dvm->mutex, NULL);
        dvm->minValue = FLT_MIN;
        dvm->maxValue = FLT_MAX;
    }
}

void generateNFAPICRCIndications() {
    initializeDynamicValueManager();

    // Create linked list
    struct node *head = NULL;
    for(int i=0; i<10; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = GetRandomInt();
        pdu.RNTI = GetRandomInt();
        pdu.CRCFLAG = GetRandomFloat();

        struct node *link = (struct node*) malloc(sizeof(struct node));
        link->data = pdu;
        link->next = head;
        head = link;
    }

    // Free memory for the linked list
    struct node* temp = head;
    while(temp != NULL) {
       struct node* prev = temp->next;
       free(temp);
       temp = prev;
    }
}
```
