    time_t timestamp;
    float packetLossRate;
    int latency;
    long throughput;  // assuming throughput is represented in bits
} network_stat_record_t;

void processAndEncryptNetworkStats(network_stat_record_t *stats, char* configuration) {
    unsigned char aes_key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];

    // Generate random key and IV
    if (RAND_bytes(aes_key, sizeof(aes_key)) != 1) {
        my_log(ERROR, "Failed to generate AES key");
        return;
    }
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        my_log(ERROR, "Failed to generate IV");
        return;
    }

    // Dynamically allocate memory for an array of network_stat_record_t structures
    int num_stats = sizeof(*stats) / sizeof(network_stat_record_t);
    network_stat_record_t* encryptedStats = malloc(num_stats * sizeof(network_stat_record_t));

    if (encryptedStats == NULL) {
        my_log(ERROR, "Failed to allocate memory for encrypted stats");
        return;
    }

    // Encrypt each network stat with AES-CBC and store in the allocated array
    AES_KEY aesKey;
    if (AES_set_encrypt_key(aes_key, sizeof(aes_key) * 8, &aesKey) != 0) {
        my_log(ERROR, "Failed to set encryption key");
        return;
    }

    for (int i = 0; i < num_stats; i++) {
        AES_cbc_encrypt((unsigned char*) &stats[i], 
                        (unsigned char*) &encryptedStats[i], sizeof(network_stat_record_t), &aesKey, iv, AES_ENCRYPT);
    }

    // Free original unencrypted stats
    free(stats);
}
