    fseek(in, 0L, SEEK_END);
    long numbytes = ftell(in);

    // Jump back to the start of the file
    fseek(in, 0L, SEEK_SET);	

    // Allocate memory for parsing the input file and writing it to the output
    char *buffer = (char*)calloc(numbytes + 1, sizeof(char));	
    if (buffer == NULL) {
        perror("Error allocating buffer");
        return NULL;
    }

    // Copy all the text into the buffer
    fread(buffer, sizeof(char), numbytes, in);
    fwrite(buffer, sizeof(char), numbytes, out);

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    int n = 10;  // number of structures
    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

