        metricRecords[i].metric_data->network_bandwidth = (double)rand() / RAND_MAX * 100.0;

        // Get current time in seconds since the Epoch
        metricRecords[i].timestamp = time(NULL);
    }

    return NULL;
}

int readInputFile(char* fileName, int numLines) {
    FILE *fp = fopen(fileName, "r");
    if (fp == NULL) {
        return -1;
    }

    char buffer[256];
    int lines = 0;
    while (fgets(buffer, sizeof(buffer), fp)) {
        lines++;
    }

    fclose(fp);
    return lines < numLines ? lines : numLines;
}

void logError(FILE *fp, const char *msg) {
