['Here's a simple implementation of the `DynamicValueManager` class along with helper functions that can help generate CRC_INDICATION_REL8_TAG values. The function `generateNFAPICRCIndications` is not included due to its complexity, but it could be implemented by integrating this class and others into a larger project:

```csharp
using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using Unity.Entities;
using System.Threading;

public class DynamicValueManager : IComponentData, IDisposable
{
    private float minValue = float.MinValue;
    private float maxValue = float.MaxValue;
    private List<float> generatedValues = new List<float>();
    private object lockObject = new object();

    public DynamicValueManager() { }

    public DynamicValueManager(float min, float max) 
    {
        AdjustRange(min, max);
    }

    public void Dispose()
    {
        ResetStatistics();
    }

    public float GetRandomFloat()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range(minValue, maxValue);
        }
    }

    public int GetRandomInt()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range((int)minValue, (int)maxValue + 1);
        }
    }

    public void AdjustRange(float newMin, float newMax)
    {
        if (newMin > newMax)
        {
            throw new ArgumentException("Invalid range: min is greater than max");
        }

        lock (lockObject)
        {
            minValue = newMin;
            maxValue = newMax;

            generatedValues.Clear();
        }
    }

    public float GetAdjustedValue(float value)
    {
        if (value < minValue)
        {
            return minValue;
        }

        if (value > maxValue)
        {
            return maxValue;
        }

        lock (lockObject)
        {
            generatedValues.Add(value);
        }

        return value;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public IEnumerable<float> CalculateAdjustedValues(IEnumerable<float> values)
    {
        lock (lockObject)
        {
            foreach (var value in values)
            {
                yield return GetAdjustedValue(value);
            }
        }
    }

    public void MergeRanges(DynamicValueManager other)
    {
        lock (lockObject)
        {
            if (other.minValue < minValue) 
            {
                minValue = other.minValue;
            }

            if (other.maxValue > maxValue)
            {
                maxValue = other.maxValue;
            }

            generatedValues.Clear();
        }
    }

    public float CurrentAverage 
    {
        get 
        {
            lock (lockObject)
            {
                return generatedValues.Count > 0 ? generatedValues.Average() : 0;
            }
        }
    }

    public void ResetStatistics()
    {
        lock (lockObject)
        {
            generatedValues.Clear();
        }
    }
}
```
