public NFAPI_CRC_INDICATION_PDU_T GenerateNFAPICRCIndication() 
{
    var crcFlag = generateRandomByte();
    var rnti = GenerateRNTI();

    return new NFAPI_CRC_INDICATION_PDU_T(rnti, new CRC_INDICATION_REL8_TAG(crcFlag));
}

public byte generateRandomByte() 
{
    Random rnd = new Random();
    byte[] buffer = new byte[1];
    rnd.NextBytes(buffer);

    return buffer[0];
}

private int GenerateRNTI() 
{
    Random random = new Random();
    int rnti = 1;

    while (rnti % 2 == 0)
    {
        rnti = random.Next(32769, 65535); // ensure RNTI is odd number
    }

    return rnti;
}
```

