device_statistics* init_traffic_stats(unsigned long bytes_in, unsigned long bytes_out, 
                                      unsigned long packets_in, unsigned long packets_out, 
                                      double error_rate, const char* interface_type) {
    device_statistics *stats = (device_statistics*)malloc(sizeof(device_statistics));

    if (!stats) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);  // enter critical section

    stats->bytes_in = bytes_in;
    stats->bytes_out = bytes_out;
    stats->packets_in = packets_in;
    stats->packets_out = packets_out;
    stats->error_rate = error_rate;

    if(strlen(interface_type) >= 16){
        fprintf(stderr, "Interface type string too long\n");
        free(stats);
        pthread_mutex_unlock(&lock); // leave critical section
        return NULL;
    }else{
        strcpy(stats->interface_type, interface_type);
    }

    pthread_mutex_unlock(&lock); // leave critical section

    return stats; 
}
