```C
#include <string.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node* head = NULL; 
int size = 0;  

void add(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node *newNode = (Node *) malloc(sizeof(Node));
    newNode->data = pdu;
    newNode->next = head;
    head = newNode;
    size++;
}

void remove(int criteria) {
    if (head == NULL) return;
    Node *temp = head, *prev;
    while (temp != NULL && temp->data.RX_UE_INFORMATION_TAG != criteria) {
        prev = temp;
        temp = temp->next;
    }
    if(temp == NULL) return; 
    prev->next = temp->next;  
    free(temp); 
    size--;
}

Node* retrieveAll() {
    Node *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
                current->data.RX_UE_INFORMATION_TAG, 
                current->data.RNTI, 
                current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

char* appendSlashIfWithinLimit(const char *str, int limit) {
    if (strlen(str) <= limit) {
        char *newStr = malloc(sizeof(char) * (limit + 2)); 
        strcpy(newStr, str);
        newStr[strlen(str)] = '/';
        return newStr;
    } else {
        return NULL;
    }
}
```
