NFAPI_CRC_INDICATION_PDU_T *collection;
int collectionSize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void manageNfaapiCrcIndication(void) {
    // Initialize the collection
    collection = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Add a new structure to the collection
void addStructure(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex); // Lock the mutex

    // Resize the array to accommodate new structure
    collection = realloc(collection, (collectionSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add new structure
    collection[collectionSize].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    collection[collectionSize].RNTI = RNTI;
    collection[collectionSize].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Increment size of collection
    collectionSize++;

    pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Remove a structure from the collection based on specific criteria
void removeStructure(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&mutex); // Lock the mutex

    // Find and remove matching structures
    for (int i = 0; i < collectionSize; i++) {
        if (collection[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            memmove(&collection[i], &collection[i + 1], (collectionSize - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            collection = realloc(collection, (collectionSize - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            collectionSize--;
        }
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Retrieve all structures meeting certain conditions
NFAPI_CRC_INDICATION_PDU_T *getStructures(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *result = malloc(collectionSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
