    long offset;
    int key;
    double value;
};

std::mutex mtx; // Mutex for thread safety
std::vector<Record*> recordArr; // Array of pointers to Records
int arrSize = 0;
int capacity = 10;

// Custom error handling function
void handleError(const char *message) {
    std::cerr << message << std::endl;
    exit(EXIT_FAILURE);
}

// Dynamically allocate and initialize an array of records
void initRecordArr() {
    for (int i = 0; i < capacity; ++i) {
        Record* r = new (std::nothrow) Record; // Allocating memory safely
        if (!r) handleError("Memory allocation failed!"); 
        r->id = i;
        r->offset = 2 * i + 1;
        r->key = i * i;
        r->value = 2.718 + (double)i / (i + 1); // euler's number + some fraction
        recordArr.push_back(r);
    }
    arrSize = capacity;
}

// Function to resize the record array when it is full
void resizeRecordArr() {
    mtx.lock();  // Locking for thread safety

    if (arrSize == capacity) {
        Record** temp = new (std::nothrow) Record*[2 * capacity]; // Allocating memory safely
        if (!temp) handleError("Memory allocation failed!"); 

        for (int i = 0; i < arrSize; ++i) {
            temp[i] = recordArr[i]; // Copying old data to new array
        }

        delete[] recordArr; // Deleting old memory
        recordArr = temp; 
        capacity *= 2;
