// Function to enqueue new notification
void enqueue(Notification* data) {
   pthread_mutex_lock(&mutexQueue); // Locking the queue while modifying it
    if(itemCount == 1024) {
        printf("Queue is full!\n");
        return;
    }

    if(rear == 1024-1) 
      rear = -1;           

    queue[++rear] = data;  
    itemCount++; 
   pthread_mutex_unlock(&mutexQueue); // Unlocking the queue after modification
}

// Function to dequeue notification based on a condition (assuming condition is SID)
void* dequeue(char *SID) {
   pthread_mutex_lock(&mutexQueue);  // Locking the queue while modifying it
    Notification* data = queue[front++];

    itemCount--; 

    if(front == 1024) 
      front = 0;

   pthread_mutex_unlock(&mutexQueue); // Unlocking the queue after modification
    return data->Payload;
}

// Function to get all notifications meeting a condition (assuming condition is SID)
Notification** getAllNotifications(char *SID){
   pthread_mutex_lock(&mutexQueue);  // Locking the queue while modifying it
    Notification** results = malloc(sizeof(Notification*)*itemCount);
    int index = 0;

    for (int i=front; i<=rear;i++){
        if (strcmp(queue[i]->SID, SID)==0)
            results[index++] = queue[i];
    }
