struct NetworkEventStructure {
    enum EVENT_TYPE { CONNECTION, DISCONNECTION };
    int SOURCE_ID;
    int PRIORITY_LEVEL;
};

class NetworkEventManager {
private:
    static std::vector<NetworkEventStructure> eventQueue;
    static std::mutex mtx;
    static std::condition_variable cv;

public:
    NetworkEventManager() {}
    ~NetworkEventManager() {
        // Cleanup resources here.
    }

    void addEvent(NetworkEventStructure event) {
        std::lock_guard<std::mutex> lk(mtx);
        eventQueue.push_back(event);
        cv.notify_one();
    }

    NetworkEventStructure removeEvent() {
        std::unique_lock<std::mutex> lk(mtx);
        while (eventQueue.empty())
            cv.wait(lk);

        NetworkEventStructure event = eventQueue.back();
        eventQueue.pop_back();
        return event;
    }
};

