['Here's an implementation in JavaScript using memoization for caching and recursion for handling component nesting up to three levels deep. This also includes support for themes and conditional rendering based on context object:

```javascript
let cache = {};

function generateHTML(components, theme = {}, context = {}) {
  return components.map((component) => {
    let type = component.type;
    let props = component.props || {};
    let templateFunc = component.templateFunction;

    // Handle conditional rendering based on context object
    if (context && context[type]) {
      props = { ...props, ...context[type] };
    }

    // Add theme class to each prop
    Object.entries(theme).forEach(([key, value]) => {
      if (!Array.isArray(value)) {
        props['class'] = `${props['class'] || ''} ${value}`;
      } else {
        props = { ...props, [key]: [...(props[key] || []), ...value] };
      }
    });

    let cacheKey = `${type}-${JSON.stringify(props)}`;

    if (cache[cacheKey]) {
      return cache[cacheKey];
    } else {
      let html = templateFunc(type, props);

      // Recursively generate HTML for nested components
      Object.entries(props).forEach(([key, value]) => {
        if (Array.isArray(value)) {
          props[key] = value.map((component) => {
            return Array.isArray(component) ? generateHTML([component], theme, context) : component;
          });
        } else if (typeof value === 'object' && value !== null) {
          // Generate HTML for nested components up to three levels deep
          props[key] = generateHTML([value], theme, context)[0];
        }
      });

      html = `<${type} ${Object.entries(props).map(([k, v]) => `${k}="${v}"`).join(' ')}>${html || ''}</${type}>`;

      cache[cacheKey] = html; // Store in cache for later use
      return html;
    }
  }).join('\n');
}
```
In this code, `components` is an array of component objects with properties:
- `type` which is a string representing the type of HTML element to be created.
- `props` which is an object containing key-value pairs of attributes for the HTML element.
- `templateFunction` is a function that accepts `type` and `props` as arguments, generating additional child elements (if any) based on these parameters.

The `theme` parameter is an optional object containing theme classes to be applied to all components. The `context` object includes any additional data needed for conditional rendering of certain components. 

To optimize memory usage, this code uses a simple cache strategy where each rendered HTML string for a given component and props pair is stored in the cache. Duplicate renders are then simply fetched from the cache instead of re-calculated. 

The code also handles missing or invalid props by ignoring them during generation of the HTML string. It uses fallback mechanisms like an empty string or an empty array for undefined or null values of `props` and `context` respectively.
']

