function traverseJson(obj, depth = 0, filterFunc) {
  let matches = [];

  if (logEnabled) console.time('traversalTime');

  function helper(data) {
    // Check for stack overflow
    if (depth > maxDepth) return;

    Object.entries(data).forEach(([key, value]) => {
      if (typeof value === 'object' && value !== null) {
        // Use caching to reduce duplicate traversal of already processed objects
        if (!cache[value]) {
          cache[value] = true;
          matches.push(...traverseJson(value, depth + 1, filterFunc));
        }
      } else {
        // If the value passes the filter function, add it to the matches list
        if (filterFunc(key, value)) {
          matches.push({ [key]: value });
        }
      }
    });
  }

  helper(obj);

  if (logEnabled) console.timeEnd('traversalTime');
  return matches;
}
