Here's an implementation for the C function:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int trans_id;
    char* client_id;
    void* meta_data; // you can change this to a specific type if required
} DataTransferObject;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

DataTransferObject* createDTOs(int N) {
    if (N < 1) return NULL; // invalid input check

    DataTransferObject* dtos = malloc(sizeof(DataTransferObject) * N);

    if (dtos == NULL) return NULL; // memory allocation failure

    for (int i = 0; i < N; ++i) {
        dtos[i].trans_id = -1;
        dtos[i].client_id = NULL;
        dtos[i].meta_data = NULL;
    }

    pthread_mutex_lock(&mutex); // ensure thread safety while allocating memory

    return dtos;
}

void freeDTOs(DataTransferObject* dtos) {
    if (dtos == NULL) return; // nothing to do if input is already null

    pthread_mutex_unlock(&mutex); // ensure thread safety before releasing memory

    free(dtos);
}
```
