                // Assuming each log line is in format "userId timestamp"
                String[] parts = line.split(" "); 
                if (parts.length < 2) continue; // Missing timestamp, skip this line

                String userId = parts[0];
                LocalDateTime timestamp = LocalDateTime.parse(parts[1], formatter);

                sessionsMap.computeIfAbsent(userId, k -> new ArrayList<>()).add(new Session(timestamp)); 
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + path);
            return;
        }

        for (Map.Entry<String, List<Session>> entry : sessionsMap.entrySet()) {
            String userId = entry.getKey();
            List<Session> sessions = entry.getValue();

            // Analyze and log each session
            for (Session session : sessions) {
                long averageDuration = session.calculateAverageDuration();
                boolean isOutlier = averageDuration > getOutlierThreshold(userId); // Define your own method to compute outlier threshold

                if (isOutlier) {
                    analyticsService.reportOutlierSession(session, userId);
                }
            }
        }
    }

    // Other methods like interruption handling etc., go here 
}
