['```java
import java.util.concurrent.*;
import java.nio.channels.*;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.regex.*;
import java.util.HashMap;
import java.lang.StringBuilder;

public class ConnectionPool {
    private Selector selector;
    private SocketChannel socketChannel;
    private ConcurrentLinkedQueue<String> textDataQueue = new ConcurrentLinkedQueue<>();
    private static final Pattern BOOK_PATTERN = Pattern.compile("\\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalm|Proverbs|Ecclesiastes|SongofSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\\b");
    private HashMap<String, Integer> bookCount = new HashMap<>();

    public ConnectionPool(int port) throws Exception {
        selector = Selector.open();
        socketChannel = SocketChannel.open(new InetSocketAddress("localhost", port));
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
    }

    public void manageConnections() throws Exception {
        while (true) {
            int readyChannels = selector.select();
            if (readyChannels == 0) continue;

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isReadable()) {
                    read(key);
                } else if (key.isWritable()) {
                    write(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void read(SelectionKey key) throws Exception {
        SocketChannel socketChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(256);
        socketChannel.read(buffer);

        String data = new String(buffer.array()).trim();
        if (!data.isEmpty()) {
            textDataQueue.add(data);
        }
    }

    private void write(SelectionKey key) throws Exception {
        SocketChannel socketChannel = (SocketChannel) key.channel();

        while (!textDataQueue.isEmpty()) {
            String data = textDataQueue.poll();

            Matcher matcher = BOOK_PATTERN.matcher(data);
            while (matcher.find()) {
                String bookName = matcher.group().toLowerCase();
                bookCount.put(bookName, bookCount.getOrDefault(bookName, 0) + 1);
            }
        }

        socketChannel.write(ByteBuffer.wrap("Data received.".getBytes()));
    }

    public HashMap<String, Integer> getBookCount() {
        return bookCount;
    }
}
```
']

