["```python
import os
import json
from flask import Flask, request, jsonify
from werkzeug.security import generate_password_hash, check_password_hash
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer
from itsdangerous import SignatureExpired
from cachetools import cached, TTLCache
import vendor.autoloader

# Load environment variables from a configuration file.
def load_config(app):
    with open('config.json') as config_file:
        app.config.update(json.load(config_file))

# Set environment variables for the web application.
def set_env_variables():
    os.environ['SECRET_KEY'] = 'your_secret_key'
    os.environ['CACHE_TYPE'] = 'simple'
    os.environ['JWT_EXPIRATION_DELTA'] = str(60 * 15) # JWT expires after 15 minutes

# Load vendor autoloader.
vendor.autoloader.load()

app = Flask(__name__)
set_env_variables()
load_config(app)

users = {}
cache = TTLCache(maxsize=100, ttl=300)  # Cache for storing user-specific data with a Time To Live of 5 minutes.

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')
    if not username or not password:
        return jsonify({'message': 'Missing credentials!'}), 401

    user = users.get(username)
    if not user or not check_password_hash(user['password'], password):
        return jsonify({'message': 'Invalid credentials!'}), 401

    s = Serializer(os.environ.get('SECRET_KEY'), expires_in=int(os.environ.get('JWT_EXPIRATION_DELTA')))
    token = s.dumps({'id': user['id']}).decode('utf-8')
    cache[username] = user  # Store user data in the cache.

    return jsonify({'token': token})

@app.route('/verify_token', methods=['POST'])
def verify_token():
    token = request.json.get('token')
    if not token:
        return jsonify({'message': 'Missing token!'}), 401

    s = Serializer(os.environ.get('SECRET_KEY'))
    try:
        data = s.loads(token)
    except SignatureExpired:
        return jsonify({'message': 'Token expired, please log in again!'}), 401

    username = get_username_by_id(data['id'])
    if not username:
        return jsonify({'message': 'Invalid token!'}), 401

    user_data = cache.get(username)
    if not user_data:
        return jsonify({'message': 'User session not found, please log in again!'}), 401

    return jsonify({'user_data': user_data})

@cached(cache)
def get_username_by_id(id):
    for username, data in users.items():
        if data['id'] == id:
            return username
```
This code provides a basic session management system using JWT and caching user-specific data. It includes login functionality to issue tokens, token verification, and handling of expired tokens. Please note that this is a simplified example and does not cover all aspects such as hashing passwords securely or implementing refreshing tokens without needing the user to re-authenticate.
"]

['Below is an example of how you might implement such functionality in PHP using `redis` for temporary storage, `RabbitMQ` for message queues and `GuzzleHttp\Client` for HTTP requests to the IdP. Note that this code doesn't include actual user authentication or password strength validation - that would require additional logic:

```php
<?php
use GuzzleHttp\Client;
use PhpAmqpLib\Connection\AMQPStreamConnection;
use Predis\Autoloader;
use Predis\Client as Redis;
require 'vendor/autoload.php';

Autoloader::register();
$redis = new Redis();
$connection = new AMQPStreamConnection('localhost', 5672, 'guest', 'guest');
$channel = $connection->channel();

function updatePassword(string $userId, string $newPassword) {
    global $redis, $channel;
    $client = new Client([
        'base_uri' => 'http://your-idp-url',
        'timeout' => 2.0, // 2 seconds timeout
    ]);

    $user = $redis->get("user:$userId"); // fetch user from cache
    if (!$user) {
        $response = $client->request('GET', "users/$userId", ['http_errors' => false]);
        if ($response->getStatusCode() !== 200) {
            throw new Exception("User $userId not found");
        }
        $user = json_decode($response->getBody(), true); // store user in cache
        $redis->set("user:$userId", $user, 'EX', 60 * 15); // expire after 15 minutes
    }

    $retryCount = 0;
    while (true) {
        try {
            $response = $client->request('PATCH', "users/$userId", [
                'json' => ['password' => $newPassword],
            ]);
            if ($response->getStatusCode() === 200) {
                $redis->del("user:$userId"); // invalidate user cache
                break;
            } elseif ($retryCount < 5 && $response->getStatusCode() !== 409) {
                throw new Exception('Unexpected response code');
            }
        } catch (Exception $e) {
            $delay = min(2 ** $retryCount, 32); // exponential backoff up to 32 seconds
            sleep($delay);
            $retryCount++;
            continue;
        }

        $message = $userId . '|' . $newPassword;
        $channel->basic_publish([
            'delivery_mode' => 2, // make message persistent
        ], '', 'password_updates');
        break;
    }
}
?>
```
In this code, we use Redis for caching user data to minimize network requests. We also use a RabbitMQ exchange named `password_updates` to store failed password updates and later retry them as the IdP comes back online. This implementation uses an exponential backoff strategy with a maximum delay of 32 seconds, which helps in handling intermittent failures while communicating with the IdP.
']

