["Here's an example implementation using C99 standard:

```c
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <limits.h>
#include <pthread.h>

// Define severity level
typedef enum {DEBUG, INFO, WARNING, ERROR} LogLevel;

// Structure to hold log entry data
typedef struct {
    time_t timestamp;
    LogLevel level;
    char source[100];
    char message[500];
} LogEntry;

pthread_mutex_t metricLock = PTHREAD_MUTEX_INITIALIZER;
long long totalLogsProcessed = 0;
long long filteredLogsCount = 0;
double averageMessageLength = 0.0;
size_t maxMessageLength = 0;
char longestMessageSource[100];
time_t windowStartTime = time(NULL);

// Function to check if log entry meets criteria
int isQualifiedLog(const LogEntry* entry) {
    int ageInSeconds = difftime(time(NULL), entry->timestamp);
    size_t messageLength = strlen(entry->message);

    return (ageInSeconds < 30 && 
            (entry->level == ERROR || entry->level == WARNING) && 
            messageLength > 10);
}

// Function to update metrics
void updateMetrics(const LogEntry* entry) {
    pthread_mutex_lock(&metricLock);
    ++totalLogsProcessed;
    ++filteredLogsCount;
