    ERROR_FILE_OPEN = 1,
    ERROR_INVALID_FORMAT,
    ERROR_SIZE_CONSTRAINT,
    ERROR_MD5_COMPUTE
};

int loadResourceBundle(char *filename, ResourceBundle **bundle, size_t maxSize) {
    FILE *file = fopen(filename, "rb"); // Open file in binary mode

    if (!file) 
        return ERROR_FILE_OPEN;

    unsigned char buffer[maxSize]; // Allocate a buffer for reading data
    size_t bytesRead = fread(buffer, sizeof(unsigned char), maxSize, file); // Read the file into the buffer

    if (bytesRead == 0) {
        fclose(file);
        return ERROR_INVALID_FORMAT;
    }

    if (bytesRead > maxSize) {
        fclose(file);
        return ERROR_SIZE_CONSTRAINT;
    }

    // Here you would decompress the buffer data and parse it into a ResourceBundle struct

    *bundle = malloc(sizeof(ResourceBundle));
    if (!*bundle) 
        return ERROR_INVALID_FORMAT;

    fclose(file); // Clean up resources when done

    return 0;
}

int computeMD5Hash(const char *string, unsigned char **hash) {
    MD5_CTX ctx;

    if (!MD5_Init(&ctx)) 
        return ERROR_MD5_COMPUTE;

    if (!MD5_Update(&ctx, string, strlen(string)))
        return ERROR_MD5_COMPUTE;

    *hash = malloc(16); // 16 bytes for MD5 hash
    if (!*hash) {
        return ERROR_MD5_COMPUTE;
    }

    if (!MD5_Final(*hash, &ctx)) 
        return ERROR_MD5_COMPUTE;

    return 0;
}
```
