double weightedAverage(int size, char* line) {
    if (size < 3) return -1; // Error indicator for fewer than 3 fields

    double sum = 0;
    int weight = 3;
    while (*line != '\n') {
        if (*line == ' ' || *line == '\0' || *(line+1) == '\0') {
            sum += (double)(*line - '0') * weight;
            weight--;
            if (weight == 0) break;
        }
        line++;
    }

    return size < 3 ? sum/size : sum;
}

