struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

int configureSubscription(char *userId, char **categories, int numCategories, char *frequency) {

    CURL *curl;
    CURLcode res;

    struct string s;
    init_string(&s);

    curl = curl_easy_init();

    if(curl) {

        // Prepare POST data
        json_object* postObj = json_object_new_object();

        json_object *userIdJson  = json_object_new_string(userId);
        json_object *categoriesJson = json_object_new_array();
        json_object *frequencyJson = json_object_new_string(frequency);

        for(int i = 0; i < numCategories; ++i) {
            json_object_array_add(categoriesJson, json_object_new_string(categories[i]));
        }

