        json_object_object_add(postObj,"deliveryFrequency", frequencyJson);

        char* postData = (char*)json_object_to_json_string(postObj);

        curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/api/subscriptions"); // replace with your API endpoint URL
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postData);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
          fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
          return 1; // error
        }

        json_object *jobj = json_tokener_parse(s.ptr);
        json_object *successJson, *messageJson;

        json_object_object_get_ex(jobj, "success", &successJson);
        json_object_object_get_ex(jobj, "message", &messageJson);

        printf("Server response: %s\n", json_object_get_string(messageJson));

        if(!json_object_get_boolean(successJson)) {
            return 1; // error
        }

        curl_easy_cleanup(curl);
    }
    free(s.ptr);
    return 0; // success
}
```
