using Microsoft.Extensions.Logging;

public interface IHashService
{
    string ComputeMD5(string input);
}

public class MD5HashService : IHashService
{
    private readonly ILogger _logger;

    public MD5HashService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string ComputeMD5(string input)
    {
        if (input == null) 
            return null;

        try
        {
            using (var md5 = MD5.Create())
            {
                byte[] inputBytes = Encoding.ASCII.GetBytes(input);
                byte[] hashBytes = md5.ComputeHash(inputBytes);

                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < hashBytes.Length; i++)
                    sb.Append(hashBytes[i].ToString("X2"));

                return sb.ToString();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while computing the hash.");
            throw;
        }
    }
}

public interface IFileService
{
    string ReadFileContent(string filePath);
}

public class FileService : IFileService
{
    private readonly MD5HashService _hashService;

    public FileService(MD5HashService hashService)
    {
        _hashService = hashService ?? throw new ArgumentNullException(nameof(hashService));
    }

    public string ReadFileContent(string filePath)
    {
        if (filePath == null) 
            return null;

        using (var reader = File.OpenText(filePath))
        {
            var content = reader.ReadToEnd();
            return _hashService.ComputeMD5(content);
        }
