```javascript
const crypto = require('crypto');
const fs = require('fs').promises;
const http = require('http');
const https = require('https');
const os = require('os');
const path = require('path');
const axios = require('axios');
require('dotenv').config();

let agent = new https.Agent({ keepAlive: true });
let semaphore = 0;

async function uploadAndEncrypt(url, options) {
  const filePath = url.split('/').pop();
  if (options.syncUpload) {
    await syncDownloadFile(url);
  } else {
    downloadFile(url);
  }

  semaphore++;
  while(semaphore >= os.cpus().length){
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  const encryptedData = await encryptFile(filePath, options);
  return { url: encryptedData };
}

function downloadFile(url) {
  https.get(url, response => {
    let file = fs.createWriteStream("./" + path.basename(url));
    response.pipe(file);
    file.on('finish', () => {
      file.close();
      semaphore--;
    });
  }).on('error', (err) => {
    console.log("Error: " + err.message);
  });
}

async function syncDownloadFile(url){
  const file = fs.createWriteStream("./" + path.basename(url));
  const response = await axios({
    url,
    method: 'GET',
    responseType: 'stream',
    httpsAgent: agent
  });

  response.data.pipe(file);
  return new Promise((resolve, reject) => {
    file.on('finish', resolve)
    file.on('error', reject)
  })
}

async function encryptFile(filePath, options){
  const data = await fs.readFile(filePath);

  // Use of OpenSSL's EVP_add_cipher and EVP_add_digest functions
  const cipher = crypto.createCipheriv(options.cipherAlgorithm, options.key, options.iv);
  let encryptedData = cipher.update(data, 'utf8', 'hex');
  encryptedData += cipher.final('hex');

  return encryptedData;
}
```
This is a basic implementation that doesn't handle all the scenarios you described but it gives you an idea about how to start building this function. Also, please note that OpenSSL's EVP_add_cipher and EVP_add_digest are not JavaScript functions, they are part of OpenSSL library which is written in C and compiled with Node.js native addon support for Node 4 onwards (see node-openssl).
']

