```javascript
const { exec } = require('child_process');
const xmldom = require('xmldom');
const DOMParser = new (require('xmldom').DOMParser)();

function executeCommand(command, args) {
    return new Promise((resolve, reject) => {
        exec(`${command} ${args.join(" ")}`, (error, stdout, stderr) => {
            if (error) {
                console.log(`Error executing command: ${error.message}`);
                reject(error);
            }

            if (stderr) {
                console.log(`Error from shell command: ${stderr}`);
                reject(new Error(stderr));
            }

            resolve(stdout);
        });
    });
}

function parseXMLAndGetElement(xml, elementName) {
    const doc = DOMParser.parseFromString(xml, 'text/xml');
    const elements = doc.getElementsByTagName(elementName);

    if (elements.length === 0) throw new Error('No such element in XML document');
    if (elements.length > 1) throw new Error('More than one element with this name in XML document');

    return elements[0];
}
```

