    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *array;
} ThreadSafeArray;

ThreadSafeArray* create_array(size_t size) {
    ThreadSafeArray* array = malloc(sizeof(ThreadSafeArray));
    if (array == NULL) return NULL;

    pthread_mutex_init(&array->mutex, NULL);
    array->count = 0;
    array->array = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array->array == NULL) {
        free(array);
        return NULL;
    }

    return array;
}

void destroy_array(ThreadSafeArray* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->array);
    free(array);
}

int add_to_array(ThreadSafeArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);

    if (array->count == SIZE_MAX) {
        errno = ENOMEM;
        return -1;
    }

    array->array[array->count] = element;
    array->count++;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// To serialize and deserialize the array to/from a binary file for persistence, you can use fwrite() and fread() functions.
int save_to_file(ThreadSafeArray* array, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) return -1;

    pthread_mutex_lock(&array->mutex);
    int retval = fwrite(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, fp);
    pthread_mutex_unlock(&array->mutex);

    fclose(fp);
    return (retval == array->count) ? 0 : -1;
}

int load_from_file(ThreadSafeArray* array, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) return -1;

    pthread_mutex_lock(&array->mutex);
    size_t retval = fread(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, fp);
    array->count = retval;
    pthread_mutex_unlock(&array->mutex);

    fclose(fp);
    return (retval == array->count) ? 0 : -1;
}
```
