typedef struct {
    pthread_mutex_t mutex;
    DL_PDU *array;
    size_t used;
    size_t size;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (DL_PDU *)malloc(initialSize * sizeof(DL_PDU));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->mutex, NULL);
}

void insertDynamicArray(DynamicArray *a, DL_PDU element) {
    pthread_mutex_lock(&a->mutex);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (DL_PDU *)realloc(a->array, a->size * sizeof(DL_PDU));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->mutex);
}

void removeDynamicArray(DynamicArray *a, size_t index) {
    pthread_mutex_lock(&a->mutex);
    if (index < a->used) {
        memmove(&a->array[index], &a->array[index + 1], (a->used - index - 1) * sizeof(DL_PDU));
        --a->used;
    }
    pthread_mutex_unlock(&a->mutex);
}

