['以下是一个简单的C语言示例，仅供参考：

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdbool.h>

// 定义DL-PDU结构体
typedef struct {
    void *valid_TB; // 有效传输块信息，实际类型根据需求定义
    bool CRC_INDICATION; // CR校验指示
    unsigned int RNTI; // 无线网络临时标识符
} DL_PDU;

// 定义动态数组结构体
typedef struct {
    DL_PDU *array;
    size_t used;
    size_t size;
} Array;

pthread_mutex_t lock; // 用于线程同步的互斥锁

// 初始化数组
void initArray(Array *a, size_t initialSize) {
    a->array = (DL_PDU *)malloc(initialSize * sizeof(DL_PDU));
    a->used = 0;
    a->size = initialSize;
}

// 插入元素到数组，线程安全
void insertArray(Array *a, DL_PDU element) {
    pthread_mutex_lock(&lock); // 获取锁

    if (a->used == a->size) { // 如果已用空间满，扩容数组
        a->size *= 2;
        a->array = (DL_PDU *)realloc(a->array, a->size * sizeof(DL_PDU));
    }
    a->array[a->used++] = element; // 添加元素

    pthread_mutex_unlock(&lock); // 释放锁
}

// 查询数组，线程安全
int findArray(Array *a, unsigned int RNTI) {
    pthread_mutex_lock(&lock); // 获取锁

    for (size_t i = 0; i < a->used; i++) {
        if (a->array[i].RNTI == RNTI) { // 查找对应RNTI的元素
            pthread_mutex_unlock(&lock); // 释放锁
            return i;
        }
    }

    pthread_mutex_unlock(&lock); // 释放锁
    return -1; // 未找到返回-1
}

// 移除元素，线程安全
void removeArray(Array *a, unsigned int RNTI) {
    pthread_mutex_lock(&lock); // 获取锁

    int index = findArray(a, RNTI); // 查找对应RNTI的元素索引
    if (index != -1) {
        a->array[index] = a->array[--a->used]; // 用最后一个元素替换要移除的元素
    }

    pthread_mutex_unlock(&lock); // 释放锁
}
```

