        {
            // Parse the JSON string and validate the required fields.
            using (JsonDocument document = JsonDocument.Parse(jsonString))
            {
                if (!document.RootElement.TryGetProperty("access_token", out var accessToken) || string.IsNullOrEmpty(accessToken.ToString()))
                    return null;

                if (!document.RootElement.TryGetProperty("expires_in", out var expiresIn) || !int.TryParse(expiresIn.ToString(), out _))
