['Below is an example of how you might implement such a function in C using linked lists and pthread library for thread safety, along with some basic error handling. Please note that this is a simplified representation and does not fully cover all the points mentioned above, but it should give a good starting point:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct frame {
    int stream_id;
    char flags[10];
    size_t payload_length;
    // headers, etc...
    struct frame *next;
} Frame;

Frame *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory = 0;
const size_t MAX_MEMORY = 1024 * 1024; // 1MB

void addFrame(int stream_id, char flags[], size_t payload_length) {
    pthread_mutex_lock(&lock);

    if (total_memory + sizeof(Frame) > MAX_MEMORY) {
        printf("Error: Not enough memory to add a new frame.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Frame *new_frame = malloc(sizeof(Frame));
    if (new_frame == NULL) {
        printf("Error: Failed to allocate memory for a new frame.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    total_memory += sizeof(Frame);
    new_frame->stream_id = stream_id;
    // Set flags and payload length...
    new_frame->next = head;
    head = new_frame;

    pthread_mutex_unlock(&lock);
}

void removeFrame(int stream_id) {
    pthread_mutex_lock(&lock);

    Frame **indirect = &head;
    while (*indirect != NULL) {
        if ((*indirect)->stream_id == stream_id) {
            Frame *frame_to_delete = *indirect;
            *indirect = frame_to_delete->next;
            free(frame_to_delete);
            total_memory -= sizeof(Frame);
            break;
        } else {
            indirect = &((*indirect)->next);
        }
    }

    pthread_mutex_unlock(&lock);
}
```
In the above code, we're using a simple linked list to store the frames. The addFrame and removeFrame functions are thread-safe thanks to the use of pthread mutexes (locks). We also check if adding a new frame would exceed our maximum memory limit. This is a very simplified version and does not cover everything mentioned in the problem, but it should give you an idea about how you might start implementing such a system.
