#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Structure for TCP packet segment
typedef struct Packet {
    char* srcIP;
    char* destIP;
    int portNum;
    int sequenceNum;
    int acknowledgmentNum;
    char* payloadData;
    struct Packet* next;
}Packet;

// Function to add a packet in the list
void addPacket(Packet** head, Packet* newPacket) {
    if (*head == NULL || strcmp((*head)->srcIP, newPacket->srcIP) != 0 || strcmp((*head)->destIP, newPacket->destIP) != 0){
        newPacket->next = *head;
        *head = newPacket;
    } else {
        Packet* temp = *head;
        while(temp->next && strcmp(temp->next->srcIP, newPacket->srcIP) == 0 && strcmp(temp->next->destIP, newPacket->destIP) == 0){
            temp = temp->next;
        }
        if(temp->next == NULL || (strcmp(temp->next->srcIP, newPacket->srcIP) != 0 || strcmp(temp->next->destIP, newPacket->destIP) != 0)){
            newPacket->next = temp->next;
            temp->next = newPacket;
        } else {
            free(newPacket); // Don't add duplicate packet
        }
    }
}

// Function to remove a packet from the list by sequence number
void removePacketBySequenceNumber(Packet** head, int seqNum) {
    if (*head == NULL){
        return; 
    }
    Packet* temp = *head;
    Packet* prev = NULL;
    while (temp != NULL && temp->sequenceNum != seqNum) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL){ 
        return; // Not found
    }
    if(prev == NULL){
        *head = temp->next;
    } else {
        prev->next = temp->next;
    }
    free(temp);
}

// Function to modify filename extension based on its content
void modifyFilenameExtension(char* filename) {
    int length = 0;
    char buffer[6]; // 5 digits + null terminator
    sprintf(buffer, "%d", strlen(filename));

    while (length < 5 && buffer[length] != '\0'){ 
        filename[strlen(filename) - length] = buffer[4 - length];
        ++length;
    }

    for (; length < 5; ++length){ 
        filename[strlen(filename)] = '0'; // Append zeros if less than 5 digits
    }

    strcat(filename, ".ext"); // Append ".ext" to the end
}

int main() {
    Packet* head = NULL;
    addPacket(&head, (Packet*)malloc(sizeof(Packet))); // Adding a packet
    removePacketBySequenceNumber(&head, 1); // Removing by sequence number

    char filename[256] = "sample";
    modifyFilenameExtension(filename);
    printf("%s\n", filename);

    return 0;
}
```
