    if (filenameLength > 255) { // Truncate long filenames to 255 characters
        filenameLength = 255;
    }

    char *newFilename = malloc((6 /*".ext0000"*/) + filenameLength + 1); // ".ext", filename, '\0'

    const char *dot = strrchr(filename, '.');
    if (dot == NULL || dot == filename) { // No extension or filename starts with a dot
