            return NULL; // Failed to create a new thread, so return failure
        }
    } else {
        strncpy(newFilename, filename, dot - filename);

        Metadata *metadata = getFileMetadata(filename);

        sprintf(newFilename + (dot - filename), ".ext%zu", metadata->size % 100000); // Append ".ext" followed by a sequence number
    }

    return newFilename;
}
