['Here is an example implementation of your requirements in C# with some simplifications:

```CSharp
using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading;

public class DynamicValueManager
{
    private static readonly Random random = new Random();

    private float minValue, maxValue;
    private int numberOfGeneratedValues = 0;
    private double sumOfAllValues = 0;
    private HashSet<float> generatedUniqueValues = new HashSet<float>();

    public DynamicValueManager(float minValue=default, float maxValue=default)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    private object lockObject = new object();

    public float GetRandomFloat()
    {
        lock (lockObject)
        {
            var value = (float)(random.NextDouble() * (maxValue - minValue) + minValue);
            ++numberOfGeneratedValues;
            sumOfAllValues += value;
            return value;
        }
    }

    public int GetRandomInt()
    {
        lock (lockObject)
        {
            ++numberOfGeneratedValues;
            var value = random.Next((int)minValue, (int)maxValue + 1);
            sumOfAllValues += value;
            return value;
        }
    }

    public void AdjustRange(float newMin, float newMax)
    {
        lock (lockObject)
        {
            if (newMin > maxValue || newMax < minValue)
                throw new ArgumentException("Invalid range");

            minValue = newMin;
            maxValue = newMax;
        }
    }

    public float GetAdjustedValue(float value)
    {
        lock (lockObject)
        {
            if (value < minValue) return maxValue - ((minValue - value) % (maxValue - minValue));
            if (value > maxValue) return minValue + ((value - minValue) % (maxValue - minValue));

            return value;
        }
    }

    public override string ToString() => "Current range: ["+minValue+", "+maxValue+"]";

    public IEnumerable<float> CalculateAdjustedValues(IEnumerable<float> values)
        => values.Select(GetAdjustedValue);

    public void MergeRanges(DynamicValueManager other)
    {
        lock (lockObject)
        {
            minValue = Math.Min(minValue, other.minValue);
            maxValue = Math.Max(maxValue, other.maxValue);

            if (minValue > maxValue) throw new ArgumentException("Invalid range");
        }
    }

    public double CurrentAverage 
        => numberOfGeneratedValues > 0 ? sumOfAllValues / numberOfGeneratedValues : double.NaN;

    public void ResetStatistics()
    {
        lock (lockObject)
        {
            numberOfGeneratedValues = 0;
            sumOfAllValues = 0;
            generatedUniqueValues = new HashSet<float>();
        }
    }

    public IEnumerable<float> GenerateUniqueValues(int count)
    {
        lock (lockObject)
        {
            var valuesToGenerate = Math.Min(count, (int)(maxValue - minValue + 1) - generatedUniqueValues.Count);

            if (valuesToGenerate <= 0) 
                throw new ArgumentException("Requested count exceeds available unique values in the range");

            while (generatedUniqueValues.Count < valuesToGenerate)
            {
                var value = GetRandomFloat();
                if (!generatedUniqueValues.Contains(value)) generatedUniqueValues.Add(value);
            }

            return generatedUniqueValues;
        }
    }
}
``` 
This code assumes that the values in the range are integral and can fit within a float type. If this assumption is not valid, you would need to adjust accordingly. It also uses `System.Random` for random number generation which may or may not be suitable depending on your requirements. The MergeRanges method throws an exception when ranges overlap unnecessarily. This could be adjusted as needed.
