#include <stdio.h>
#include <openssl/sha.h>   /* For SHA-256 */

/* Define error codes */
enum ErrorCodes {
    NO_ERROR = 0,
    FILE_ACCESS_ISSUE = 1,
    DECRYPTION_FAILURE = 2,
    INVALID_DATA_FORMAT = 3,
    SIZE_CONSTRAINT_EXCEEDED = 4,
    CHECKSUM_MISMATCH = 5
};

/* Struct to hold configuration parameters */
typedef struct {
    char* key;
    char* value;
} ConfigurationParam;

/* Struct to hold iterator state */
typedef struct {
    FILE *file;
    char* buffer;
    int bufferSize;
    int currentIndex;
    int totalParams;
    SHA_CTX sha256Context;  /* For checksum verification */
} ConfigurationFileIterator;

/* Function to initialize iterator */
int initConfigurationIterator(const char *filename, long maxSize, ConfigurationFileIterator *iterator) {
    /* Open file for reading */
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return FILE_ACCESS_ISSUE;
    }

    /* Initialize SHA-256 context */
    if(!SHA256_Init(&iterator->sha256Context)) {
        fclose(file);
        return DECRYPTION_FAILURE;
    }

    iterator->file = file;
    iterator->bufferSize = 1024;  /* Start with small buffer */
    iterator->currentIndex = 0;
    iterator->totalParams = 0;

    return NO_ERROR;
}

/* Function to read next configuration parameter */
int getNextConfigurationParam(ConfigurationFileIterator *iterator, ConfigurationParam *param) {
    /* Read line from file */
    if (fgets(iterator->buffer, iterator->bufferSize, iterator->file) == NULL) {
        return FILE_ACCESS_ISSUE;  /* Error or end of file */
    }

    /* Update checksum */
    SHA256_Update(&iterator->sha256Context, iterator->buffer, strlen(iterator->buffer));

    /* Parse line into key and value */
    if (sscanf(iterator->buffer, "%[^=]=%s", param->key, param->value) != 2) {
        return INVALID_DATA_FORMAT;
    }

    iterator->currentIndex++;
    iterator->totalParams++;

    /* Check if we've reached the end of file */
    if (feof(iterator->file)) {
        /* Verify checksum */

        unsigned char sha256Digest[SHA256_DIGEST_LENGTH];
        SHA256_Final(sha256Digest, &iterator->sha256Context);
        if (/* checksum doesn't match */) {
            return CHECKSUM_MISMATCH;
        }

        fclose(iterator->file);
    }

    return NO_ERROR;
}
```
This is a high level code. Depending on your file format, encryption type, etc., you may need to adjust the code accordingly. Also, I did not include how dynamic buffer size would be adjusted based on estimated incoming data as it can be complex and depends on specific requirements. Furthermore, decryption handling also varies depending on the encryption used (e.g., AES).
