['Here is a basic implementation of your requirements. Please note that actual implementation can vary greatly depending on specifics such as the exact structure of your database or other factors. Also, proper handling of connections to databases requires additional considerations like connection pooling or using `using` blocks for automatic closing and disposing of resources.

```csharp
public class SqlExecutor
{
    private readonly string _connectionString;
    private static ConcurrentDictionary<string, (DateTime, object)> _cache = 
        new ConcurrentDictionary<string, (DateTime, object)>();

    public SqlExecutor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public IDataReader ExecuteQuery(string commandText, params Tuple<object, DbType>[] parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var transaction = connection.BeginTransaction();

            try
            {
                using (var command = connection.CreateCommand())
                {
                    command.CommandText = commandText;
                    command.Transaction = transaction;

                    foreach (var parameter in parameters)
                    {
                        var dbParameter = command.CreateParameter();
                        dbParameter.Value = parameter.Item1;
                        dbParameter.DbType = parameter.Item2;
                        command.Parameters.Add(dbParameter);
                    }

                    IDataReader reader = null;

                    if (_cache.TryGetValue(commandText, out var cached))
                    {
                        if (DateTime.Now - cached.Item1 < TimeSpan.FromMinutes(5)) // adjust as needed
                            reader = (IDataReader)cached.Item2;
                        else
                            _cache.Remove(commandText, out _);
                    }

                    if (reader == null)
                    {
                        reader = command.ExecuteReader();
                        _cache[commandText] = (DateTime.Now, reader);
                    }

                    transaction.Commit();

                    return reader;
                }
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                Console.WriteLine($"Error executing query: {ex}"); // adjust as needed
                throw;
            }
        }
    }
}
```
This class uses the `ConcurrentDictionary` to cache results and implements a basic time-based caching mechanism. It logs errors to the console but a more appropriate logging mechanism would depend on your specific requirements. Also note that the above implementation is very simplistic and doesn't cover all possible edge cases or issues like thread safety, proper error handling etc. A full-featured SQL executor would be much larger and more complex.
