#include <limits.h>

#define MAX_SESSIONS 10000 // adjust according to requirements

typedef struct session {
    int id;
    time_t timestamp;
    struct session* next;
} Session;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int addSession(Session **head, int *sessionCount, int newID) {
    if (newID < 0 || newID > INT_MAX) return -1; // validate session IDs

    Session* newSession = malloc(sizeof(Session));
    if (!newSession) return -1; // check memory allocation
    newSession->id = newID;
    newSession->timestamp = time(NULL);

    pthread_mutex_lock(&lock); // begin critical section

    if (*sessionCount >= MAX_SESSIONS) { // delete oldest session if max reached
        Session *current = *head, *temp = NULL;

        while (current->next->next != NULL) current = current->next;

        temp = current->next;
        current->next = NULL;
        free(temp);
    } else (*sessionCount)++; // increment session count

    newSession->next = *head; // add at head of list
    *head = newSession;

    pthread_mutex_unlock(&lock); // end critical section

    return 0;
}
```

