import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.common.util.concurrent.RateLimiter;

public class HashUtil {
    private static final Logger logger = LoggerFactory.getLogger(HashUtil.class);
    private static final RateLimiter rateLimiter = RateLimiter.create(10.0 / 60.0); // Allow 10 hashes per minute

    public String md5WithRateLimitAndLogging(String input) {
        if (!rateLimiter.tryAcquire()) {
            logger.warn("Too many hash requests in a short time frame");
            return null;
        }

        try {
            String hashed = DigestUtils.md5Hex(input);

            logger.info("Input: {}, Hashed Output: {}", input, hashed);

            return hashed;
        } catch (Exception e) {
            logger.error("Error while hashing the input string", e);
            return null;
        }
    }
}
```
