public class MessageProcessor {
    private final Logger logger = LoggerFactory.getLogger(MessageProcessor.class);
    private final ExecutorService executor;
    private final RedisCache cache;
    private final RateLimiter rateLimiter;
    private final PriorityQueue<Message> queue;

    public MessageProcessor() {
        this.executor = Executors.newFixedThreadPool(10); // Configure the number of threads based on system capacity and throughput requirements
        this.cache = new RedisCache();
        this.rateLimiter = new RateLimiter(5, TimeUnit.SECONDS); 
        this.queue = new PriorityQueue<>(Comparator.comparingInt(Message::getPriority)); // Define your own priority calculation logic
    }

    public void processMessage(String message) {
        if (rateLimiter.tryAcquire()) {
            executor.submit(() -> {
                String hash = cache.computeIfAbsent(message, this::computeHash);
                logger.info("Processed message: {} with hash: {}", message, hash);
            });
        } else {
            // Log or handle rate limit violation
        }
    }

    private String computeHash(String message) {
        Message msg = new Message(message);
        queue.offer(msg);

        while (!queue.isEmpty()) {
            Message processingMessage = queue.poll();
            // Add any pre-processing steps here, like filtering or transforming messages

            try {
                return DigestUtils.md5Hex(processingMessage.getContent());
            } catch (Exception e) {
                logger.error("Failed to compute hash for message: {}", processingMessage.getContent(), e);
            }
        }

        return null;
    }
}
```

