import org.apache.commons.pool2.impl.GenericObjectPool;
import org.apache.commons.pool2.BasePooledObjectFactory;
import org.apache.commons.pool2.PooledObject;
import org.apache.commons.pool2.impl.DefaultPooledObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.security.MessageDigest;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class MD5HashProcessor {
    private static final Logger logger = LoggerFactory.getLogger(MD5HashProcessor.class);

    // Token bucket for rate limiting
    private final RateLimiter tokenBucket = new RateLimiter(); 

    // A pool of MD5 hasher threads
    private final GenericObjectPool<MessageDigest> pool;

    public MD5HashProcessor(int maxConcurrency) {
        this.pool = new GenericObjectPool<>(new BasePooledObjectFactory<MessageDigest>() {
            @Override
            public MessageDigest create() throws Exception {
                return MessageDigest.getInstance("MD5");
            }

            // other methods omitted for brevity
        });

        this.pool.setMaxTotal(maxConcurrency);
    }

    public void process(List<String> strings) {
        try {
            tokenBucket.acquire();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.error("Rate limiting interrupts processing", e);
            return;
        }

        strings.parallelStream()
               .forEach(s -> processStringSafely(s));
    }

    private void processStringSafely(String s) {
        try {
            String hash = calculateHash(s);

            // Store the result in a database here
            logger.info("Processed string: {}, md5 hash: {}", s, hash);
        } catch (Exception e) {
            logger.error("An error occurred while processing string " + s, e);
        }
    }

    private String calculateHash(String s) throws Exception {
        MessageDigest md = pool.borrowObject();

        try {
            byte[] bytes = md.digest(s.getBytes());

            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } finally {
            pool.returnObject(md);
        }
    }
}
```
The `RateLimiter` class is left as a placeholder for your actual implementation of the token bucket algorithm. The logger is used to keep track of all operations, including exceptions. 

This code doesn't include database interaction or any kind of logging framework integration, because that would be quite complex and depend on many factors like whether you use an ORM, which one, how your database and tables are set up etc. For a real-world application you might want to consider libraries such as Hibernate for the ORM part, and Logback or other similar frameworks for logging.
