    FileHandler fh;

    public HashGenerator() throws SecurityException, IOException {
        // This block configures the logger with file handler and formatter
        fh = new FileHandler("MyLogFile.log", true);
        logger.addHandler(fh);
        SimpleFormatter formatter = new SimpleFormatter();
        fh.setFormatter(formatter);
    }

    public synchronized String getMD5Hash(String input) {
        if (input == null || input.isEmpty()) {
            logger.severe("Input string is empty or null");
            return "";
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b & 0xff));
            }

            String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);
            logger.info("MD5 operation performed at " + timestamp);

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.severe("Failed to find MD5 algorithm: " + e.getMessage());
            return "";
        }
    }
}
```
