    // other members...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** list;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* createList(size_t initialCapacity) {
    DynamicList* l = malloc(sizeof(DynamicList));
    if (!l) return NULL; // handle memory exhaustion

    pthread_mutex_init(&l->lock, NULL);

    l->capacity = initialCapacity;
    l->length = 0;
    l->list = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!l->list) { // handle memory exhaustion
        free(l);
        return NULL;
    }

    return l;
}

void destroyList(DynamicList* list) {
    for (size_t i = 0; i < list->length; ++i) {
        free(list->list[i]); // free individual structures as well
    }

    pthread_mutex_destroy(&list->lock);
    free(list->list);
    free(list);
}

int appendToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!element || !list) return -1; // handle invalid inputs

    pthread_mutex_lock(&list->lock);

    if (list->length >= list->capacity) {
        size_t newCapacity = list->capacity * 2;

        NFAPI_CRC_INDICATION_PDU_T** newList = realloc(list->list, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!newList) { // handle memory exhaustion
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->capacity = newCapacity;
        list->list = newList;
    }

    list->list[list->length] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)); // allocate memory for individual structures
    if (!list->list[list->length]) { // handle memory exhaustion
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(list->list[list->length], element, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // copy data into the new structure
    ++list->length;

    pthread_mutex_unlock(&list->lock);
    return 0; // success
}

