// Dynamic list structure
typedef struct {
    ListElement* elements; 
    size_t capacity; 
    size_t count;
    pthread_mutex_t mutex;
} List;

// Initialize the list with a given capacity
void initList(List *list, size_t capacity) {
    list->elements = (ListElement*) calloc(capacity, sizeof(ListElement));
    if(list->elements == NULL) exit(1); // Handle allocation failure 

    list->count = 0;
    list->capacity = capacity;

    if(pthread_mutex_init(&list->mutex, NULL) != 0){
        perror("Failed to initialize mutex");
        exit(1); // Handle thread initialization failure 
    }
}

// Function to add an element safely to the list
int addElementSafely(List *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_lock(&list->mutex) != 0){
        perror("Failed to lock mutex");
        return -1; // Handle thread lock failure 
    }

    // Check for space in the list
    if(list->count == list->capacity) {
        printf("List is full. No more elements can be added\n");
        pthread_mutex_unlock(&list->mutex);
        return -1; 
    }

    // Add the element to the first unoccupied slot in the list
    for(size_t i = 0; i < list->capacity; ++i) {
        if(!list->elements[i].valid) {
            list->elements[i].pdu = pdu;
            list->elements[i].valid = 1;
            ++list->count;
            printf("Element added to the list\n");
            break;
        }
    }

    if(pthread_mutex_unlock(&list->mutex) != 0){
        perror("Failed to unlock mutex");
        return -1; // Handle thread unlock failure 
    }

    return 0;
}

// Function to update an element in the list
void updateElement(List *list, int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (index < 0 || index >= list->capacity) {
        printf("Invalid index. No such element exists\n");
        return; 
    }

    // Check if the specified index is valid
    if(!list->elements[index].valid) {
        printf("No such element exists at this index\n");
        return; 
    }

    if (pthread_mutex_lock(&list->mutex) != 0){
        perror("Failed to lock mutex");
        return; // Handle thread lock failure 
    }

    list->elements[index].pdu = pdu;
    printf("Element at index %d updated\n", index);

    if (pthread_mutex_unlock(&list->mutex) != 0){
        perror("Failed to unlock mutex");
        return; // Handle thread unlock failure 
    }
}
```
