using System.Security.Cryptography;

public class MyController : Controller
{
    private readonly IService _service;

    public MyController(IService service)
    {
        _service = service;
    }

    [HttpPost]
    public ActionResult UpdatePageSection([FromBody] RequestModel model)
    {
        try
        {
            var decryptedMessage = DecryptTripleDes(model.EncryptedMessage, model.Key, model.IV);

            _service.UpdateElementHtmlContent(model.PageSectionId, model.ElementId, model.HtmlContent);

            return Json(new ResponseModel
            {
                Message = decryptedMessage,
                RefreshPage = true
            });
        }
        catch (Exception ex)
        {
            // Log the exception details
            return new HttpStatusCodeResult(HttpStatusCode.InternalServerError);
        }
    }

    private string DecryptTripleDes(string encryptedMessage, byte[] key, byte[] iv)
    {
        using (var tripleDes = TripleDES.Create())
        {
            var cipherTextBytes = Convert.FromBase64String(encryptedMessage);

            using (var decryptor = tripleDes.CreateDecryptor(key, iv))
            {
                var plainTextBytes = decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length);
                return Encoding.UTF8.GetString(plainTextBytes);
            }
        }
    }
}
