[HttpPost]
public async Task<IActionResult> UpdateElement(int userId, string sessionToken, int pageSectionId, int elementId, string htmlContent)
{
    // Authenticate and authorize the session token with Identity Management Service
    var isValid = await _identityService.IsSessionTokenValidAsync(sessionToken);
    if (!isValid) 
        return Unauthorized();

    // Obtain a distributed lock to prevent concurrent updates
    using (var mutexLock = new DistributedMutex(_distributedCache, $"element:{pageSectionId}:{elementId}"))
    {
        if (!mutexLock.TryAcquire()) 
            return StatusCode(503, "Service Unavailable"); // Service Unavailable

        try
        {
            // Retrieve the current HTML content from cache
            var cachedHtml = await _distributedCache.GetAsync<string>($"element:{pageSectionId}:{elementId}");

            if (cachedHtml == null) 
                return NotFound();

            // Update the element in database asynchronously and update cache
            var dbUpdateTask = _databaseService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
            var cacheUpdateTask = _distributedCache.SetAsync($"element:{pageSectionId}:{elementId}", htmlContent);

            // Handle database and cache updates in parallel
            await Task.WhenAll(dbUpdateTask, cacheUpdateTask);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element");
            return StatusCode(500, "Internal Server Error"); // Internal Server Error
        }
    }

    // Invalidate cache in background for high-priority updates
    _backgroundJobQueue.Enqueue(() => InvalidateCacheAsync(pageSectionId, elementId));

    return Ok("Page should be refreshed"); // Successful update
}
