void on_resolved(uv_getaddrinfo_t *resolver, int status, struct addrinfo *res) {
    char addr[17] = "";
    if (status < 0) {
        fprintf(stderr, "getaddrinfo callback error: %s\n", uv_strerror(status));
        return;
    }
    inet_ntop(res->ai_family, res->ai_addr, addr, 16);
    printf("IP address is: %s\n", addr);
}

int main() {
    uv_loop_t *loop = malloc(sizeof(uv_loop_t));
    uv_loop_init(loop);

    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    uv_getaddrinfo_t resolver;
    int r = uv_getaddrinfo(loop, &resolver, on_resolved, "www.example.com", "80", &hints);

    if (r) {
        fprintf(stderr, "getaddrinfo call error: %s\n", uv_strerror(r));
        return 1;
    }

    r = uv_run(loop, UV_RUN_DEFAULT);
}
```
