    pthread_mutex_t lock;
} PRNG;

PRNG prng = {0, PTHREAD_MUTEX_INITIALIZER};
int debugLoggingEnabled = 1; // set this to 0 for production use

static unsigned char generateRandomChar(PRNG *prng) {
    assert(prng);

    pthread_mutex_lock(&prng->lock);
    srand((unsigned int) time(NULL) + prng->seed++);
    unsigned char randVal = (unsigned char)(rand() % 256);
    pthread_mutex_unlock(&prng->lock);

    return randVal;
}

NFAPI_CRC_INDICATION_PDU_T *generateNfapiPduList(size_t n) {
    if (n <= 0 || ((long long)n * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > SIZE_MAX || n > (SIZE_MAX / 256)) {
        return NULL; // error handling, invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // error handling, allocation failure
    }

    for (size_t i = 0; i < n; ++i) {
        list[i].ueTag.RNTI = (int)generateRandomChar(&prng);
        list[i].crcTag.CRCFLAG = generateRandomChar(&prng);

        if (debugLoggingEnabled) {
            printf("Generated PDU %zu: RNTI=%d, CRCFLAG=%u\n", i, list[i].ueTag.RNTI, list[i].crcTag.CRCFLAG);
        }
    }

    return list;
}
