```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#define MAX_ELEMENTS 5000
typedef struct measurement {
    double frequency;
    short signalStrength;
} Measurement;

typedef struct memoryPool {
    pthread_mutex_t lock;
    Measurement* measurements;
    size_t size;
    size_t capacity;
} MemoryPool;

MemoryPool pool;

void initMemoryPool(size_t initialCapacity) {
    if (pthread_mutex_init(&pool.lock, NULL) != 0) {
        // Log error here using provided logger interface 
        exit(EXIT_FAILURE);
    }

    pool.measurements = malloc(sizeof(Measurement) * initialCapacity);
    if (pool.measurements == NULL) {
        // Log error here using provided logger interface 
        exit(EXIT_FAILURE);
    }

    pool.capacity = initialCapacity;
    pool.size = 0;
}

void addToMemoryPool(Measurement measurement) {
    pthread_mutex_lock(&pool.lock);
    if (pool.size == pool.capacity) {
        Measurement* newArray = realloc(pool.measurements, 2 * pool.capacity * sizeof(Measurement));
        if (newArray == NULL) {
            // Log error here using provided logger interface 
            pthread_mutex_unlock(&pool.lock);
            return;
        }

        pool.measurements = newArray;
        pool.capacity *= 2;
    }

    memcpy(&(pool.measurements[pool.size]), &measurement, sizeof(Measurement));
    pool.size++;

    pthread_mutex_unlock(&pool.lock);
}

void destroyMemoryPool() {
    free(pool.measurements);
    pthread_mutex_destroy(&pool.lock);
}

// Example usage of the functions above to create a measurement and add it to the pool:
int main() {
    initMemoryPool(1000);

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        Measurement measurement = { rand() % 50, rand() % 100 };
        addToMemoryPool(measurement);
    }

    destroyMemoryPool();
}
```
This example code provides a basic thread-safe memory pool implementation. It uses `pthread_mutex` for locking the memory pool while modifying it, ensuring data consistency across multiple threads. The `addToMemoryPool` function automatically resizes the array if necessary to keep the capacity at a reasonable level, improving performance on systems with limited resources. 

