['The problem described involves complex programming concepts such as dynamic memory management, concurrency control, data structures optimization, error handling, etc. Below is an implementation using pthreads for thread safety and memory pool from the C standard library for efficient memory usage. 

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 10000
#define MIN(a, b) ((a)<(b)?(a):(b))

typedef struct {
    int key;
} record;

typedef struct {
    pthread_mutex_t lock;
    record* records[MAX_SIZE];
    atomic_int count;
} RecordManager;

RecordManager* createRecordManager() {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&(manager->lock), NULL);
    atomic_store(&(manager->count), 0);

    return manager;
}

record* createRecord() {
    record* rec = malloc(sizeof(record));
    if (rec == NULL) return NULL;

    srand(time(NULL));
    rec->key = rand();

    return rec;
}

void addRecord(RecordManager* manager, record* rec) {
    pthread_mutex_lock(&(manager->lock));
    if (atomic_load(&(manager->count)) < MAX_SIZE) {
        int index = atomic_fetch_add(&(manager->count), 1);
        manager->records[index] = rec;
    } else {
        free(rec);
    }
    pthread_mutex_unlock(&(manager->lock));
}

void updateRecords(RecordManager* manager, int* indices, record** newRecords, int length) {
    for (int i = 0; i < length; i++) {
        if (indices[i] >= atomic_load(&(manager->count))) continue;

        pthread_mutex_lock(&(manager->lock));
        record* oldRec = manager->records[indices[i]];
        manager->records[indices[i]] = newRecords[i];
        free(oldRec);
        pthread_mutex_unlock(&(manager->lock));
    }
}

void destroyRecordManager(RecordManager* manager) {
    for (int i = 0; i < atomic_load(&(manager->count)); i++) {
        free(manager->records[i]);
    }

    pthread_mutex_destroy(&(manager->lock));
    free(manager);
}
``` 
The above code snippet is a simple demonstration of how to manage dynamic records in a thread safe way. It uses pthread mutexes for locking and atomic operations for count manipulation. In a real world scenario, more complex data structures and memory management techniques would be used based on the specific requirements. Error handling, logging etc. have also been simplified here due to their complexity.
']

