```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private Random rng = new Random();
    private int minValue, maxValue;
    private Dictionary<(int, int), List<int>> cachedIntValues = new Dictionary<(int, int), List<int>>();

    public void InitializePRNG(int seed) => rng = new Random(seed);

    public float GetRandomFloat() => 
        (float)(rng.NextDouble() * (maxValue - minValue) + minValue);

    public int GetRandomInt()
    {
        var key = (minValue, maxValue);
        if (!cachedIntValues.ContainsKey(key)) 
        {
            cachedIntValues[key] = Enumerable.Range(minValue, maxValue - minValue + 1).OrderBy(_ => rng.Next()).ToList();
        }
        var values = cachedIntValues[key];
        var result = values.First();
        values.RemoveAt(0);
        if (values.Count == 0)
            cachedIntValues.Remove(key);

        return result;
    }

    public void UpdateRange(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public override string ToString() => $"Current range: [{minValue}, {maxValue}]";
}
```
