```java
import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.zip.GZIPInputStream;

public class StateLoader {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final MessageDigest digest = MessageDigest.getInstance("SHA-256");

    public interface LoadCallback<T> {
        T loadFromInputStream(InputStream is) throws IOException;
    }

    public <T> void asyncLoadStateObject(String path, String checksum, LoadCallback<T> callback) {
        executor.execute(() -> {
            try (FileInputStream fis = new FileInputStream(path)) {
                T object = loadCompressedOrUncompressed(fis, callback);
                byte[] actualChecksum = digest.digest(serializer.serializeObject(object));
                if (!checksum.equals(new String(actualChecksum))) {
                    throw new IllegalStateException("Data corrupted");
                }
                // Success callback here
            } catch (IOException e) {
                // Error callback here
            }
        });
    }

    private <T> T loadCompressedOrUncompressed(FileInputStream fis, LoadCallback<T> callback) throws IOException {
        if (isGZIPStream(fis)) {
            try (GZIPInputStream gzis = new GZIPInputStream(fis)) {
                return callback.loadFromInputStream(gzis);
            }
        } else {
            return callback.loadFromInputStream(fis);
        }
    }

    private boolean isGZIPStream(FileInputStream fis) throws IOException {
        byte[] bytes = new byte[2];
        if (fis.read(bytes, 0, 2) != 2) {
            throw new IllegalStateException("Couldn't read file header");
        }
        return bytes[0] == (byte) GZIPInputStream.GZIP_MAGIC && bytes[1] == (byte) (GZIPInputStream.GZIP_MAGIC >> 8);
    }
}
```

This code is a simplified version of what your method might look like, and it doesn't handle transient failures or updates in a distributed system. It would also need to be extended to support network I/O for loading states from remote files or across different nodes in a distributed system. You would need to use appropriate libraries (like Apache Commons Compress) instead of manually checking the file header for GZIP streams.
