typedef struct {
    uint64_t timestamp;
    float SNR;
    int errorCode;
} LTE_PHY_RX_SRB1_PDU_T;

typedef struct Node {
    LTE_PHY_RX_SRB1_PDU_T data;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
int size = 0;
const int MAX_SIZE = 10000;

void* allocate(size_t size) {
    void* memory = malloc(size);
    if (memory == NULL && size != 0) {
        log_details("Failed to allocate memory");
        return NULL;
    }
    return memory;
}

void deallocate(void *p){
    free(p);
}

Node* create_node(uint64_t timestamp, float SNR, int errorCode) {
    Node *newNode = allocate(sizeof(Node));
    if (newNode == NULL) { return NULL; }

    newNode->data.timestamp = timestamp;
    newNode->data.SNR = SNR;
    newNode->data.errorCode = errorCode;
    newNode->next = NULL;

    return newNode;
}

void add_node(uint64_t timestamp, float SNR, int errorCode) {
    pthread_mutex_lock(&lock);

    if (size >= MAX_SIZE) {
        log_details("Max size reached");
        return;
    }

    Node *newNode = create_node(timestamp, SNR, errorCode);
    if (newNode == NULL) { 
        pthread_mutex_unlock(&lock);
        return; 
    }

    newNode->next = head;
    head = newNode;
    size++;

    pthread_mutex_unlock(&lock);
}
