        logError("Failed to allocate memory for packet list");
        return NULL;
    }

    list->capacity = initialCapacity;
    list->size = 0;
    list->records = malloc(initialCapacity * sizeof(packet_record));

    if (!list->records) {
        logError("Failed to allocate memory for packet records");
        free(list);
        return NULL;
    }

    return list;
}

void appendRecord(PacketList* list, packet_record record) {
    while (atomic_flag_test_and_set(&list->lock)); // spin lock start

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        packet_record* tempRecords = realloc(list->records, newCapacity * sizeof(packet_record));

        if (!tempRecords) {
            logError("Failed to resize memory for packet records");
            atomic_flag_clear(&list->lock); // spin lock end
            return;
        }

        list->records = tempRecords;
        list->capacity = newCapacity;
    }

    list->records[list->size++] = record;

    atomic_flag_clear(&list->lock); // spin lock end
}

