#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* read_file(FILE *fp, Node **head) {
    if (fp == NULL) return -1;

    int num;
    while(fscanf(fp, "%d", &num) == 1){
        push(head, num);
    }
}

void push(Node** head_ref, int new_data){
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->value  = new_data;
    new_node->next = (*head_ref);    
    (*head_ref)    = new_node;
} 

int findMax(Node *node){
    int max = 0;
    while (node != NULL){
       if(max < node->value) {
          max = node->value;
        }
        node = node->next;
    }     
    return max; 
}

void write_output(FILE *fp, int max_num){
    fprintf(fp, "%d", max_num);
}

int main(int argc, char** argv) {
    if (argc != 3) {
        printf("Incorrect arguments. Usage: ./program input.txt output.txt\n");
        return -1;
    }

    FILE *input_fp = fopen(argv[1], "r");
    if(input_fp == NULL){
      perror("Failed to open the file.");
      return errno;
    }

    Node* head = NULL;
    read_file(input_fp, &head);

    int maxNum = findMax(head);

    FILE *output_fp = fopen(argv[2], "w");
    if(output_fp == NULL){
      perror("Failed to open the file.");
      return errno;
    }

    write_output(output_fp, maxNum);

    fclose(input_fp);
    fclose(output_fp);
    return 0;
}
