    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = *head;
    *head = newNode;

    atomic_fetch_add(size, 1);

    pthread_mutex_unlock(&list.mutex);
}

LTE_PHY_RX_SRB1_PDU_T* pop(_Atomic(int)* size, Node** head) {
