    GTPV2_MESSAGE_ARRAYS* arrays = malloc(sizeof(GTPV2_MESSAGE_ARRAYS));
    assert(arrays != NULL); // Handle memory allocation failure gracefully
    memset(arrays, 0, sizeof(GTPV2_MESSAGE_ARRAYS));
    pthread_mutex_init(&arrays->lock, NULL);
    return arrays;
}

void addMessageToArrays(GTPV2_MESSAGE_ARRAYS* arrays, TAI taiIdentifier, int packetRateIndex) {
    assert(arrays != NULL && packetRateIndex >= 0 && packetRateIndex < MAX_SIZE); // Ensure input data is valid

    pthread_mutex_lock(&arrays->lock); // Lock for concurrent write access
    if (arrays->size >= MAX_SIZE) {
        // Log detailed error information and handle memory allocation failure gracefully
        LOGGER_INTERFACE("Error: Unable to add message. Max size of arrays reached.");
        pthread_mutex_unlock(&arrays->lock);
        return;
    }

    // Add the new message to the arrays
    arrays->taiIdentifiers[arrays->size] = taiIdentifier;
    arrays->packetRateIndices[arrays->size] = packetRateIndex;
    ++arrays->size;

    pthread_mutex_unlock(&arrays->lock); // Unlock after write access
}
``` 

This is a simple skeleton and does not include all required functionality like error handling, logging, memory pool management, etc. Writing the complete solution within this box would be too large and complex. This solution also doesn't handle network dependencies or third-party libraries integration as it's beyond the scope of this task and may require detailed understanding of your specific requirements. 

