import dns.resolver  # pip install dns-python
from threading import Lock

class DNSService:
    def __init__(self):
        self._lock = Lock()

    def resolve_hostname(self, hostname):
        with self._lock:
            try:
                result = dns.resolver.query(hostname, 'A')  # A stands for IP address type
                return [int(ip) for ip in str(result[0]).split('.')]  # convert string to list of ints
            except Exception as e:
                print("Error resolving hostname", e)
                return None
```
**Python Component (MD5 Hash Calculation)**
```python
import hashlib
from threading import Lock

class MD5Service:
    def __init__(self):
        self._lock = Lock()

    def calculate_hash(self, filepath):
        with self._lock:
            try:
                md5_hash = hashlib.md5()
                with open(filepath,"rb") as f:
                    for byte_block in iter(lambda: f.read(4096),b""):  # read file in chunks
                        md5_hash.update(byte_block)
                return md5_hash.hexdigest()
            except Exception as e:
                print("Error calculating hash", e)
                return None
```
The above Python code uses the `dns-python` library for DNS resolution and built-in `hashlib` module for MD5 calculation. The components are thread safe by using `threading.Lock()` to ensure that only one thread can access the shared data at a time, thus maintaining consistency of data across multiple threads concurrently accessing it.

**C Component (DNS Resolution)**
```c
#include <netdb.h>
#include <arpa/inet.h>
#include <stdio.h>
#include <string.h>

struct hostent *he;
char ip_address[INET6_ADDRSTRLEN];
u_char address_array[4];

void resolve_hostname(const char* hostname) {
    if ((he=gethostbyname(hostname)) == NULL) { 
        herror("gethostbyname");
        return;
    }
    inet_ntop(AF_INET, (struct in_addr*)he->h_addr_list[0], ip_address, sizeof ip_address);

    // convert string IP to u_char array
    sscanf(ip_address, "%hu.%hu.%hu.%hu", &address_array[0], &address_array[1], &address_array[2], &address_array[3]);
}
