['```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>
#include <string.h>

#define BUF_SIZE 4096

typedef struct Config {
    EVP_CIPHER* (*cipher)(void);
    int key_size;
    const EVP_MD* digest;
} Config;

int loadConfig(const char *filename, Config *config) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // Error opening file
    }

    /* Read from the configuration file and initialize config struct */
    const EVP_CIPHER *(*cipher)(void);
    int key_size;
    const EVP_MD *digest;

    if (fscanf(file, "Cipher: %p", &cipher) != 1 || cipher == NULL ||
        fscanf(file, "KeySize: %d", &key_size) != 1 ||  key_size <= 0 ||
        fscanf(file, "Digest: %p", &digest) != 1 || digest == NULL) {
        return -2; // Error reading config
    }

    config->cipher = cipher;
    config->key_size = key_size;
    config->digest = digest;
    fclose(file);
    return 0; // Success
}

int processData(const Config *config, unsigned char *in, int inLen, unsigned char **out, int *outLen) {
    if (!EVP_CIPHER_CTX_init(&ctx)) {
        /* Error */
        return -1;
    }

    /* Set up the context */
    ctx.cipher = config->cipher();
    ctx.key_len = config->key_size / 8;
    ctx.md = config->digest();

    if (!EVP_DigestInit(&ctx)) {
        /* Error */
        return -2;
    }

    if (!EVP_DigestUpdate(&ctx, in, inLen)) {
        /* Error */
        return -3;
    }

    *out = malloc(BUF_SIZE);
    unsigned char tmp[BUF_SIZE];
    while ((*outLen = EVP_DigestFinal(&ctx, tmp, NULL))) {
        if (*outLen == -1) {
            /* Error */
            return -4;
        }

        *out = realloc(*out, *outLen);
        memcpy(*out + outLen, tmp, *outLen);
    }

    EVP_CIPHER_CTX_cleanup(&ctx);
    return 0; // Success
}
```
