const { EventEmitter } = require('events');
const sqlite3 = require('sqlite3').verbose();
let db = new sqlite3.Database('./booksdb.db', (err) => {
    if(err){
        console.error(`Error connecting to database: ${err}`);
    } else {
        console.log("Connected to the SQLite database!");
        db.run("CREATE TABLE IF NOT EXISTS books ("+
            "id INTEGER PRIMARY KEY, "+
            "title TEXT, "+
            "yearOfPublication INTEGER"+
        ")");
    }
});

const bookData = JSON.parse(fs.readFileSync('books.json'));
const booksRegex = new RegExp("\\b(" + bookData.join("|") + ")\\b", 'i'); 
let emitter = new EventEmitter();
emitter.setMaxListeners(0); // set to infinity if you need more than 10 listeners

const processTextAndExecuteQuery = async (text) => {
    let matches = text.match(booksRegex);
    let bookCounts = {};
    for (let match of matches){
        if(!bookCounts[match]){
            bookCounts[match] = 1;
        } else {
            bookCounts[match]++;
        }
    }

    const query = "SELECT * FROM books WHERE title IN (" + Object.keys(bookCounts).join(", ") + ")";
    let statement = await new Promise((resolve, reject) => {
        db.each(query, (err, row) => {
            if(err){
                reject(`Error executing query: ${err}`);
            } else {
                resolve(row);
            }
        });
    });

    emitter.emit('data', statement);
};

emitter.on('error', (err) => console.log(`Error event: ${err}`));

processTextAndExecuteQuery("The books that were read were Old Testament, New Testaments and other unrelated books.").catch((e) => console.error(e));
