['Sure, here's a simple implementation in C using pthreads for multi-threading:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>

int* array;
int size = 0, max_size = 1000;
char async = 0; // 0 for synchronous, 1 for asynchronous
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void read_data(int rounding) {
    array = (int*)malloc(max_size * sizeof(int));
    if (!array) {
        printf("Failed to allocate memory\n");
        exit(1);
    }

    char buffer[20];
    while(scanf("%s", buffer) != EOF && size < max_size){
        if (strchr(buffer, '.') == NULL) {
            array[size++] = atoi(buffer); // reading integers
        } else {
            float f = atof(buffer);
            switch(rounding) {
                case 0: // Round to nearest
                    array[size++] = (int)(f + 0.5);
                    break;
                case 1: // Floor
                    array[size++] = (int)floor(f);
                    break;
                case 2: // Ceiling
                    array[size++] = (int)ceil(f);
                    break;
            }
        }
    }
}

void* largest_value() {
    int maxVal = array[0];
    for(int i=1; i<size; ++i){
        if(array[i] > maxVal) maxVal = array[i];
    }

    printf("Largest value: %d\n", maxVal);
}

void* thread_function() {
    pthread_mutex_lock(&lock);
    largest_value();
    pthread_mutex_unlock(&lock);
}

int main(int argc, char** argv) {
    if (argc < 2 || argc > 3) {
        printf("Usage: ./program maxSize [roundingMethod]\n");
        return 1;
    }

    max_size = atoi(argv[1]);
    if (max_size > 1000) max_size = 1000;

    int rounding = 0; // Default to nearest integer by default
    if (argc == 3) rounding = atoi(argv[2]); 

    read_data(rounding);

    if (!async) {
        largest_value();
    } else {
        pthread_t thread;
        int res = pthread_create(&thread, NULL, &thread_function, NULL);

        if (res != 0) {
            perror("Thread creation failed");
            return 1;
        }

        res = pthread_join(thread, NULL);
        if (res != 0) {
            perror("Error in thread join");
            return 1;
        }
    }

    free(array);
    return 0;
}
```

This program first takes the maximum size and rounding method as command line arguments. It then reads a list of numbers from standard input, converting them to integers or using the specified rounding method if they're floating point values. The largest integer value is found either synchronously (default) or asynchronously based on a flag set at compile time. If the latter option is chosen, it uses pthreads for thread creation and management, ensuring safe access to shared memory. It also utilizes a mutex lock for thread synchronization.

