typedef struct DynamicValueManager {
    atomic_int minValue;
    atomic_int maxValue;
    _Atomic long totalValues;
} DynamicValueManager;

void ResetStatistics(DynamicValueManager* dvm) {
    atomic_init(&dvm->minValue, INT_MAX);
    atomic_init(&dvm->maxValue, INT_MIN);
    atomic_store(&dvm->totalValues, 0L);
}

void DynamicValueManager_AdjustRange(DynamicValueManager* dvm, int newMin, int newMax) {
    if (newMin > newMax) return;
    if (atomic_load(&dvm->minValue) < newMin) atomic_store(&dvm->minValue, newMin);
    if (atomic_load(&dvm->maxValue) > newMax) atomic_store(&dvm->maxValue, newMax);
}

int DynamicValueManager_GetRandomInt(DynamicValueManager* dvm) {
    int min = atomic_load(&dvm->minValue);
    int max = atomic_load(&dvm->maxValue);
    return rand() % (max - min + 1) + min;
}

float DynamicValueManager_GetRandomFloat(DynamicValueManager* dvm) {
    float min = (float)atomic_load(&dvm->minValue);
    float max = (float)atomic_load(&dvm->maxValue);
    return min + ((float)rand() / (float)(RAND_MAX)) * (max - min);
}

float DynamicValueManager_GetAdjustedValue(DynamicValueManager* dvm, float value) {
    int min = atomic_load(&dvm->minValue);
    int max = atomic_load(&dvm->maxValue);
    if (value < min) return (float)min;
    else if (value > max) return (float)max;
    else return value;
}
```
