```csharp
#include <random>
#include <mutex>
#include <atomic>
#include <vector>
#include <iostream>
#include <algorithm>
#include <iterator>

std::default_random_engine generator;
std::uniform_real_distribution<float> distribution(0.0, 1.0);
std::mutex mtx;
std::atomic<double> totalSum{0};
std::atomic<int> numValues{0};

class DynamicValueManager {
private:
    std::atomic<float> minValue;
    std::atomic<float> maxValue;
public:
    DynamicValueManager(float initMin, float initMax) : minValue(initMin), maxValue(initMax){}

    float GetRandomFloat() {
        std::lock_guard<std::mutex> lock(mtx);
        return distribution(generator) * (maxValue - minValue) + minValue;
    }

    int GetRandomInt() {
        std::lock_guard<std::mutex> lock(mtx);
        return static_cast<int>(distribution(generator) * (maxValue - minValue + 1)) + minValue;
    }

    void AdjustRange(float newMin, float newMax){
        std::lock_guard<std::mutex> lock(mtx);
        if(newMin > newMax){
            std::swap(newMin, newMax);
        }
        minValue = newMin;
        maxValue = newMax;
    }

    float GetAdjustedValue(float value) {
        std::lock_guard<std::mutex> lock(mtx);
        if(value < minValue){
            return minValue;
        } else if (value > maxValue){
            return maxValue;
        } else{
            totalSum += value;
            numValues++;
            return value;
        }
    }

    float GetCurrentAverage(){
        std::lock_guard<std::mutex> lock(mtx);
        if(numValues == 0){
            return 0.0f;
        } else{
            return totalSum / numValues;
        }
    }

    void ResetStatistics(){
        std::lock_guard<std::mutex> lock(mtx);
        totalSum = 0;
        numValues = 0;
    }
};
```

