['Here's an outline of how you can implement this kind of function in C using POSIX threads (pthread). Note that the actual code would be quite lengthy and complex, so I will provide a very simplified version to give you an idea of what such function might look like.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Add your fields for image processing tasks here
} Task;

typedef struct {
    int uniqueTaskID;  // Unique task ID
    void* inputImageBuffer;  // Input image buffer
    void** outputBufferPointer;  // Output buffer pointers
} TaskContext;

// Queue data structure for tasks
typedef struct Node {
    Task *task;
    struct Node *next;
} Node;

Node *front = NULL, *rear = NULL;
pthread_mutex_t lock;
int taskCount = 0;
#define MAX_TASKS 200

// Enqueue operation for the queue data structure
void enqueue(Task *task) {
    pthread_mutex_lock(&lock);
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->task = task;
    temp->next = NULL;
    if (front == NULL && rear == NULL){
        front = rear = temp;
    } else {
        rear->next = temp;
        rear = temp;
    }
    taskCount++;
    pthread_mutex_unlock(&lock);
}

// Dequeue operation for the queue data structure
Task* dequeue() {
    pthread_mutex_lock(&lock);
    Task* result = NULL;
    if (front != NULL) {
        Node* temp = front;
        result = front->task;
        front = front->next;
        free(temp);
        taskCount--;
    }
    pthread_mutex_unlock(&lock);
    return result;
}

// Worker thread function that processes tasks
void* workerThread(void* arg) {
    while (1) {
        Task *task = dequeue();
        if (task != NULL) {
            // Process the task here
        } else {
            break;  // Break from loop when there's no more tasks to process
        }
    }
    return NULL;
}

// The main function that processes multi-threaded image processing tasks
void* processMultiThreadedImageProcessingTasks(TaskContext *taskContext, int numTasks) {
    // Initialize mutex for thread safety
    pthread_mutex_init(&lock, NULL);

    // Start worker threads
    pthread_t workerThreads[MAX_TASKS];
    for (int i = 0; i < MAX_TASKS; ++i) {
        if(pthread_create(&workerThreads[i], NULL, &workerThread, NULL) != 0){
            printf("Failed to create thread\n");
            return NULL;
        }
    }

    // Enqueue tasks for processing
    for (int i = 0; i < numTasks; ++i) {
        enqueue(taskContext[i].task);
    }

    // Join worker threads and clean up
    for (int i = 0; i < MAX_TASKS; ++i) {
        if(pthread_join(workerThreads[i], NULL) != 0){
            printf("Error: Failed to join thread\n");
            return NULL;
        }
    }
    pthread_mutex_destroy(&lock);
}
```
