    users = fetch_data(args.endpoint, args.auth_token)
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_data, user, 'rules'): user for user in users}

        # Process and update preferences
        for future in concurrent.futures.as_completed(futures):
