    size_t allocatedSize;
} AllocationInfo;

AllocationInfo allocations[1024];
size_t numAllocations = 0;

void logAllocation(char *buffer, size_t size) {
    if (numAllocations < 1024) {
        AllocationInfo *info = &allocations[numAllocations++];
        info->totalSize = size;
        info->allocatedSize = malloc_usable_size(buffer);
    }
}

size_t copyStringWithLimit(const char *src, size_t limit, char *dst, size_t *counter) {
    if (strlen(src) <= limit - 1) {
        strncpy(dst, src, limit);
        dst[limit-1] = '\0'; // Ensure null termination.
        (*counter)++;
        return strlen(dst);
    } else {
        *counter = 0;
        return 0;
    }
}
```

In this example, we keep track of all allocations using an array called `allocations`. We also store the total size and allocated size of each allocation for logging purposes. The function `logAllocation` logs a new allocation by incrementing `numAllocations` and storing information about the allocation in the next slot of the `allocations` array.

The function `copyStringWithLimit` copies the string from `src` to `dst`, provided that `src` is not longer than `limit - 1` characters (leaving room for a null termination character). If the copy was successful, it increments `*counter` and returns the length of `dst`. If the copy would have exceeded `limit`, it sets `*counter` to zero and returns zero.
