// Define your own data structure here, as this is just an example
typedef struct {
    int field1;
    float field2;
} MyStruct;

static pcg32 rng(42u); // PRNG with a seed value
extern bool g_logEnabled; // Global flag for logging configuration
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread-safe operations

int deserializeAndInitializeData(const char* filename, MyStruct** data) {
    if (g_logEnabled) printf("Starting deserialization.\n");

    FILE *file = fopen(filename, "rb"); // Open file in binary mode
    if (file == NULL) {
        if (g_logEnabled) printf("Error opening file: %s\n", filename);
        return -1;
    }

    // Determine size of the data structure in bytes
    fseek(file, 0L, SEEK_END);
    long numbytes = ftell(file);
    fseek(file, 0L, SEEK_SET);	

    *data = (MyStruct*) malloc(numbytes); // Allocate memory for the structure
    if (*data == NULL) {
        if (g_logEnabled) printf("Memory allocation failed.\n");
        return -1;
    }

    size_t readSize = fread(*data, numbytes, 1, file); // Read from binary file into memory
    if(numbytes != readSize){
        if (g_logEnabled) printf("File reading failed.\n");
        free(*data); *data = NULL;
        return -1;
    }

    fclose(file); // Close the file

    pthread_mutex_lock(&lock);  // Start of critical section for thread-safe operations

    /* Initialize your data here */

    pthread_mutex_unlock(&lock);  // End of critical section

    if (g_logEnabled) printf("Deserialization and initialization completed.\n");

    return numbytes;
}

double randomDouble(double min, double max){ // Function to generate a floating-point value between the specified range.
