        String hash = cache.get(message);
        if (hash == null) {
            byte[] digest = md5Hasher.digest(message.getBytes(StandardCharsets.UTF_8));
            hash = bytesToHex(digest);
            cache.set(message, hash); // Cache the computed MD5 for future reference
        }

        logger.info("Message processed: " + message);
    }

    // Utility method to convert byte array to hexadecimal string
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
