#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#define MAX_ENTRIES 10000

// Custom memory pool
typedef struct {
    char* key;
    char* value;
    time_t timestamp;
    int expirationTime;
} entry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
entry** entriesPool[MAX_ENTRIES];
int currentSize = 0;

// Logger interface
void logError(char* errorMsg) {
    // Implement actual logging mechanism here
}

// Memory pool functions
entry* allocateEntry() {
    entry* newEntry = (entry*) malloc(sizeof(entry));
    if (!newEntry) {
        logError("Memory allocation failed.");
        return NULL;
    }

    // Initialize entry
    newEntry->key = NULL;
    newEntry->value = NULL;
    newEntry->timestamp = 0;
    newEntry->expirationTime = 0;

    return newEntry;
}

void addToPool(entry* newEntry) {
    if (currentSize >= MAX_ENTRIES) {
        logError("Memory pool is full.");
        free(newEntry);
        return;
    }

    entriesPool[currentSize++] = newEntry;
}

// Thread-safe read/write access functions
entry* getEntryFromKey(char* key) {
    pthread_mutex_lock(&lock);

    entry* targetEntry = NULL;
    for (int i = 0; i < currentSize; ++i) {
        if (!strcmp(entriesPool[i]->key, key)) {
            targetEntry = entriesPool[i];
            break;
        }
    }

    pthread_mutex_unlock(&lock);
    return targetEntry;
}

void insertNewKeyValuePair(char* key, char* value, int expirationTime) {
    entry* newEntry = allocateEntry();
    if (!newEntry) {
        logError("Failed to add new entry.");
        return;
    }

    // Set values for the new entry
    newEntry->key = key;
    newEntry->value = value;
    newEntry->timestamp = time(NULL);
    newEntry->expirationTime = expirationTime;

    pthread_mutex_lock(&lock);
    addToPool(newEntry);
    pthread_mutex_unlock(&lock);
}
``` 

This is a very basic implementation and lacks many important features such as handling memory deallocation, retry logic for allocation failures, dynamic resizing of the memory pool, and sophisticated memory management strategies. Each of these components would require their own detailed implementations which have not been included in this example code for brevity's sake.
