bool validateToken(const char* json_string) {
    const cJSON *json = cJSON_Parse(json_string);

    if (!cJSON_HasObjectItem(json, "access_token") ||
        !cJSON_HasObjectItem(json, "expires_in") ||
        !cJSON_HasObjectItem(json, "token_type")) {
            cJSON_Delete(json);
            return false;
    }

    const cJSON *tokenType = cJSON_GetObjectItemCaseSensitive(json, "token_type");
    const cJSON *expiresIn = cJSON_GetObjectItemCaseSensitive(json, "expires_in");

    if (!cJSON_IsString(tokenType) || strcmp(tokenType->valuestring, "Bearer") != 0 ||
        !cJSON_IsNumber(expiresIn) || expiresIn->valueint <= 0) {
            cJSON_Delete(json);
            return false;
    }

    cJSON_Delete(json);

    return true;
}
