["Here's a basic C solution that implements the `FrameProcessor` class with necessary fields and methods along with thread safety using pthread mutex locks. Also, it does not consider all edge cases but provides a base to add more in future as required. This is quite a big task and may need additional components for a full solution like error handling, testing etc.

```C
#include <pthread.h>
#include <stdlib.h>

typedef struct FrameMetadata {
    long timestamp;
    int sequenceNumber;
    size_t payloadSize;
} FrameMetadata;

typedef struct FrameProcessor {
    FrameMetadata* buffer;
    size_t currentFrameCount;
    size_t bufferSize;
    pthread_mutex_t lock;
    long currentTimestamp;
    int lastSequenceNumber;
    size_t frameCount;
} FrameProcessor;

void AddFrame(FrameProcessor* processor, FrameMetadata metadata) {
    if (processor == NULL || processor->buffer == NULL || 
        processor->currentFrameCount >= processor->bufferSize) return;

    pthread_mutex_lock(&processor->lock);

    if (metadata.sequenceNumber > processor->lastSequenceNumber && 
        processor->currentFrameCount < processor->bufferSize){

        processor->buffer[processor->currentFrameCount++] = metadata;
        processor->frameCount++;
        processor->lastSequenceNumber = metadata.sequenceNumber;
    }

    pthread_mutex_unlock(&processor->lock);
}

void ProcessFrames(FrameProcessor* processor) {
    if (processor == NULL || processor->buffer == NULL) return;

    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->currentFrameCount; ++i){
        FrameMetadata metadata = processor->buffer[i];

        // Perform frame processing here.

        if(metadata.timestamp > processor->currentTimestamp) {
            processor->currentTimestamp = metadata.timestamp;
        }
    }

    pthread_mutex_unlock(&processor->lock);
}

FrameMetadata GetLatestFrame(const FrameProcessor* processor) {
    FrameMetadata latestFrame;
    if (processor == NULL || processor->buffer == NULL || 
        processor->currentFrameCount == 0) return latestFrame;

    pthread_mutex_lock(&processor->lock);

    long maxTimestamp = processor->buffer[0].timestamp;
    size_t indexOfMax = 0;

    for(size_t i = 1; i < processor->currentFrameCount; ++i) {
        if (processor->buffer[i].timestamp > maxTimestamp){
            maxTimestamp = processor->buffer[i].timestamp;
            indexOfMax = i;
        }
    }

    latestFrame = processor->buffer[indexOfMax];

    pthread_mutex_unlock(&processor->lock);

    return latestFrame;
}

void ResetBuffer(FrameProcessor* processor) {
    if (processor == NULL || processor->buffer == NULL) return;

    pthread_mutex_lock(&processor->lock);

    for(size_t i = 0; i < processor->currentFrameCount; ++i){
        // Perform necessary cleanup on each frame here.
    }

    free(processor->buffer);

    pthread_mutex_unlock(&processor->lock);
}
```
This is just the basic solution, you would need to add all the edge cases as mentioned in task and optimize it further based on your needs. This code also lacks a lot of error checking for production level code, you would want to add assertions or other checks as per your requirement. Also remember that pthread_mutex locks are quite expensive in terms of system resource usage so use them judiciously.
"]

