        return false;
    }

    return true;
}

// Prune the pool using a sliding window approach
void prunePool(Pool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size > WINDOW_SIZE) {
        for (int i = 0; i < pool->size - WINDOW_SIZE; ++i) {
            free(pool->data[i]); // Free memory of structures no longer needed
        }

        memmove(pool->data, &pool->data[pool->size - WINDOW_SIZE], WINDOW_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        pool->size = WINDOW_SIZE; // Update size after pruning

