#include <errno.h>

struct conn_session {
    struct bufferevent *bev;
    evutil_socket_t fd;
    char session_id[37]; // UUID length + null terminator
    struct sockaddr_in client_addr;
};

static void readcb(struct bufferevent *bev, void *ctx) {
    struct conn_session *conn = (struct conn_session *) ctx;
    // handle data from the socket here 
}

static void errorcb(struct bufferevent *bev, short events, void *ctx) {
    if (events & BEV_EVENT_EOF) {
        // Socket has been closed. Free resources and cleanup here.
    } else if (events & BEV_EVENT_ERROR) {
        // An error occurred on the socket. Handle it here.
    }
}

struct conn_session *create_conn(const char *ip, int port, const char *id) {
    struct sockaddr_in sin;
    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    evutil_inet_pton(AF_INET, ip, &sin.sin_addr);
    sin.sin_port = htons(port);

    struct event_base *base = event_base_new();

    int sockfd = socket(PF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        // Error handling here
    }

    struct conn_session *conn = malloc(sizeof(*conn));
    conn->bev = bufferevent_socket_new(base, sockfd, BEV_OPT_CLOSE_ON_FREE);
    conn->client_addr = sin;
    strcpy(conn->session_id, id);

    bufferevent_setcb(conn->bev, readcb, NULL, errorcb, conn);
    bufferevent_enable(conn->bev, EV_READ | EV_WRITE);

    if (connect(sockfd, (struct sockaddr *) &sin, sizeof(sin)) < 0) {
        // Error handling here
    }

    return conn;
}
```
