struct ServerConfig {
    int port;
    char *bindaddr;
};

typedef struct StatsServer {
    struct event_base *evbase; 
    struct evhttp *server;
    struct ServerConfig config;
    pthread_t threadId;
} StatsServer;

StatsServer* createServer(struct ServerConfig config) {
    // Initialize the server structure
    StatsServer *server = malloc(sizeof(StatsServer));

    if (!server) return NULL;

    server->config = config;
    server->evbase = event_base_new();

    if (!server->evbase) {
        free(server);
        return NULL; 
    }

    // Initialize the HTTP server and bind it to a specific port/address
    server->server = evhttp_new(server->evbase);

    if (!server->server || evhttp_bind_socket(server->server, config.bindaddr, config.port) != 0) {
        free(server->evbase); 
        free(server); 
        return NULL;
    }

    // Initialize endpoints here...

    return server;
}

void* runServerThread(void *arg) {
    StatsServer *server = (StatsServer *) arg;

    event_base_dispatch(server->evbase); 

    evhttp_free(server->server);
    event_base_free(server->evbase);
}

void startServer(StatsServer *server) {
    pthread_create(&server->threadId, NULL, runServerThread, server);
}

int main() {
    struct ServerConfig config; 

    // Configure the server...

    StatsServer *server = createServer(config);

    if (!server) {
        fprintf(stderr, "Failed to create HTTP server\n");
        return 1;
    }

    startServer(server);

    // Server setup complete. Wait for exit signal...

    pthread_join(server->threadId, NULL);
}
```

