```c
int addSession(Node** head, int* active_sessions, int max_sessions, int id) {
    // Check if adding this session would exceed maximum
    if (*active_sessions >= max_sessions) {
        removeOldestSession(head); 
    }

    Node* newNode = (Node*)malloc(sizeof(Node)); 
    if (newNode == NULL) return -1; // out of memory
    newNode->session->session_id = id;
    newNode->session->timestamp = time(NULL);
    newNode->next = *head;
    *head = newNode; 

    (*active_sessions)++; // Increment session count
    return 0;
}
```
3. Implement a function to remove the oldest session:
```c
void removeOldestSession(Node** head) {
    if(*head == NULL) return;

    Node* current = *head;
    while (current->next != NULL && current->next->session->timestamp < (*head)->session->timestamp){
        current = current->next;
    }

    // Remove the oldest session node
    if(current == *head) { 
        *head = (*head)->next; 
    } else{
        Node* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}
