Address* readNetworkConfigFile(char* filename, int *count) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    Address* addresses = malloc(MAX_ENTRIES * sizeof(Address));
    char line[MAX_LINE];
    int i = 0;

    while ((fgets(line, MAX_LINE, file)) != NULL && i < MAX_ENTRIES) {
        // Assume that each line is in the format "IP:port"
        addresses[i].ip = malloc((strlen(line) + 1) * sizeof(char));
        sscanf(line, "%[^:]:%d", addresses[i].ip, &addresses[i].port);
        ++i;
    }

    fclose(file);
    validateAddressesAndFreeResources(addresses, i);
    *count = i;
    return addresses;
}
