typedef struct CacheItem {
    int key;
    void *value;
    size_t size;
    unsigned long timestamp;
    struct CacheItem *prev, *next;
} CacheItem;

typedef struct DistributedCache {
    pthread_mutex_t lock;
    sem_t availableItems;
    size_t totalSize;
    size_t maxSize;
    unsigned long timestampCounter;
    double loadFactor;
    size_t evictionThreshold;
    CacheItem *leastRecentlyUsed, *mostRecentlyUsed;
} DistributedCache;

DistributedCache* createDistributedCache(size_t initialSize) {
    DistributedCache *cache = malloc(sizeof(DistributedCache));
    if (!cache) return NULL;

    cache->totalSize = 0;
    cache->maxSize = initialSize;
    cache->timestampCounter = 0;
    cache->loadFactor = 0.75; // adjust as needed
    cache->evictionThreshold = initialSize * 0.25; // start with a conservative eviction threshold

    pthread_mutex_init(&cache->lock, NULL);
    sem_init(&cache->availableItems, 0, initialSize);

    cache->leastRecentlyUsed = cache->mostRecentlyUsed = NULL;

    return cache;
}

// Note: Implementation of the addItem function is complex and depends on how you manage memory in your system.
// Here's a skeleton to get you started:
void addItem(DistributedCache *cache, int key, void *value, size_t size) {
    pthread_mutex_lock(&cache->lock);

    // Evict items if necessary
    while (cache->totalSize + size > cache->maxSize && cache->leastRecentlyUsed) {
        evictLeastRecentlyUsedItem(cache);
    }

    CacheItem *newItem = malloc(sizeof(CacheItem));
    newItem->key = key;
    newItem->value = value;
    newItem->size = size;
    newItem->timestamp = cache->timestampCounter++;

    // Add the item to the front of the LRU list
    if (!cache->mostRecentlyUsed) {
        cache->leastRecentlyUsed = cache->mostRecentlyUsed = newItem;
    } else {
        newItem->next = cache->mostRecentlyUsed;
        cache->mostRecentlyUsed->prev = newItem;
        cache->mostRecentlyUsed = newItem;
    }

    // Add the item to your actual data structure here...

    sem_post(&cache->availableItems);
    pthread_mutex_unlock(&cache->lock);
}
