    for (size_t i = 0; i < MAX_NUMBER_OF_ALLOCATIONS; ++i) {
        if (cachedAllocations[i].memoryPointer == NULL) {
            cachedAllocations[i] = info;
            break;
        }
    }

    return structures;
}

void deallocateStructures(FAPI_CRC_INDICATION_PDU_T *structures) {
    pthread_mutex_lock(&info.mutex); // lock mutex before freeing memory
    free(structures);
    pthread_mutex_unlock(&info.mutex); // unlock mutex after memory is freed

    for (size_t i = 0; i < MAX_NUMBER_OF_ALLOCATIONS; ++i) {
        if (cachedAllocations[i].memoryPointer == structures) {
            memset(&cachedAllocations[i], 0, sizeof(AllocationInfo)); // clear cache entry after deallocation
