public class MessageProcessor {
    private static final Log log = LogFactory.getLog(MessageProcessor.class);
    private Jedis jedis;
    private ExecutorService executor;
    private ReentrantLock lock;
    private Semaphore semaphore;

    public MessageProcessor() {
        this.jedis = new Jedis("localhost"); // assuming you're using Redis as cache
        this.executor = Executors.newFixedThreadPool(10); // 10 threads for concurrency control
        this.lock = new ReentrantLock(); // lock for managing file accesses
        this.semaphore = new Semaphore(10); // semaphore to limit requests
    }

    public void processMessage(String message) {
        executor.execute(() -> {
            try {
                semaphore.acquire(); // acquire a permit from the semaphore

                String hash = getMD5Hash(message);
                jedis.set(hash, message);
                log.info("Processed message: " + hash);

                semaphore.release(); // release the permit back to the semaphore
            } catch (Exception e) {
                log.error("Error processing message", e);
            }
        });
    }

    private String getMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes());
        return DatatypeConverter.printHexBinary(digest).toUpperCase();
    }

    public String modifyAndLoadFilename(String filename) {
        lock.lock(); // acquire the lock to ensure exclusive access to the file

        try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(Paths.get(filename)))) {
            MoSTState loadedObj = (MoSTState) ois.readObject();

            if (loadedObj == null) {
                log.warn("Loaded object is null");
                return null;
            }

            String newFilename = modifyExtension(filename);
            jedis.set(newFilename, loadedObj); // cache the loaded object
            return newFilename;
        } catch (Exception e) {
            log.error("Error loading file", e);
            return null;
        } finally {
            lock.unlock(); // release the lock
        }
    }

    private String modifyExtension(String filename) {
        int dotIndex = filename.lastIndexOf('.');

        if (dotIndex == -1 || dotIndex + 6 > filename.length()) {
            return filename;
        }

        String sequence = Integer.toString((filename.hashCode() % 90000) + 10000); // generate a unique sequence based on the filename's content
        return filename.substring(0, dotIndex) + sequence + filename.substring(dotIndex);
    }

    public void close() {
        executor.shutdown();
        jedis.close();
    }
}
