        if (filename.length() > MAX_FILENAME_LENGTH) {
            filename = filename.substring(0, MAX_FILENAME_LENGTH);
        }

        String[] parts = filename.split("\\.", -1);
        int sequence = 0;
        for (char c : filename.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                sequence += c;
            }
        }

        String extension = parts[parts.length-1];
        if (extension.isEmpty()) {
            extension = DEFAULT_EXTENSION;
        }

        filename = filename + String.format("%05d", sequence) + extension;

        try {
            fileLock.lock();

            Object stateObj;
            File f = new File(filename);
            if (f.exists() && !f.isDirectory()) {
                FileInputStream fis = new FileInputStream(filename);
                ObjectInputStream ois = new ObjectInputStream(fis);

                stateObj = ois.readObject();
                ois.close();
                fis.close();
            } else {
                stateObj = new MoSTState();
                FileOutputStream fos = new FileOutputStream(filename);
                ObjectOutputStream oos = new ObjectOutputStream(fos);

                oos.writeObject(stateObj);
                oos.close();
                fos.close();
            }

            if (MoSTState.class.isAssignableFrom(stateObj.getClass())) {
                return stateObj;
            } else {
                logger.error("Loaded object is not an instance of MoSTState");
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Error occurred during file operation", e);
            return null;
        } finally {
            fileLock.unlock();
        }
    }

    // Upload file to server is not implemented in this context, 
    // as it's dependent on a specific JavaScript library or framework, 
    // which isn't specified in the task description.
}
```

