```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>

typedef struct Notification {
    char* sid;
    int type;
    char* payload; // For simplicity, payload is a string. In reality it might be binary data or structured data.
} Notification;

Notification* createNotification(char* sid, int type, char* payload) {
    Notification* notification = malloc(sizeof(Notification));
    if (notification == NULL) return NULL;

    notification->sid = strdup(sid);
    notification->type = type;
    notification->payload = strdup(payload);

    return notification;
}

void destroyNotification(Notification* notification) {
    free(notification->sid);
    free(notification->payload);
    free(notification);
}

typedef struct Node {
    Notification* notification;
    struct Node* next;
} Node;

Node* createNode(Notification* notification) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->notification = notification;
    node->next = NULL;

    return node;
}

void destroyNode(Node* node) {
    destroyNotification(node->notification);
    free(node);
}

typedef struct Queue {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
} Queue;

Queue* createQueue() {
    Queue* queue = malloc(sizeof(Queue));
    if (queue == NULL) return NULL;

    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->size = 0;

    return queue;
}

void destroyQueue(Queue* queue) {
    Node* node = queue->head;
    while (node != NULL) {
        Node* next = node->next;
        destroyNode(node);
        node = next;
    }

    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

void enqueue(Queue* queue, Notification* notification) {
    Node* node = createNode(notification);
    if (node == NULL) return; // Handle error.

    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        queue->head = node;
        queue->tail = node;
    } else {
        queue->tail->next = node;
        queue->tail = node;
    }
    ++queue->size;
    pthread_mutex_unlock(&queue->lock);
}

Notification* dequeue(Queue* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return NULL; // Handle error.
    }

    Node* node = queue->head;
    queue->head = node->next;
    --queue->size;
    if (queue->size == 0) {
        queue->tail = NULL;
    }
    pthread_mutex_unlock(&queue->lock);

    Notification* notification = node->notification;
    destroyNode(node);

    return notification;
}

char* md5HashOfString(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), digest);    

    char *mdString = malloc(33);
    for(int i = 0; i < 16; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    return mdString;
}
```

This code is just a starting point. It doesn't cover all the requirements and you would need to expand it further based on your specific needs. For example, for concurrent operations or large queues it might be worth using lock-free data structures instead of mutexes which can cause high contention. Also, real logging framework should be implemented, performance metrics and configuration management could be added, etc.
']

