void push_back(CRC_pool_t* pool, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    // Lock to ensure thread safety
    pthread_spin_lock(&(pool->lock));

    // Add new entry at the head of the list (stack)
    NFAPI_CRC_INDICATION_PDU_T* old_head = pool->head;
    new_entry->next = old_head;
    while (!atomic_compare_exchange_strong(&(pool->head), &old_head, new_entry)) {}

    pthread_spin_unlock(&(pool->lock));
}
