import redis.clients.jedis.Jedis;

public class MessageProcessor {
    private Jedis jedis = new Jedis("localhost");

    public String process(String message) throws NoSuchAlgorithmException {
        String cachedHash = jedis.get(message); // Check if the hash is already in cache

        if (cachedHash != null) {
            return cachedHash;
        } else {
            MessageDigest md = MessageDigest.getInstance("MD5");

            byte[] hashInBytes = md.digest(message.getBytes(StandardCharsets.UTF_8));

            String hexString = bytesToHex(hashInBytes); // Convert the resulting bytes to hex string

            jedis.set(message, hexString); // Add the hash to cache

            return hexString;
        }
    }

