['Here is a basic implementation of your requirements using C language:

```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int SenderID;
    long Timestamp;
    char* payload;
} Message;

Message** messages = NULL;
int message_count = 0;
const int MAX_MESSAGES = 10000;
pthread_mutex_t lock;

void serialize(Message *message, unsigned char **output) {
    // Serialize the SenderID and Timestamp into output. Assuming that 4 bytes are enough for SenderID and 8 bytes are enough for Timestamp
    memcpy(*output, &message->SenderID, sizeof(int));
    *output += sizeof(int);
    memcpy(*output, &message->Timestamp, sizeof(long));
    *output += sizeof(long);

    // Serialize the length of payload and then the payload itself
    size_t payloadLength = strlen(message->payload) + 1;  // +1 to include null terminator
    memcpy(*output, &payloadLength, sizeof(size_t));
    *output += sizeof(size_t);
    memcpy(*output, message->payload, payloadLength);
}

Message* deserialize(unsigned char **input) {
    Message *message = (Message*) malloc(sizeof(Message));

    // Deserialize SenderID and Timestamp
    memcpy(&message->SenderID, *input, sizeof(int));
    *input += sizeof(int);
    memcpy(&message->Timestamp, *input, sizeof(long));
    *input += sizeof(long);

    // Deserialize payload length and then the payload itself
    size_t payloadLength;
    memcpy(&payloadLength, *input, sizeof(size_t));
    *input += sizeof(size_t);
    message->payload = (char*) malloc(payloadLength);
    memcpy(message->payload, *input, payloadLength);

    return message;
}

void addMessage(int SenderID, long Timestamp, char* payload) {
    pthread_mutex_lock(&lock);

    if (message_count < MAX_MESSAGES) {
        Message *newMessage = (Message*) malloc(sizeof(Message));
        newMessage->SenderID = SenderID;
        newMessage->Timestamp = Timestamp;
        newMessage->payload = strdup(payload);  // Create a copy of the payload

        messages[message_count++] = newMessage;
    }

    pthread_mutex_unlock(&lock);
}
```
This implementation does not include monitoring or memory usage tracking, as those would require additional libraries and could be quite complex to implement efficiently. Also note that this code assumes a specific serialization format (SenderID, Timestamp and payload in sequence). If you want to use another format, please adjust the `serialize` and `deserialize` functions accordingly.
