typedef struct {
    int LogID;
    int LogLevel;
    time_t Timestamp;
    char* Message;
} LogEntry;

LogEntry* createLogEntry(int id, int level, const char* msg) {
    // Verify input values and allocate memory
    if (id <= 0 || level <= 0 || msg == NULL || strlen(msg) == 0) return NULL;

    LogEntry* entry = malloc(sizeof(LogEntry));
    if (entry == NULL) return NULL;

    // Initialize struct members
    entry->LogID = id;
    entry->LogLevel = level;
    time(&entry->Timestamp);

    // Copy message into dynamically allocated memory
    entry->Message = malloc(strlen(msg) + 1);
    if (entry->Message == NULL) {
        free(entry);
        return NULL;
    }
    strcpy(entry->Message, msg);

    return entry;
}

// Define global variables and mutex for thread safety
#define MAX_ENTRIES 5000
LogEntry* logArray[MAX_ENTRIES];
size_t arrayIndex = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a LogEntry safely with thread-safety
void addLogEntry(int id, int level, const char* msg) {
    // Lock mutex for safe access
    pthread_mutex_lock(&lock);

    if (arrayIndex < MAX_ENTRIES) {
        LogEntry* entry = createLogEntry(id, level, msg);
        if (entry != NULL) {
            logArray[arrayIndex++] = entry;
        }
    } else {
        printf("Maximum entries limit reached\n");
    }

    // Unlock mutex after access
    pthread_mutex_unlock(&lock);
}
