int frameCount = 0;

void addElement(LTEPHY_RX_PDU_T data) {
    pthread_mutex_lock(&mutex);
    ++frameCount;
    Node* node = malloc(sizeof(Node));
    memcpy(&node->data, &data, sizeof(LTEPHY_RX_PDU_T));
    node->next = head;
    head = node;
    pthread_mutex_unlock(&mutex);
}

void iterateList() {
    pthread_mutex_lock(&mutex);
    for (Node* current = head; current != NULL; current = current->next) {
        // Perform operation on the data here
    }
    pthread_mutex_unlock(&mutex);
}

LTEPHY_RX_PDU_T getElement(int index) {
    LTEPHY_RX_PDU_T result;
    memset(&result, 0, sizeof(LTEPHY_RX_PDU_T));

    pthread_mutex_lock(&mutex);
    if (index < frameCount) {
        Node* current = head;
        for (int i = 0; i < index && current != NULL; ++i, current = current->next);

        if (current != NULL) {
            memcpy(&result, &(current->data), sizeof(LTEPHY_RX_PDU_T));
        }
