#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>

typedef struct ResourceUsage {
    int ProcessID;
    int ResourceType;
    int UsageValue;
    time_t Timestamp;
    char* ResourceName; // variable-length string
} ResourceUsage;

// A lock-free queue for resource usage records
atomic_int producerIndex = ATOMIC_VAR_INIT(0);
ResourceUsage** buffer;
const int BUFFER_SIZE = 1e6;

void produce(ResourceUsage* record) {
    // Verify integrity of the record before adding it to the queue.
    if (verifyChecksum(record)) {
        while (!atomic_compare_exchange_weak(&producerIndex, &index, (index + 1) % BUFFER_SIZE));
        buffer[index] = record;
    } else {
        // Handle invalid record.
    }
}

// A lock-free stack for processing records
atomic_int consumerIndex = ATOMIC_VAR_INIT(0);

ResourceUsage* consume() {
    int index = atomic_load(&consumerIndex);
    ResourceUsage* record = buffer[index];
    while (!atomic_compare_exchange_weak(&consumerIndex, &index, (index + 1) % BUFFER_SIZE));
    return record;
}
```
