    char *guti;
    char *ipAddr;
    PdpContext **pdpList;
    int pdpCount;
    struct UeRecord* next;
} UeRecord;

UeRecord *head = NULL; // Head of the linked list

// Function to add a UE record
void add_ue(char *guti, char *ipAddr) {
    UeRecord *newNode = (UeRecord*) malloc(sizeof(UeRecord));
    newNode->guti = strdup(guti);
    newNode->ipAddr = strdup(ipAddr);
    newNode->pdpList = NULL;
    newNode->pdpCount = 0;
    newNode->next = head; // Insert at the beginning of the list
    head = newNode;
}

// Function to remove a UE record
void remove_ue(char *guti) {
    UeRecord **tracer = &head;
    while(*tracer){
        if(strcmp((*tracer)->guti, guti) == 0){
            UeRecord *tempNode = *tracer;
            *tracer = (*tracer)->next;
            free(tempNode->guti);
            free(tempNode->ipAddr);
            // TODO: Free pdpList if needed.
            free(tempNode);
            break;
        } else {
            tracer = &((*tracer)->next);
        }
    }
}

// Function to add a PDP context to a UE record
void add_pdp(char *guti, int sessionID, char *data) {
    UeRecord *currentNode = head;
    while (currentNode != NULL){
        if (strcmp(currentNode->guti, guti) == 0){
            PdpContext **newPdpList = realloc(currentNode->pdpList, sizeof(PdpContext*) * (currentNode->pdpCount + 1));
            if (newPdpList){
                currentNode->pdpList = newPdpList;
                PdpContext *newPdp = malloc(sizeof(PdpContext));
                newPdp->sessionID = sessionID;
                newPdp->data = strdup(data);
                currentNode->pdpList[currentNode->pdpCount] = newPdp;
                (currentNode->pdpCount)++;
            } else {
                printf("Error: Unable to add PDP context.\n");
            }
            return;
        }
        currentNode = currentNode->next;
    }
}
