['This task involves complex functionalities that may be implemented in different ways depending on specific use cases or systems. Below is a simple implementation using C programming language without any external libraries for educational purposes only. The data structure used here is a hash table with locking mechanism for efficient synchronization and thread-safety. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming IP addresses and GUTI are represented as unsigned int
typedef unsigned int IP_Address;
typedef unsigned int GUTI;
typedef unsigned int PDPContext; 

struct Node {
    struct Node* next;
    PDPContext data;
};

typedef struct {
    pthread_mutex_t lock;
    struct Node* contexts;
} UEContext;

// Global hash table of UEContexts, indexed by GUTI.
#define MAX_UE 1024
static UEContext g_uecontext[MAX_UE];

void init() {
    for (int i = 0; i < MAX_UE; ++i)
        pthread_mutex_init(&g_uecontext[i].lock, NULL);
}

// Adds a new PDP context to the UE.
// If an existing PDP context with this session ID exists, it is replaced.
int addPdpContext(GUTI guti, PDPContext pdp) {
    pthread_mutex_lock(&g_uecontext[guti].lock);

    // Check if the PDP context already exists, remove if found.
    struct Node* node = g_uecontext[guti].contexts;
    while (node) {
        if (node->data == pdp) {
            node->data = pdp;
            break;
        }
        node = node->next;
    }

    // Add new node.
    if (!node) {
        struct Node* newNode = malloc(sizeof(struct Node));
        newNode->data = pdp;
        newNode->next = g_uecontext[guti].contexts;
        g_uecontext[guti].contexts = newNode;
    }

    pthread_mutex_unlock(&g_uecontext[guti].lock);
    return 0;
}

// Removes a PDP context from the UE.
int removePdpContext(GUTI guti, PDPContext pdp) {
    pthread_mutex_lock(&g_uecontext[guti].lock);

    struct Node* node = g_uecontext[guti].contexts;
    struct Node* prev = NULL;
    while (node) {
        if (node->data == pdp) {
            if (prev) {
                prev->next = node->next;
            } else {
                g_uecontext[guti].contexts = node->next;
            }

            free(node);
            break;
        }

        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&g_uecontext[guti].lock);
    return 0;
}
```

This is a basic implementation. In a real world scenario, the UE context would have more properties and it might be better to use a database system such as SQLite or PostgreSQL that can handle complex queries and manage data consistency efficiently. Furthermore, you could use existing network management tools like srsLTE to interact with your system instead of implementing everything from scratch.
']

