using System.Threading;

public class DynamicValueManager
{
    private float minValue = float.MinValue;
    private float maxValue = float.MaxValue;

    private int generatedValuesCount = 0;
    private double totalSumOfGeneratedValues = 0.0d;

    private object lockObj = new object();

    public float GetRandomFloat()
    {
        Random random = new Random(Guid.NewGuid().GetHashCode());

        return (float)(random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GetRandomInt()
    {
        Random random = new Random(Guid.NewGuid().GetHashCode());

        return (int)(minValue + (maxValue - minValue + 1) * random.NextDouble());
    }

    public void AdjustRange(float newMin, float newMax)
    {
        if (!(newMin <= newMax)) throw new ArgumentException("Invalid range: min must be less than or equal to max.");

        lock (lockObj)
        {
            // Ensure the new range crosses the existing range boundary. 
            this.minValue = newMin;
            this.maxValue = newMax;

            if (this.generatedValuesCount > 0)
                this.totalSumOfGeneratedValues = 0;
        }
    }

    public float GetAdjustedValue(float value)
    {
        lock (lockObj)
        {
            while (value < minValue || value > maxValue)
            {
                if (value < minValue)
                    value += (maxValue - minValue);
                else if (value > maxValue)
                    value -= (maxValue - minValue);
            }

            return value;
        }
    }

    public override string ToString()
    {
