['```java
import java.util.*;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.concurrent.locks.*;

class UserInteraction {
    String sessionId;
    String interactionType;
    long timestamp;
}

public class InteractionAggregator {
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final Map<String, List<UserInteraction>> interactionsMap = new HashMap<>();

    public void add(UserInteraction interaction) {
        if (interaction == null || interaction.sessionId == null || interaction.timestamp <= 0L) {
            System.err.println("Invalid interaction: " + interaction);
            return;
        }

        lock.writeLock().lock();
        try {
            interactionsMap.computeIfAbsent(interaction.sessionId, k -> new ArrayList<>()).add(interaction);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void aggregate() {
        for (List<UserInteraction> sessionInteractions : interactionsMap.values()) {
            Collections.sort(sessionInteractions, Comparator.comparingLong(i -> i.timestamp));

            long totalDuration = 0L;
            int totalInteractions = sessionInteractions.size();

            for (int i = 1; i < totalInteractions; i++) {
                UserInteraction currentInteraction = sessionInteractions.get(i);
                UserInteraction previousInteraction = sessionInteractions.get(i - 1);

                long duration = currentInteraction.timestamp - previousInteraction.timestamp;
                totalDuration += duration;
            }

            System.out.println("Session: " + sessionInteractions.get(0).sessionId + 
                               ", Total Interactions: " + totalInteractions + 
                               ", Average Duration: " + (totalDuration / totalInteractions));
        }
    }

    public void exportToCSV(String filePath) {
        try (PrintWriter pw = new PrintWriter(new File(filePath))) {
            StringBuilder sb = new StringBuilder();
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

            for (List<UserInteraction> sessionInteractions : interactionsMap.values()) {
                for (UserInteraction interaction : sessionInteractions) {
                    sb.append(interaction.sessionId).append(",");
                    sb.append(interaction.interactionType).append(",");
                    sb.append(sdf.format(new Date(interaction.timestamp)));
                    sb.append("\n");
                }
            }

            pw.write(sb.toString());
        } catch (FileNotFoundException e) {
            System.err.println("Failed to write CSV file: " + e);
        }
    }
}
```
This code creates a `UserInteraction` class representing an interaction in the system, and an `InteractionAggregator` which adds interactions (thread-safe), aggregates them by session ID, calculates metrics such as total interactions and average duration between interactions, exports aggregated data to a CSV file.
']

