['Here is a C# implementation for the task using thread-safe access by locking. For simplicity, only one seed is maintained but can be easily extended to multiple ranges if needed.

```csharp
using System;
using System.Text.Json;
using System.Threading;

public class RandomValueGenerator
{
    private int seed = 0;
    private ReaderWriterLockSlim locker = new ReaderWriterLockSlim();

    public void SetSeed(int seed)
    {
        this.seed = seed;
    }

    public double GenerateDouble(double min, double max)
    {
        if (min > max || (max - min) < Double.Epsilon) throw new ArgumentException("Invalid range");

        locker.EnterWriteLock();
        try
        {
            Random random = new Random(seed);
            double value = random.NextDouble() * (max - min) + min;
            return value;
        }
        finally
        {
            locker.ExitWriteLock();
        }
    }

    public int GenerateInteger(int min, int max)
    {
        if (min > max || (max - min) == 0) throw new ArgumentException("Invalid range");

        locker.EnterReadLock();
        try
        {
            Random random = new Random(seed);
            int value = random.Next(min, max + 1);
            return value;
        }
        finally
        {
            locker.ExitReadLock();
        }
    }

    public void ResetSeed()
    {
        locker.EnterWriteLock();
        try
        {
            seed = 0;
        }
        finally
        {
            locker.ExitWriteLock();
        }
    }

    public string SerializeState()
    {
        return JsonSerializer.Serialize(this);
    }

    public static RandomValueGenerator DeserializeState(string json)
    {
        return JsonSerializer.Deserialize<RandomValueGenerator>(json);
    }

    public override string ToString()
    {
        locker.EnterReadLock();
        try
        {
            return $"Seed: {seed}";
        }
        finally
        {
            locker.ExitReadLock();
        }
    }
}
```
The above code uses `ReaderWriterLockSlim` for thread-safe access to the shared `RandomValueGenerator` instance. It serializes and deserializes the current object's state by using `System.Text.Json` namespace. The `ToString()` method provides a readable string representation of the seed value.
']

