void logAccess(char* path, int success, time_t startTime);

// timeout mechanism handling function
int readWithTimeout(int fd, void *buf, size_t nbytes, time_t startTime) {
    while (time(NULL) - startTime < TIMEOUT_SECONDS) {
        int bytesRead = read(fd, buf, nbytes);
        if (bytesRead > 0 || errno != EAGAIN && errno != EWOULDBLOCK)
            return bytesRead;
    }
    // timeout occurred, handle accordingly
}

// thread-safe function to serve file descriptors
int getFileDescriptor(char* path) {
    FileDescriptorCacheEntry* cacheEntry = getCachedFd(path);
    if (cacheEntry != NULL) {  // found in cache
        return cacheEntry->fd;
    } else {  // not in cache, open and add to cache
        int fd = open(path, O_RDONLY);
        if (fd == -1) {
            logAccess(path, 0, time(NULL));
            return -1;
        }
        updateCacheEntry(path);
        return fd;
    }
}
```
