                          10000, EVP_aes_256_cbc(), EVP_MAX_KEY_LENGTH, ctx->key)) {
        return NULL;
    }

    /* Initializing the cipher context */
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        return NULL;
    }

    return ctx;
}

void aes256_cleanup(AES256Context *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}
