#include <pthread.h>
#include <stdlib.h>

typedef struct HTTP2Frame {
    int streamID;
    int flags;
    int length;
    char* payload;
    struct HTTP2Frame* next;
} HTTP2Frame;

HTTP2Frame *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addFrame(int streamID, int flags, int length, char* payload) {
    pthread_mutex_lock(&lock);

    HTTP2Frame *newFrame = malloc(sizeof(HTTP2Frame));
    newFrame->streamID = streamID;
    newFrame->flags = flags;
    newFrame->length = length;
    newFrame->payload = payload;
    newFrame->next = NULL;

    if (head == NULL || head->streamID > streamID) {
        newFrame->next = head;
        head = newFrame;
    } else {
        HTTP2Frame *current = head;
        while (current->next != NULL && current->next->streamID < streamID) {
            current = current->next;
        }
        newFrame->next = current->next;
        current->next = newFrame;
    }

    pthread_mutex_unlock(&lock);
}

void removeFrame(int streamID) {
    pthread_mutex_lock(&lock);

    if (head != NULL && head->streamID == streamID) {
        HTTP2Frame *temp = head;
        head = head->next;
        free(temp);
    } else {
        HTTP2Frame *current = head;
        while (current->next != NULL && current->next->streamID != streamID) {
            current = current->next;
        }

        if (current->next != NULL) {
            HTTP2Frame *temp = current->next;
            current->next = temp->next;
            free(temp);
        }
    }

    pthread_mutex_unlock(&lock);
}
```
