// Define the list data structure and its methods...
typedef struct {
    size_t size;
    size_t capacity;
    PHY_TASK_DESC_T *data;
    pthread_mutex_t lock;
} DynamicList;

void addElement(DynamicList *list, PHY_TASK_DESC_T element) {
    // Acquire the mutex before modifying the list...
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // If we're out of capacity, double it...
        list->data = realloc(list->data, sizeof(*list->data) * list->capacity * 2);
        list->capacity *= 2;
    }

    // Add the new element and increment the size...
    list->data[list->size++] = element;

    // Release the mutex...
    pthread_mutex_unlock(&list->lock);
}

// Iterate over the elements in the list...
void iterate(DynamicList *list, void (*func)(PHY_TASK_DESC_T*)) {
    for (size_t i = 0; i < list->size; ++i) {
        func(&list->data[i]);
    }
}

// Retrieve an element by index...
PHY_TASK_DESC_T getElement(DynamicList *list, size_t index) {
    if (index < list->size) {
        return list->data[index];
