static char buffer[MAX_BUFFER_SIZE];
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void logMessage(const char *file, int line, const char *func, const char *level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&lock);
    time_t timestamp = time(NULL);
    int len = snprintf(buffer, MAX_BUFFER_SIZE, "[%ld] %s:%d:%s() [%s] ", 
                       timestamp, file, line, func, level);

    // Check if the buffer has enough space for the formatted string. If not, truncate it.
    if (len < MAX_BUFFER_SIZE) {
        vsnprintf(buffer + len, MAX_BUFFER_SIZE - len, format, args);
    } else {
        vsnprintf(NULL, 0, format, args); // Discard the string to get its length
    }

    LogMessage* message = malloc(sizeof(LogMessage));
    if (message == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    message->timestamp = timestamp;
    message->message = strdup(buffer); // Copy the buffer to ensure it is not overwritten before being sent

    sendToExternalService(message);
    pthread_mutex_unlock(&lock);

    va_end(args);
}
