def secure_generate_token(api_url):
    retry = 0
    while True:
        try:
            response = requests.get(api_url)
            response.raise_for_status()  # Raise exception if status is not 2xx
        except (requests.HTTPError, requests.RequestException) as err:
            if retry < 3:
                sleep((2 ** retry))
                retry += 1
                logging.warning('Retrying...')
                continue
