['Here is a simple implementation using C99. The actual implementation may be more complex depending on specific requirements like HTTP/2 frame structure, handling of memory usage limitation, etc. Note that this code does not include all the features mentioned in your request due to space constraints and complexity, but it provides a starting point.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Frame {
    int stream_id;
    // Other frame data...
    struct Frame* next;
} Frame;

typedef struct LinkedList {
    pthread_mutex_t lock;
    Frame* head;
} LinkedList;

// Initialize a linked list.
void init(LinkedList* list) {
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
}

// Add a frame.
void addFrame(LinkedList* list, Frame* newFrame) {
    pthread_mutex_lock(&list->lock);
    newFrame->next = list->head;
    list->head = newFrame;
    pthread_mutex_unlock(&list->lock);
}

// Remove a frame.
void removeFrame(LinkedList* list, int streamId) {
    pthread_mutex_lock(&list->lock);
    Frame** linkPtr = &list->head;
    while (*linkPtr != NULL) {
        if ((*linkPtr)->stream_id == streamId) {
            Frame* nextFrame = (*linkPtr)->next;
            free(*linkPtr);
            *linkPtr = nextFrame;
            break;
        } else {
            linkPtr = &(*linkPtr)->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Query a frame.
Frame* queryFrame(LinkedList* list, int streamId) {
    pthread_mutex_lock(&list->lock);
    Frame* current = list->head;
    while (current != NULL) {
        if (current->stream_id == streamId) {
            break;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}
```

This code creates a simple linked list of frames with locking to ensure thread safety. Each frame contains an integer stream ID and a pointer to the next frame in the list, forming a singly-linked list structure. When adding or removing a frame, it takes the lock to protect against concurrent modifications by other threads.
