EVP_CIPHER_CTX *threaded_aes_file_processor(const char* input, const char* output, const char* password, const char* salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Check if the cipher context was successfully created.
    if (ctx == NULL) {
        printf("Error creating the cipher context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Initialize IV and derive key using PBKDF2
    unsigned char iv[16];
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        printf("Failed to generate secure random bytes for initialization vector\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (!PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), (unsigned char*)salt, strlen(salt), 10000, EVP_CIPHER_key_length(EVP_aes_256_cbc()), key)) {
        printf("Failed to derive encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher with AES-256-CBC mode and our key/iv.
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1 || EVP_CIPHER_CTX_set_padding(ctx, 0) != 1) {
        printf("Error initializing the cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Open input file and output file for reading/writing.
    FILE *in = fopen(input, "rb");
    if (in == NULL) {
        printf("Failed to open input file: %s\n", strerror(errno));
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    FILE *out = fopen(output, "wb");
    if (out == NULL) {
        printf("Failed to open output file: %s\n", strerror(errno));
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Process each task here. For simplicity, we'll just encrypt the entire input file.
    unsigned char buffer[4096];
    int bytesRead = 0;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        if (EVP_EncryptUpdate(ctx, buffer, &bytesRead, buffer, bytesRead) != 1) {
            printf("Error encrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }

        fwrite(buffer, 1, bytesRead, out);
    }

    // Finalize the encryption process.
    if (EVP_EncryptFinal_ex(ctx, buffer, &bytesRead) != 1) {
        printf("Error finalizing encryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    fwrite(buffer, 1, bytesRead, out);

    // Clean up and close files.
    EVP_CIPHER_CTX_cleanup(ctx);
    fclose(in);
    fclose(out);

    return ctx;
}
```
