["Here is an example of how this could be accomplished in C using pthreads and a linked list for the task queue. However, keep in mind that it's just a basic demonstration. Actual production code would require extensive testing, exception handling, optimization, and customization to match your specific requirements:

```c
#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdio.h>
#include <time.h>

// Define a struct for tasks and a linked list node
typedef struct task {
    void (*routine)(void*); // Function pointer to routine
    void *arg;             // Argument to pass to routine
    struct task *next;     // Pointer to next task in queue
} Task;

// Define thread pool data structure
typedef struct {
    pthread_t *threads;        // Array of threads in the pool
    int num_threads;          // Number of threads
    Task *queue;              // Queue for tasks
    pthread_mutex_t queueLock;// Mutex to control access to task queue
    pthread_cond_t  condvar; // Condition variable used to notify workers when a new task is added or pool is being shut down
    int shutdown;            // Flag indicating if the pool is currently shutting down
} ThreadPool;

// Function executed by each worker thread
void *worker(void *arg) {
    ThreadPool *pool = (ThreadPool *) arg;
    Task *task;

    while (1) {
        pthread_mutex_lock(&(pool->queueLock));

        // Wait until there is work to do or pool is shutting down
        while (!pool->shutdown && pool->queue == NULL) 
            pthread_cond_wait(&(pool->condvar), &(pool->queueLock));

        if (pool->shutdown) {
            pthread_mutex_unlock(&(pool->queueLock));
            pthread_exit(NULL);
        }

        // Get next task from queue and run it
        task = pool->queue;
        pool->queue = task->next;
        pthread_mutex_unlock(&(pool->queueLock));

        task->routine(task->arg);
        free(task);
    }
}

// Initialize thread pool
ThreadPool *initThreadPool(int num_threads) {
    ThreadPool *pool;
    int i;

    if (num_threads <= 0) return NULL;

    pool = calloc(1, sizeof(*pool));

    // Create threads and start them
    pool->threads = calloc(num_threads, sizeof(*(pool->threads)));
    for (i = 0; i < num_threads; ++i) {
        if (pthread_create(&(pool->threads[i]), NULL, worker, pool)) 
            goto err;
    }

    // Initialize mutex and condition variable
    pthread_mutex_init(&(pool->queueLock), NULL);
    pthread_cond_init(&(pool->condvar), NULL);

    return pool;

err:
    // Cleanup on error
    for (--i; i >= 0; --i) 
        pthread_join(pool->threads[i], NULL);
    free(pool->threads);
    pthread_mutex_destroy(&(pool->queueLock));
    pthread_cond_destroy(&(pool->condvar));
    free(pool);
    return NULL;
}

// Submit a task to the thread pool
void submitTask(ThreadPool *pool, void (*routine)(void*), void *arg) {
    Task *task = malloc(sizeof(*task));

    // Initialize task and add it to queue
    if (task != NULL) {
        task->routine = routine;
        task->arg = arg;
        pthread_mutex_lock(&(pool->queueLock));
        task->next = pool->queue;
        pool->queue = task;
        pthread_cond_signal(&(pool->condvar));
        pthread_mutex_unlock(&(pool->queueLock));
    }
}

// Shutdown thread pool gracefully (waits for all tasks to finish)
void shutdownThreadPool(ThreadPool *pool) {
    Task *task;

    // Signal threads and wait until they are done
    pthread_mutex_lock(&(pool->queueLock));
    pool->shutdown = 1;
    pthread_cond_broadcast(&(pool->condvar));
    pthread_mutex_unlock(&(pool->queueLock));

    for (int i = 0; i < pool->num_threads; ++i) 
        pthread_join(pool->threads[i], NULL);

    // Cleanup remaining tasks in queue
    while ((task = pool->queue)) {
        pool->queue = task->next;
        free(task);
    }
}
```
To create a thread pool with 4 threads, you can use: `ThreadPool *pool = initThreadPool(4);`. To submit a new task, call `submitTask(pool, myRoutine, myArg);` where `myRoutine` is the function to run and `myArg` is its argument. When done with the pool, call `shutdownThreadPool(pool);`.
"]

