class ArrayManager {
private:
    boost::bloom_filter<std::string> bloomFilter;
    std::unordered_map<unsigned int, NFAPI_CRC_INDICATION_PDU_T> arrayMap;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> arrayVector;
    std::ofstream logFile;

public:
    ArrayManager() {
        logFile.open("logfile.txt", std::ios::app); // open the file in append mode
    }

    ~ArrayManager() {
        if (logFile.is_open()) {
            logFile.close();
        }
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& element) {
        if (!bloomFilter[std::to_string(element.RNTI)]) { // RNTI is not in bloom filter
            arrayMap[element.RNTI] = element;
            arrayVector.push_back(element);
            bloomFilter.insert(std::to_string(element.RNTI));

            logFile << "Added: " << element.RNTI << std::endl;
        } else {
            // handle duplicate RNTI
            std::cout << "Duplicate RNTI detected: " << element.RNTI << std::endl;
        }
    }

    void remove(unsigned int rnti) {
        auto it = arrayMap.find(rnti);
        if (it != arrayMap.end()) {
            // remove from map and vector
            arrayVector.erase(std::remove_if(arrayVector.begin(), arrayVector.end(), 
                [&](const NFAPI_CRC_INDICATION_PDU_T& e) { return e.RNTI == rnti; }), arrayVector.end());
            arrayMap.erase(it);

            // remove from bloom filter
            bloomFilter.remove(std::to_string(rnti));

            logFile << "Removed: " << rnti << std::endl;
        } else {
            std::cout << "RNTI not found in array." << std::endl;
        }
    }

    // Implement other methods as needed...
};
```
