```python
import threading
from collections import deque
from datetime import datetime

class OctreeNode:
    def __init__(self):
        self.data = None
        self.children = {}

    def insert(self, key_path, data):
        if len(key_path) == 0:
            self.data = data
        else:
            first, rest = key_path[0], key_path[1:]
            if first not in self.children:
                self.children[first] = OctreeNode()
            self.children[first].insert(rest, data)

    def search(self, key_path):
        if len(key_path) == 0:
            return self.data
        else:
            first, rest = key_path[0], key_path[1:]
            if first not in self.children:
                return None
            return self.children[first].search(rest)

class Octree:
    def __init__(self):
        self.root = OctreeNode()
        self.lock = threading.Lock()

    def insert(self, key_path, data):
        with self.lock:
            self.root.insert(key_path, data)

    def search(self, key_path):
        return self.root.search(key_path)

def octreeInit(ticker, timestamp, price, volume):
    # Validate incoming data
    if not isinstance(ticker, str) or not isinstance(timestamp, datetime) or not isinstance(price, (int, float)) or not isinstance(volume, int):
        raise ValueError("Invalid input type")

    # Initialize octree
    octree = Octree()

    # Process data
    key_path = [ticker, timestamp.strftime("%Y-%m-%d %H:%M:%S"), price]
    data = volume

    # Insert into octree
    octree.insert(key_path, data)
```
