#include <semaphore.h>

typedef struct LTE_PHY_RX_SRB1_PDU_T {
    uint64_t timestamp;
    float SNR;
    int errorCode;
    double latency;
} LTE_PHY_RX_SRB1_PDU_T;

typedef struct Node {
    LTE_PHY_RX_SRB1_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;
Node *head = NULL;
int size = 0;
const int MAX_SIZE = 15000, MIN_SIZE = 5000;

void add(LTE_PHY_RX_SRB1_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));

    if(newNode == NULL) {
        //Handle memory allocation failure
        return;
    }

    sem_wait(&semaphore);
    pthread_mutex_lock(&lock);

    newNode->data = data;
    newNode->next = head;
    head = newNode;
    size++;

    if(size > MAX_SIZE) {
        Node* temp = head;

        for(int i = 0; i < MIN_SIZE - 1; i++) {
            temp = temp->next;
        }

        free(temp->next);
        temp->next = NULL;
        size = MIN_SIZE;
    }

    pthread_mutex_unlock(&lock);
    sem_post(&semaphore);
