from django import forms
from .models import Task

class TaskForm(forms.ModelForm):
    class Meta:
        model = Task
        fields = ['title', 'description', 'due_date', 'priority', 'status']

def manage_task(request, task_id=None):  # If no ID is given a new task will be created
    if request.method == 'POST':
        form = TaskForm(request.POST)
        if form.is_valid():
            task = form.save()
            return JsonResponse({'success': True, 'task_id': task.id})
        else:
            return JsonResponse({'success': False, 'errors': form.errors}, status=400)
    elif request.method == 'PUT':  # Update existing task
        try:
            task = Task.objects.get(id=task_id)
        except Task.DoesNotExist:
            return JsonResponse({'success': False, 'errors': {'Task not found.'}}, status=404)
        form = TaskForm(request.PUT, instance=task)
        if form.is_valid():
            task = form.save()
            return JsonResponse({'success': True, 'task_id': task.id})
        else:
            return JsonResponse({'success': False, 'errors': form.errors}, status=400)
    elif request.method == 'DELETE':  # Delete a task
        try:
            Task.objects.get(id=task_id).delete()
        except Task.DoesNotExist:
            return JsonResponse({'success': False, 'errors': {'Task not found.'}}, status=404)
        return JsonResponse({'success': True})
```

