    let value = myCache.get(url);
    if (value === undefined) {
        try {
            const response = await fetchWithRetry(url); // Fetch with retry mechanism
            myCache.set(url, response); // Cache the result
            return response;
        } catch (error) {
            console.log('Error fetching data: ', error); 
        }
    } else {
        console.log('Served from cache');
        return value;
    }
};

// Function with retry mechanism for failed requests
const fetchWithRetry = async (url, retries = 5) => {
    try {
        const response = await getData(url); 
        return response;
    } catch (error) {
        if (retries === 1) throw error; // If no more retries are available, throw the error
        console.log('Retrying after', Math.pow(2, 5 - retries) * 1000, 'ms');
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, 5 - retries) * 1000)); // Exponential backoff delay
        return fetchWithRetry(url, retries - 1); // Retry after delay
    }
};

// Function to get data using OAuth access token and handle pagination.
const getData = async (url) => {
    let response;
    try {
       if (!accessToken) {
           accessToken = await oauth2.getOAuthAccessToken('', {'grant_type': 'client_credentials'}); // Get new token if not available
       }
       response = await fetch(url, { headers: { Authorization: `Bearer ${accessToken}` }});
    } catch (error) {
        accessToken = ''; // If the token is expired or invalidated, reset it
        throw error; // Rethrow the error to be caught by retry mechanism
    }

    if (response.status === 401) {
       accessToken = ''; // If unauthorized response received, reset access token
    } 

    return response.json(); // Return JSON response
};
```
In the above code snippet, `getDataSafely` function is used to fetch data from URLs efficiently by implementing caching and retries with exponential backoff for handling failed requests. The OAuth token is stored in a session-like variable within the context of this function to facilitate seamless user authentication.
