```rust
use std::time::Duration;
use diesel::{r2d2::{self, ConnectionManager}, pg::PgConnection};
use tokio::sync::RwLock;
use tracing::info;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct DatabaseConfig {
    pub database_url: String,
    pub max_connections: u32,
    pub idle_timeout: Duration,
    pub max_lifetime: Option<Duration>,
}

impl Default for DatabaseConfig {
    fn default() -> Self {
        Self {
            database_url: String::from("postgres://username:password@localhost/database"),
            max_connections: 10,
            idle_timeout: Duration::from_secs(60),
            max_lifetime: None,
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = DatabaseConfig::default();
    let manager = ConnectionManager::<PgConnection>::new(config.database_url);
    let pool: r2d2::Pool<ConnectionManager<PgConnection>> = 
        r2d2::Builder::with_manager(manager)
        .max_size(config.max_connections as usize)
        .idle_timeout(config.idle_timeout)
        .max_lifetime(config.max_lifetime.unwrap_or(Duration::from_secs(60)))
        .build()?;
    let pool = RwLock::new(pool);

    // Example of a query execution and logging
    let conn = pool.read().await?;
    info_span::debug(|| "executing database query")?;
    diesel::pg::PgConnection::execute(&*conn, "SELECT 1", &[])?;

    Ok(())
}
```
This code initializes a connection pool for a PostgreSQL database. You can adjust it according to your specific requirements and the details of your database system. It uses the Diesel ORM to execute SQL queries. Note that error handling is kept simple in this example, you would probably want to include more detailed logging or retries depending on your application needs.
