    $lockResult = $db->query("SELECT * FROM users WHERE id = ? FOR UPDATE", [$id]); 

    // Update the User Profile
    $statement = $db->prepare("UPDATE users SET contactDetails = :contact, lastLoginTimestamp = :lastLogin, userAgentString = :userAgent, subscriptionStatus = :subscriptionStatus, paymentInfo = :paymentInfo, preferences = :preferences WHERE id = ?");

    // Execute Statement
