// Define log entry structure
typedef struct {
    time_t timestamp;
    char level[20]; // debug, info, warning or error
    char source[50];
    char message[1000];
    void* metadata;  // Custom data that can vary in size and structure
} LogEntry;

// Define severity levels struct
typedef struct {
    char name[20];   // Severity level's name
    int maxEntries;  // Maximum number of log entries for this level
    int count;       // Current number of log entries
    pthread_mutex_t lock;
} SeverityLevel;

// Global variables for metrics and configuration
int totalLogs = 0;
SeverityLevel severityLevels[20] = {0};  // Array to hold severity levels
time_t windowSizeSec = 10;                // Sliding window size in seconds
pthread_mutex_t metricLock = PTHREAD_MUTEX_INITIALIZER;
int maxMessageLength = 0;                  // Maximum message length encountered
char sourceLongestMsg[50] = {0};            // Source associated with the longest message
double avgMsgLength = 0.0;                 // Average message length of filtered logs
time_t timeLimitSec = 30;                  // Log's age limit in seconds
pthread_mutex_t configLock = PTHREAD_MUTEX_INITIALIZER;
char metadataValidationRules[100] = {0};   // Predefined validation rules for custom metadata

// Function prototype
int processLog(LogEntry* log);
SeverityLevel* getSeverityLevel(const char* levelName);
void updateMetrics(LogEntry* log, int isFiltered);
void writeToStorageSystem(LogEntry* log);
int validateMetadata(void* metadata);

// Main function to process log entries
int processLog(LogEntry* log) {
    time_t currentTime = time(NULL);

    // Check if log's age is less than 30 seconds
    if (difftime(currentTime, log->timestamp) > timeLimitSec) {
        return 0;   // Log entry does not meet criteria
    }

    SeverityLevel* level = getSeverityLevel(log->level);
    pthread_mutex_lock(&level->lock);

    // Check if log's message length is greater than 10 characters and metadata is valid
    if (strlen(log->message) <= 10 || !validateMetadata(log->metadata)) {
        return 0;   // Log entry does not meet criteria
    }

    updateMetrics(log, 1);  // Update metrics with filtered log entry
    writeToStorageSystem(log);  // Write to persistent storage system

    pthread_mutex_unlock(&level->lock);

    return 1;   // Log entry meets criteria
}

// Function to update metrics
void updateMetrics(LogEntry* log, int isFiltered) {
    pthread_mutex_lock(&metricLock);

    totalLogs++;
    if (isFiltered) {
        avgMsgLength = ((avgMsgLength * (totalLogs - 1)) + strlen(log->message)) / totalLogs;
        if (strlen(log->message) > maxMessageLength) {
            maxMessageLength = strlen(log->message);
            strcpy(sourceLongestMsg, log->source);
        }
    }

    pthread_mutex_unlock(&metricLock);
}
```

