['Below is a simplified implementation of the UDP socket manager in C using POSIX threads (pthreads). Please note that this is a basic skeleton to give you an idea about how such a function can be structured, further features like multicast or QoS adjustments need additional code and considerations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 1024

typedef struct {
    int id;
    char address[INET6_ADDRSTRLEN];
    in_port_t port;
} Session;

Session sessions[MAX_CONNECTIONS] = {{0}};
int sockets[MAX_CONNECTIONS] = {0};
pthread_mutex_t socketLocks[MAX_CONNECTIONS] = PTHREAD_MUTEX_INITIALIZER;

void error(const char *msg) { 
    perror(msg); 
    exit(1); 
} 

int createUdpSocket() {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) error("ERROR opening socket");
    return sockfd;
}

void* handlePacketReception(void* args) {
    Session* session = (Session*)args;
    int id = session->id;

    char buffer[BUFFER_SIZE];
    struct sockaddr_in servAddr, cliAddr;
    socklen_t len = sizeof(cliAddr);
    while (1) {
        bzero(buffer, BUFFER_SIZE);
        int n = recvfrom(sockets[id], buffer, BUFFER_SIZE, MSG_WAITALL, (struct sockaddr*)&cliAddr, &len);
        if (n < 0) error("ERROR reading from socket");

        // process data here...
    }
    return NULL;
}

int initializeUdpSocket(Session* session) {
    struct sockaddr_in servAddr;

    int id = session->id;
    if (sockets[id] == 0) {
        pthread_mutex_lock(&socketLocks[id]);
        // double check after locking
        if (sockets[id] != 0) return sockets[id];

        sockets[id] = createUdpSocket();

        bzero((char*)&servAddr, sizeof(servAddr));
        servAddr.sin_family = AF_INET;
        servAddr.sin_port = htons(session->port);
        if (inet_aton(session->address, &servAddr.sin_addr) == 0) { 
            error("ERROR converting address");
        }

        bind(sockets[id], (struct sockaddr*)&servAddr, sizeof(servAddr));
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, handlePacketReception, session)) { 
        error("ERROR creating thread"); 
    }

    return sockets[id];
}
```

This code creates a UDP socket for each unique session and starts a new thread to listen for packets on that socket. It uses mutex locks to ensure thread-safety when initializing the sockets.

Note: This is a high-level view of how such functionality can be implemented in C using pthreads, actual implementation might require handling packet buffering and timeout settings properly which is not covered here due to complexity. Also remember that this code does not handle error recovery or closing of connections when they are no longer needed.
']

