typedef struct Node {
    NFAPI_RRC_MSG_T data;
    struct Node *next;
} Node;

Node *head = NULL; // The head of the list

void insert(NFAPI_RRC_MSG_T msg, int limit) {
    if (sizeof(*head) >= limit) { 
        printf("Buffer Overflow Warning: Not adding element as size limit exceeded.\n");
        return;
    }

    Node *node = malloc(sizeof(Node));
    node->data = msg;
    node->next = NULL;

    if (head == NULL) { // If list is empty, point head to the new node
        head = node;
    } else { 
        Node *temp = head;

        while(temp != NULL) {
            if (temp->data.RNTI == msg.RNTI){
                printf("Duplicate RNTI Warning: Not adding element as RNTI is duplicate.\n");
                return;
            }

            // If it's the last node, append new node at end
            if (temp->next == NULL) { 
                temp->next = node;
                break;
            }

            temp = temp->next; // Go to next node
        }
    }
}
```

This code uses a linked list implementation where each `Node` contains an `NFAPI_RRC_MSG_T` and a pointer to the next `Node`. When inserting, it first checks if the buffer limit is reached. If not, it then checks if the RNTI already exists in the list. If the RNTI doesn't exist yet, a new node is added at the end of the list.
