    printf("Invalid RNTI value. Skipping insertion.\n");
    failedInsertions++;
    return messages;
  }

  int i;
  for(i=0; i<size; ++i){ // check if the RNTI is already present in the array
    if (messages[i].RNTI == rnti) {
      printf("Duplicate RNTI. Skipping insertion.\n");
      failedInsertions++;
      return messages;
    }
  }

  if(size + numOfMessages > MAX_SIZE){ // check if array size limit will be exceeded after insertion
    printf("Exceeding maximum size limit. Skipping insertion.\n");
    failedInsertions += numOfMessages;
