typedef struct Node {
    int value;
    struct Node *next;
} Node;

int insertNode(Node **head, int val) {
    if (*head == NULL) { // If list is empty, initialize it with new node.
        *head = (Node*) malloc(sizeof(Node));
        (*head)->value = val;
        (*head)->next = NULL;
        return 1;
    } else if ((*head)->value == val) { // If value already exists in list, do nothing.
        printf("Warning: Duplicate TAI detected.\n");
        return 0;
    } else { // Else, continue traversing the list.
        return insertNode(&((*head)->next), val);
    }
}

// Function to generate and populate array of NFAPI_MAC_MSG_T structures.
