    if (num > limit) { // Check for buffer overflow.
        printf("Error: Number of messages exceeds specified limit.\n");
        return NULL;
    } else if (num == 0) { // Handle edge case of zero TAI values.
        printf("Warning: No TAIs provided.\n");
