typedef struct RegistrationTable {
    int* entries; 
    size_t totalEntries;
    size_t maxEntries;
    size_t successfulInsertions;
    size_t failedInsertions;
    pthread_mutex_t lock;
} RegistrationTable;

RegistrationTable* createTable(size_t initialSize) {
    RegistrationTable* table = malloc(sizeof(RegistrationTable));
    if (!table) return NULL;

    table->entries = malloc(initialSize * sizeof(int));
    if (!table->entries) {
        free(table);
        return NULL;
    }

    table->totalEntries = 0;
    table->maxEntries = initialSize;
    table->successfulInsertions = 0;
    table->failedInsertions = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroyTable(RegistrationTable* table) {
    if (!table) return;
    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int insertIntoTable(RegistrationTable* table, int RNTI) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->totalEntries; ++i) {
        if (table->entries[i] == RNTI) {
            ++table->failedInsertions;
            pthread_mutex_unlock(&table->lock);
            return 1; // Duplicate entry
        }
    }

    if (table->totalEntries == table->maxEntries) {
        ++table->failedInsertions;
        pthread_mutex_unlock(&table->lock);
        return -1; // Table is full
    }

    ++table->successfulInsertions;
    table->entries[table->totalEntries] = RNTI;
    ++table->totalEntries;

    pthread_mutex_unlock(&table->lock);

    return 0; // Success
}

void processMessages(NFAPI_RRC_MSG_T* msgs, size_t msgCount, RegistrationTable* table) {
    for (size_t i = 0; i < msgCount; ++i) {
        if (!insertIntoTable(table, msgs[i].RNTI)) {
            // Successful insertion
            logSuccessfulInsertion(msgs[i]);
        } else {
            // Duplicate RNTI or table is full
            logFailedInsertion(msgs[i]);
        }
    }

    logProcessedMessages(msgCount);
}
```
Please replace `logSuccessfulInsertion`, `logFailedInsertion` and `logProcessedMessages` with actual logging functions. Also note that this code doesn't handle resizing of the table when it gets full, which could be done by simply doubling the size each time an insertion fails due to insufficient space. This implementation is a simple illustration and can be greatly improved for production-level code, but it should give you an idea of how such a system might be implemented in C.
