    if (fp == NULL) {
        handleError("Failed to open task sequence file.");
        return NULL;
    }

    // Allocate initial memory for the arrays
    const size_t initialSize = 1024;
    int* taskIds = malloc(sizeof(*taskIds) * initialSize);
    float* deadlines = malloc(sizeof(*deadlines) * initialSize);
    char** names = malloc(sizeof(*names) * initialSize);
    if (taskIds == NULL || deadlines == NULL || names == NULL) {
        handleError("Failed to allocate memory for task sequence arrays.");
        fclose(fp);
        return NULL;
    }

    // Allocate space for tasks
    Task** tasks = malloc(sizeof(*tasks) * initialSize);
    if (tasks == NULL) {
        handleError("Failed to allocate memory for task array.");
        free(taskIds);
        free(deadlines);
        free(names);
        fclose(fp);
        return NULL;
    }

    // Read and process tasks from the file
    size_t numTasks = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        /* Process task data */
        ++numTasks;
        if (numTasks > initialSize) {
            handleError("Too many tasks in the sequence.");
            break;
        }
    }

    // Fill the arrays and tasks
    for (size_t i = 0; i < numTasks; ++i) {
        /* Process task data */
        Task* task = malloc(sizeof(*task));
        if (task == NULL) {
            handleError("Failed to allocate memory for a task.");
            break;
        }
        tasks[i] = task;
    }

    // Initialize the TaskSequence object
    TaskSequence* sequence = malloc(sizeof(*sequence));
    if (sequence == NULL) {
        handleError("Failed to allocate memory for the TaskSequence.");
        /* Free allocated resources */
        return NULL;
    }

    // Initialize synchronization mechanism
    pthread_mutex_init(&sequence->lock, NULL);

    sequence->tasks = tasks;
    sequence->taskIds = taskIds;
    sequence->deadlines = deadlines;
    sequence->names = names;
    sequence->numTasks = numTasks;
    sequence->maxNumTasks = initialSize;

    // Schedule tasks and handle completion callbacks
