typedef struct {
    int port;
    float latency;
    char* serviceName;
} NetworkConfig;

typedef void (*NetworkCallback)(NetworkConfig*, size_t);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // for thread-safety

void handleAllocationFailure(const char* message) {
    // Log the error and exit
}

NetworkConfig* processAndExecuteNetworkConfigurationChanges(char* filePath, size_t maxEntries, NetworkCallback callback, int(*comparison)(const void*, const void*)) {
    json_error_t error;
    json_t *root = json_load_file(filePath, 0, &error);

    if(!json_is_array(root)) {
        handleAllocationFailure("File content is not an array");
    }

    size_t length = json_array_size(root);
    NetworkConfig* configs = (NetworkConfig*)calloc(length, sizeof(NetworkConfig));

    if(!configs) {
        handleAllocationFailure("Failed to allocate memory for configurations");
    }

    // Parse each network configuration and fill the array
    for(size_t i = 0; i < length; ++i) {
        json_t *network = json_array_get(root, i);

        if(!json_is_object(network)) {
            handleAllocationFailure("Network entry is not an object");
        }

        configs[i].port = json_integer_value(json_object_get(network, "port"));
        configs[i].latency = (float)json_real_value(json_object_get(network, "latency"));

        const char *name = json_string_value(json_object_get(network, "serviceName"));
        if(!name) {
            handleAllocationFailure("Invalid service name");
        }

        configs[i].serviceName = strdup(name);  // copy string to heap memory
    }

    qsort(configs, length, sizeof(NetworkConfig), comparison);

    pthread_mutex_lock(&lock);  // for thread-safety

    callback(configs, length);  // call the provided callback function

    pthread_mutex_unlock(&lock);  // unlock after callback

    return configs;
}
```
