['This problem requires low level programming knowledge of C language and system APIs. Here's a simplified version of code using glib library for loading resource bundles from file. It can be enhanced further based on specific requirements. 

```c
#include <glib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

static pthread_mutex_t resourceMutex = PTHREAD_MUTEX_INITIALIZER;

GHashTable* loadResourceBundle(const char* filePath, GError **error) {
    FILE *file = fopen(filePath, "r"); // r for read mode
    if (file == NULL) {
        g_set_error(error, 1, 0, "Failed to open the resource bundle: %s", filePath);
        return NULL;
    }

    GHashTable *bundle = g_hash_table_new(g_str_hash, g_str_equal);
    if (bundle == NULL) {
        fclose(file);
        g_set_error(error, 2, 0, "Failed to allocate memory for the resource bundle");
        return NULL;
    }

    char line[1024]; // assuming each line in file is a key-value pair
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        g_hash_table_insert(bundle, g_strdup(key), g_strdup(value)); // assuming key-value pairs are separated by '='
    }

    fclose(file);
    return bundle;
}

int getBundleSize(const char* filePath) {
    GError *error = NULL;
    pthread_mutex_lock(&resourceMutex); // Lock mutex to make operation thread-safe

    GHashTable *bundle = loadResourceBundle(filePath, &error);
    int size = 0;
    if (bundle != NULL) {
        size = g_hash_table_size(bundle);
        g_hash_table_destroy(bundle);
    } else {
        fprintf(stderr, "%s\n", error->message);
        g_error_free(error);
    }

    pthread_mutex_unlock(&resourceMutex); // Unlock mutex
    return size;
}
```

Please note: This code doesn't handle network I/O, it directly reads file from local file system. If you want to manage resources that are located on a network share, the best way would be to mount the remote filesystem locally or use some library like libcurl for network requests which handles this out of the box.
']

