["To solve this problem, we need to use C with POSIX threading and some other libraries/data structures such as hash table for efficient `RNTI` management and doubly linked list for dynamic cleanup of unused `NFAPI_RRC_MSG_T` structures. 

Please note that this is just a basic implementation to give you an idea of how it can be done, the actual code will depend on your specific requirements:

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_RRC_MSG_T {
    int RR_REGISTRATION_REQUEST_TAG;
    int PUSCH资源配置; // I'm assuming this is a typo, if it isn't please replace with the correct term.
    int RNTI;
} NFAPI_RRC_MSG_T;

typedef struct Node {
    NFAPI_RRC_MSG_T msg;
    time_t lastUsedTime;
    struct Node *prev, *next;
} Node;

Node *head = NULL, *tail = NULL;
pthread_mutex_t mutexQueue = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t rwLockRNTI = PTHREAD_RWLOCK_INITIALIZER;
atomic_int totalSize = 0, successCount = 0, failCount = 0;
atomic_llong timeTakenSuccess = 0;

// A simple hash table to manage RNTI entries
#define TABLE_SIZE 10007 // Prime number for better hashing
typedef struct HashTableEntry {
    int RNTI;
    struct HashTableEntry *next;
} HashTableEntry;
HashTableEntry hashTable[TABLE_SIZE];

void insert(NFAPI_RRC_MSG_T msg) {
    // Check if the message limit is reached
    if (totalSize >= LIMIT) {
        atomic_fetch_add(&failCount, 1);
        return;
    }

    int index = abs(msg.RNTI % TABLE_SIZE); // Hash function for RNTI
    pthread_rwlock_rdlock(&rwLockRNTI);
    for (HashTableEntry *entry = hashTable[index]; entry != NULL; entry = entry->next) {
        if (entry->RNTI == msg.RNTI) {
            atomic_fetch_add(&failCount, 1);
            pthread_rwlock_unlock(&rwLockRNTI);
            return;
        }
    }

    // If RNTI not found in hash table, acquire write lock and insert
    pthread_rwlock_wrlock(&rwLockRNTI);
    HashTableEntry *newEntry = (HashTableEntry *) malloc(sizeof(HashTableEntry));
    newEntry->RNTI = msg.RNTI;
    newEntry->next = hashTable[index];
    hashTable[index] = newEntry;

    // Add to the queue and update stats
    pthread_mutex_lock(&mutexQueue);
    Node *node = (Node *) malloc(sizeof(Node));
    node->msg = msg;
    gettimeofday(&node->lastUsedTime, NULL);
    if (head == NULL) {
        head = tail = node;
        node->prev = node->next = NULL;
    } else {
        tail->next = node;
        node->prev = tail;
        node->next = NULL;
        tail = node;
    }
    atomic_fetch_add(&totalSize, 1);
    pthread_mutex_unlock(&mutexQueue);

    // Update successful insert stats
    struct timespec startTime, endTime;
    clock_gettime(CLOCK_MONOTONIC, &startTime);
    atomic_fetch_add(&successCount, 1);
    clock_gettime(CLOCK_MONOTONIC, &endTime);
    atomic_fetch_add(&timeTakenSuccess, (long long)(endTime.tv_sec - startTime.tv_sec) * 1000000000 + (endTime.tv_nsec - startTime.tv_nsec));

    pthread_rwlock_unlock(&rwLockRNTI);
}
```

This implementation handles most of the requirements mentioned in your task, but please note that it is not complete and may need to be extended or modified based on specific use cases.
