```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_MAC_MSG_T {
    MAC_PDU_TAG tag;
    DL_GRANT grant;
    TAI tai;
} NFAPI_MAC_MSG_T;

typedef struct DataManager {
    NFAPI_MAC_MSG_T* data;
    int maxMessages;
    int currentMessages;
    pthread_mutex_t lock;
} DataManager;

void addMessage(DataManager* manager, NFAPI_MAC_MSG_T message) {
    // Lock the mutex to ensure thread safety.
    pthread_mutex_lock(&manager->lock);

    if (manager->currentMessages >= manager->maxMessages) {
        // Increase the size of the data array dynamically.
        manager->data = realloc(manager->data, sizeof(NFAPI_MAC_MSG_T) * manager->maxMessages * 2);
        if (manager->data == NULL) {
            perror("Error while resizing the data array");
            return;
        }

        // Update maxMessages for future calculations.
        manager->maxMessages *= 2;
    }

    manager->data[manager->currentMessages++] = message;

    pthread_mutex_unlock(&manager->lock);
}

void removeMessage(DataManager* manager, TAI tai) {
    // Lock the mutex to ensure thread safety.
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->currentMessages; ++i) {
        if (manager->data[i].tai == tai) {
            // Shift all messages after the one to remove.
            for (int j = i; j < manager->currentMessages - 1; ++j) {
                manager->data[j] = manager->data[j + 1];
            }

            --manager->currentMessages;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

