typedef struct Set {
    pthread_mutex_t mutex;
    Node** buckets;
    size_t bucketCount;
    size_t count;  // for statistics
} Set;

Set* createSet(size_t bucketCount) {
    Set* set = malloc(sizeof(Set));
    set->buckets = calloc(bucketCount, sizeof(Node*));
    set->bucketCount = bucketCount;
    set->count = 0;
    pthread_mutex_init(&set->mutex, NULL);
    return set;
}

void destroySet(Set* set) {
    for (size_t i = 0; i < set->bucketCount; ++i) {
        Node* node = set->buckets[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);  // assuming NFAPI_RRC_MSG_T is allocated separately and needs to be freed here
            node = next;
        }
    }
    pthread_mutex_destroy(&set->mutex);
    free(set->buckets);
    free(set);
}

void insertToSet(Set* set, int rnti, NFAPI_RRC_MSG_T* value) {
    pthread_mutex_lock(&set->mutex);

    // hash function to get bucket index
    size_t bucketIndex = abs(rnti) % set->bucketCount;
    Node** nodePtr = &set->buckets[bucketIndex];
    while (*nodePtr != NULL) {
        if ((*nodePtr)->rnti == rnti) {
