Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int listSize = 0;

void insert(NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));  // replace with memory allocator
    if(!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    newNode->value = value;
    newNode->next = head;
    head = newNode;
    ++listSize;

    pthread_mutex_unlock(&lock);
}

void delete(int position) {
    pthread_mutex_lock(&lock);

    if (position < 0 || position >= listSize) return;

    Node* temp = head;

    if (position == 0) { 
        head = head->next;  
        free(temp); 
        --listSize;
        pthread_mutex_unlock(&lock);
        return;
    } 

    for (int i = 0; temp != NULL && i < position - 1; i++) {
        temp = temp->next;
    }

    if (temp == NULL || temp->next == NULL) return;

    Node *next = temp->next->next; 
    free(temp->next); 
    temp->next = next; 

    --listSize;
    pthread_mutex_unlock(&lock);
}

int getSize() {
    pthread_mutex_lock(&lock);
    int size = listSize;
    pthread_mutex_unlock(&lock);
    return size;
}

void printList() {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while(temp != NULL) {
        printf("%d ", temp->value.data);  // replace with actual fields in your structure
        temp = temp->next;
    }
