    unsigned long Timestamp;
    char* Payload;
} Message;

#define SIZE_OF_HASH 16384 // Assuming a power of two for efficiency.
unsigned int hash[SIZE_OF_HASH];

void insertIntoHash(int value, unsigned int hash[]) {
    if (hash[(value % SIZE_OF_HASH)] == 0) {
        hash[(value % SIZE_OF_HASH)] = 1;
    } else {
        printf("Warning: Duplicate entry detected. Skipping insertion.\n");
    }
}

int isDuplicate(int value, unsigned int hash[]) {
    return hash[(value % SIZE_OF_HASH)];
}

void initHash() {
    for (unsigned int i = 0; i < SIZE_OF_HASH; i++) {
        hash[i] = 0;
    }
}

NFAPI_RRC_MSG_T* NFAPI_RRC_init(int numEntries, unsigned int RNTI_start) {
    initHash();

    NFAPI_RRC_MSG_T* array = (NFAPI_RRC_MSG_T*) malloc(numEntries * sizeof(NFAPI_RRC_MSG_T));
    if (array == NULL) return NULL; // Out of memory.

    for (int i = 0; i < numEntries; i++) {
        array[i].RNTI = RNTI_start + i;
        insertIntoHash(array[i].RNTI, hash);
    }

    return array;
}
