        int value = generateRandomInteger(dvm);

        // Check if the generated value is unique.
        size_t j;
        for (j = 0; j < numUsedValues; ++j) {
            if (usedValues[j] == value) break;
        }

        // If we found a unique value, return it and remember it.
        if (j >= numUsedValues) {
            usedValues[numUsedValues++] = value;
            return value;
        }
    }

