const fs = require('fs');
const path = require('path');

class manageDynamicArray {
    constructor() {
        this.arrayOfObjects = [];
        // Assumption: Maximum elements is 10^6, as it won't cause segmentation faults in typical environments
        this.MAX_ELEMENTS = 1e6; 
    }

    addObject(RNTI) {
        if (this.arrayOfObjects.length < this.MAX_ELEMENTS) {
            let CRCFLAG = Math.random() >= 0.5; // Randomly assigning a boolean value for simplicity
            let newObj = { 
                RX_UE_INFORMATION_TAG: 'someValue', 
                RNTI, 
                CRC_INDICATION_REL8_TAG: 'anotherValue',
                CRCFLAG, 
            };
            this.arrayOfObjects.push(newObj);
        } else {
            throw new Error('Array is at its maximum limit');
        }
    }

    removeObjectByRNTI(RNTI) {
        let indexToRemove = this.arrayOfObjects.findIndex((obj) => obj.RNTI === RNTI);
        if (indexToRemove !== -1) {
            this.arrayOfObjects.splice(indexToRemove, 1);
        } else {
            throw new Error('No object found with the given RNTI');
        }
    }

    getNumberOfValidEntries() {
        return this.arrayOfObjects.length;
    }

    readFileSync(filePath) {
        let absolutePath = path.resolve(__dirname, filePath);
        try {
            let data = fs.readFileSync(absolutePath, 'utf8');
            return data;
        } catch (err) {
            throw new Error('Error reading the file: ', err);
        }
    }
}
