class CustomHandler(FileSystemEventHandler):
    def on_modified(self, event):
        if not event.is_directory and ".json" in event.src_path:
            updateConfig = json.loads(open(event.src_path).read())
            with class_lock:
                configs[updateConfig['sequenceNumber']] = updateConfig
            logging.info('Updated configuration at sequence number %d', updateConfig['sequenceNumber'])

def setupMonitoringService():
    observer = Observer()
    observer.schedule(CustomHandler(), path='./configs', recursive=True)
    observer.start()

