def encryptData(data):
    key = get_random_bytes(16)
    cipher = AES.new(key, AES.MODE_CBC)
    return {cipher.encrypt(pad(json.dumps(data).encode(), AES.block_size))}

def decryptData(encrypted):
    key = get_random_bytes(16)
    cipher = AES.new(key, AES.MODE_CBC, IV=cipher.iv)
    return json.loads(unpad(cipher.decrypt(encrypted), AES.block_size).decode())

def generateChecksum(data):
    m = hashlib.sha256()
    m.update(json.dumps(data).encode())
    return m.hexdigest()

# Compression functions
def compressData(data, level=9): # Default compression level is 9
    compressed_data = zlib.compress(json.dumps(data), level)
    return compressed_data

def decompressData(compressed_data):
    data = zlib.decompress(compressed_data)
    return json.loads(data)

# Validation function using SHA-256 checksums
def validateChecksum(checksum, data):
    return generateChecksum(data) == checksum

# Add custom validation rule through plugins
def addValidationRule(rule):
    plugins.append(rule)

