    doc = ""
    for key in schema:
        doc += "# {}:\n".format(key)
        doc += "{}\n\n".format(schema[key]['description'])
        doc += "- Example: {}\n\n".format(json.dumps(schema[key]['example']))
    with open('schema_doc.md', 'w') as f:
        f.write(doc)

# Notify subscribers of changes to specific parameters
def notifySubscribers(param):
    for subscriber in subscribers[param]:
        requests.post(subscriber, json={'param': param})

# Concurrent access function
def concurrentAccess():
    with class_lock:
