typedef struct ARRAY {
    pthread_mutex_t lock;
    int size, capacity;
    Connection **data;
} Array;

Array* createArray() {
    Array *array = malloc(sizeof(Array));
    array->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    array->capacity = 10; // Initial capacity
    array->data = malloc(array->capacity * sizeof(Connection*));
    array->size = 0;
    return array;
}

void addToArray(Array *array, Connection *conn) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) { // Ensure enough space
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(Connection*));
    }

    array->data[array->size++] = conn;

    pthread_mutex_unlock(&array->lock);
}

void updateArray(Array *array, int index, Connection *conn) {
    pthread_mutex_lock(&array->lock);

    if (index < array->size && index >= 0) { // Ensure valid index
        array->data[index] = conn;
    } else {
        printf("Error: Index out of bounds\n");
    }

    pthread_mutex_unlock(&array->lock);
}
