```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Xml.Linq;

public class WebSiteAdder {
    private Dictionary<string, string> AddAndStartWebsites(string directoryPath, List<string> siteNames, string configOverrideFile = null) {
        var results = new Dictionary<string, string>();

        foreach (var siteName in siteNames) {
            var siteDirectory = Path.Combine(directoryPath, siteName);
            var webConfigPath = Path.Combine(siteDirectory, "web.config");

            if (!File.Exists(webConfigPath)) {
                Console.WriteLine("Warning: Missing configuration for site " + siteName);
                results[siteName] = null;
                continue;
            }

            var webConfigDoc = XDocument.Load(webConfigPath);
            var applicationElement = webConfigDoc.Root?.Element("system.web")?.Element("applicationName");

            if (applicationElement == null || string.IsNullOrEmpty(applicationElement.Value)) {
                Console.WriteLine("Warning: Invalid configuration for site " + siteName);
                results[siteName] = null;
                continue;
            }

            var applicationProcessStartInfo = new ProcessStartInfo() {
                FileName = webConfigDoc.Root.Element("system.web").Element("startupExecutable")?.Value, // assuming a startup executable in web.config
                WorkingDirectory = siteDirectory
            };

            using (var process = Process.Start(applicationProcessStartInfo)) {
                if (process == null) {
                    Console.WriteLine("Error: Failed to start application for " + siteName);
                    results[siteName] = null;
                } else {
                    Console.WriteLine("Successfully started application for " + siteName);
                    results[siteName] = $"Application {process.Id} has been started successfully.";
                }
            }
        }

        return results;
    }
}
```
This code simply checks if the `web.config` file exists and contains a non-empty `applicationName` element. If these conditions are met, it starts an application specified in the web.config file in the respective website directory. Note that this is a simplified version and does not cover all edge cases or requirements mentioned above.
