    BASE_STATION* baseStation;
    UE* ue;
    CONN_STATUS status;
    time_t lastActivityTimestamp;
    int trafficPriorityLevel;
} CELLULAR_CONNECTION;

CELLULAR_CONNECTION** connectionsArray = NULL;
int connectionCount = 0;
pthread_mutex_t arrayLock; // for handling concurrent access to the array

void addConnection(BASE_STATION* baseStation, UE* ue, int trafficPriorityLevel) {
    pthread_mutex_lock(&arrayLock);

    connectionCount++;
    connectionsArray = realloc(connectionsArray, sizeof(CELLULAR_CONNECTION*) * connectionCount);
    CELLULAR_CONNECTION* newConnection = malloc(sizeof(CELLULAR_CONNECTION));
    newConnection->baseStation = baseStation;
    newConnection->ue = ue;
    newConnection->status = IDLE;
    newConnection->trafficPriorityLevel = trafficPriorityLevel;
    connectionsArray[connectionCount - 1] = newConnection;

    pthread_mutex_unlock(&arrayLock);
}

void updateConnection(int index, CONN_STATUS status) {
    if (index < connectionCount) {
        pthread_mutex_lock(&arrayLock);

        CELLULAR_CONNECTION* connection = connectionsArray[index];
        connection->status = status;
        if(status == ACTIVE){
            connection->lastActivityTimestamp = time(NULL);
        }

        pthread_mutex_unlock(&arrayLock);
    }
}
```
