            if (string.IsNullOrEmpty(url) || string.IsNullOrEmpty(port))
            {
                resultDict[site] = $"Missing URL or PORT environment variables for applicationName {applicationNameElement} in system.web section of web.config for {site}";
                continue;
            }

            // start the website asynchronously
            await StartWebsite(websitePath, url, port);

            resultDict[site] = "Started Successfully";
        }

        return resultDict;
    }

    private object LoadConfigOverrides(string configOverrideFile)
    {
        if (string.IsNullOrEmpty(configOverrideFile)) return null;

        var extension = Path.GetExtension(configOverrideFile);
        switch (extension)
        {
