  const readFileSync = (fileName) => {
    try{
      const data = fs.readFileSync(path.join(directoryPath, fileName), 'utf8');
      return data;
    } catch (err){
      throw err;
    }
  };

  const writeToJsonFile = async () => {
    if(lock) return; // Locking mechanism to prevent race condition.

    lock = true;
    try{
      await fs.promises.writeFile(path.join(directoryPath, 'data.json'), JSON.stringify(array));
    } catch (err){
      throw err;
    } finally {
      lock = false; // Release the lock after operation finishes.
    }
  };

  const readFromJsonFile = () => {
