// Struct to hold server instance data
struct MecServerInstance {
  int serverId;
  std::string workloadStatus;
  double resources;
  std::string versionInfo;
  double latencyMetrics;
};

class MECServerManager {
private:
  // Vector of server instances
  std::vector<MecServerInstance> servers;

public:
  MECServerManager() {}

  ~MECServerManager() {
    // Free memory if needed
    servers.clear();
    servers.shrink_to_fit();
  }

  void generateMECServerInstances(int N, double defaultResources) {
    try {
      // Check for invalid input values
      if (N < 1 || N > 10000) throw std::invalid_argument("Invalid number of instances");

      // Dynamically allocate servers based on the number of instances required
      servers.reserve(N);

      for(int i = 0; i < N; ++i) {
        MecServerInstance server;

        // Initialize instance data
        server.serverId = i + 1;
        server.workloadStatus = "idle";
        server.resources = defaultResources; 
        server.versionInfo = "Version 1";
        server.latencyMetrics = 0.0;

        servers.push_back(server);
      }

      // Track successful creations
      std::cout << N << " MEC server instances successfully created" << std::endl;
    } 
    catch (const std::bad_alloc& e) {
      // Handle memory allocation failures
      std::cerr << "Memory allocation failed: " << e.what() << '\n';

      // Track failed creations
      std::cout << "Failed to create MEC server instances" << std::endl;
    } 
    catch (const std::exception& e) {
      // Handle other exceptions
      std::cerr << "Exception: " << e.what() << '\n';

      // Track failed creations
      std::cout << "Failed to create MEC server instances" << std::endl;
    }
  }

  void computeMD5Hash(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest); 

    char mdString[33];

    for(int i = 0; i < 16; i++)
      sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

    std::cout << "MD5 hash of \"" << input << "\": " << mdString << std::endl;
  }
};
```
