```c
#include <pthread.h>
#include <time.h>

typedef struct LTE_UARFCN_T {
    int freq;
} LTE_UARFCN_T;

typedef struct LTE_BANDINFO_T {
    char* bandName;
    time_t lastUsedTimeStamp;
    LTE_UARFCN_T* uarfcnList;
    int listSize;
} LTE_BANDINFO_T;

typedef struct Node {
    LTE_BANDINFO_T* data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

// Function to add a new band info
void add(LTE_BANDINFO_T* bandInfo) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = bandInfo;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

// Function to update a existing band info
void update(int id, LTE_BANDINFO_T* updatedData) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        if (temp->data->bandId == id) {
            break;
        }
        temp = temp->next;
    }

    if (temp != NULL) {
        free(temp->data); // Assuming memory allocation for bandInfo is dynamic
        temp->data = updatedData;
    }

    pthread_mutex_unlock(&lock);
}

// Function to delete a band info
void delete(int id) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev;
    while (temp != NULL && temp->data->bandId != id) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;
    prev->next = temp->next;

    free(temp->data); // Assuming memory allocation for bandInfo is dynamic
    free(temp);

    pthread_mutex_unlock(&lock);
}
```
The code provided above assumes that you have already defined the `LTE_UARFCN_T` and `LTE_BANDINFO_T` structs, which may not be complete for this context. The full implementation would require more detailed design such as memory management strategies, concurrent access controls, search features, archiving feature, logging/timestamping integration, and error handling, among others.
