    }

    char buffer[MAX_LINE];
    int count = 0;
    while (fgets(buffer, MAX_LINE, file)) {
        printf("Line %d: %s\n", ++count, buffer);
    }

    fclose(file);

    return count; // total number of lines read from the file
}
```
