```C
#include <stdio.h>
#include <stdlib.h>
#include <getopt.h>
#include <string.h>

#define MAX_FILES 100

struct Options {
    char *compression;
    FILE *outputFile;
    int limit;
    int noHeader;
    int incremental;
};

void processLogFiles(char* files[], struct Options options);

int main(int argc, char **argv) {
    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"compression", required_argument, 0, 'c'},
        {"output_file", required_argument, 0, 'o'},
        {"limit", required_argument, 0, 'l'},
        {"no_header", no_argument, 0, 'n'},
        {"incremental", no_argument, 0, 'i'}
    };

    struct Options options = {.compression = NULL, .outputFile = stdout, .limit = 0, .noHeader = 0, .incremental = 0};

    int c;
    while ((c = getopt_long(argc, argv, "hc:o:l:ni", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                printHelp();
                return 0;
            case 'c':
                options.compression = optarg;
                break;
            case 'o':
                if ((options.outputFile = fopen(optarg, "w")) == NULL) {
                    perror("Error opening output file");
                    return 1;
                }
                break;
            case 'l':
                options.limit = atoi(optarg);
                break;
            case 'n':
                options.noHeader = 1;
                break;
            case 'i':
                options.incremental = 1;
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                printHelp();
                return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Expected file arguments after options\n");
        printHelp();
        return 1;
    }

    char *files[MAX_FILES];
    int numFiles = 0;
    for (; optind < argc && numFiles < MAX_FILES; optind++, numFiles++) {
        files[numFiles] = argv[optind];
    }

    processLogFiles(files, options);

    if (options.outputFile != stdout) fclose(options.outputFile);

    return 0;
}
```
