int addNewConnection(ConnectionArray* array, BASE_STATION* baseStation, USER_EQUIPMENT* userEquipment) {
    pthread_mutex_lock(&array->lock);
    array->size++;

    CELLULAR_CONNECTION** temp = (CELLULAR_CONNECTION**)realloc(array->connections, sizeof(CELLULAR_CONNECTION*) * array->size);
    if(temp != NULL) {
        array->connections = temp;
        array->connections[array->size - 1] = (CELLULAR_CONNECTION*)malloc(sizeof(CELLULAR_CONNECTION));
        array->connections[array->size - 1]->baseStation = baseStation;
        array->connections[array->size - 1]->userEquipment = userEquipment;
        // Initialize other fields here
    } else {
        array->size--;
        pthread_mutex_unlock(&array->lock);
        return -1;  // Return error code on memory allocation failure
    }

    pthread_t threadId;
    if(pthread_create(&threadId, NULL, &connectionManagementThread, array->connections[array->size - 1])) {
        array->size--;
        free(array->connections[array->size]);
        pthread_mutex_unlock(&array->lock);
        return -2;  // Return error code on thread creation failure
    }

    pthread_detach(threadId);
    pthread_mutex_unlock(&array->lock);
    return 0;  // Connection added successfully
}
