                     "  -v, --verbose        Verbose mode. Print more detailed event information.\n"
                     "  -h, --help           Display this help and exit.");
                return EXIT_SUCCESS;
            default:
                puts("Try `programName --help` for more information.");
                return EXIT_FAILURE;
        }
    }

    if (optind < argc) {
        processFile(argv[optind], verboseMode, outputFile);
    } else {
        puts("No input file specified!");
        return EXIT_FAILURE;
    }

    fclose(outputFile);
    if (outputFileName != NULL) free(outputFileName);
    return EXIT_SUCCESS;
}
```
