['Here is a simplified version of what your task might require. This is a basic implementation where server load, response time, and available processing units are checked before executing operations. 

```java
import java.util.concurrent.*;
import org.apache.commons.lang3.time.StopWatch;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.sf.ehcache.CacheManager;
import net.sf.ehcache.Ehcache;
import net.sf.ehcache.Element;

public class LoadBalancer {
    private static final Logger logger = LoggerFactory.getLogger(LoadBalancer.class);

    private CacheManager cacheManager;
    private Ehcache metricsCache;

    // Constructor for LoadBalancer 
    public LoadBalancer() {
        this.cacheManager = CacheManager.getInstance();
        this.metricsCache = cacheManager.getEhcache("metrics");
    }

    ExecutorService executorService = Executors.newFixedThreadPool(10_000);
    BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(10_000);

    // Load balancing method 
    public void loadBalance(double serverLoad, double responseTime, int processingUnits) {
        if (serverLoad > 0.8 || responseTime > 50) {
            logger.info("Not executing operation due to high load or long response time");
            return;
        }

        // Use a distributed cache for shared state management 
        Element el = metricsCache.get(processingUnits);
        if (el == null || el.getObjectValue() != Integer.class) {
            logger.info("Not executing operation due to insufficient processing units");
            return;
        }

        // Submit a new task to executor service 
        Runnable task = () -> executeOperation(processingUnits);
        try {
            boolean offerResult = queue.offer(task, 10, TimeUnit.MILLISECONDS);
            if (!offerResult) {
                logger.info("Queue is full");
            } else {
                executorService.execute(task);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    // Execute operation method 
    private void executeOperation(int processingUnits) {
        try {
            StopWatch stopwatch = new StopWatch();
            stopwatch.start();

            // Logic for executing the selected operation goes here 
            // ...

            stopwatch.stop();
            logger.info("Execution time: {}ms", stopwatch.getTime());
        } catch (Exception e) {
            logger.error("Error during execution of operation", e);
        } finally {
            metricsCache.put(new Element(processingUnits, processingUnits - 1));
        }
    }
}
```
Please note that actual implementation would require handling different server operations and implementing a retry mechanism for transient failures. For custom metrics, you can use tools like Prometheus or Graphite alongside with Grafana for visualization. Please ensure to handle all exceptions in the application according to your application requirements. 

