ConfigData* readCompressedEncryptProcessJSONConfig(char* inputFilePath, char* cmdLineOptions) {
    FILE *fp = fopen(inputFilePath, "rb");  // Open file in binary mode
    if (fp == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);  // Lock mutex for thread-safety

    json_error_t error;
    ConfigData *configData = malloc(sizeof(ConfigData));  // Dynamically allocate memory

    fseek(fp, 0L, SEEK_END);  // Move file pointer to the end
    long size = ftell(fp);  // Get current position (file size)
    rewind(fp);  // Move file pointer back to the beginning

    if (size > maxSize) {
        printf("File too large\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex before returning NULL
        return NULL;
    }

    char *fileContent = malloc(size + 1);  // Dynamically allocate memory for file content
    fread(fileContent, size, 1, fp);  // Read file content into buffer
    fileContent[size] = '\0';  // Null-terminate string

    if (enableEncryption) {
        // Implement encryption here
    }

    configData->root = json_loads(fileContent, 0, &error);  // Parse JSON
    free(fileContent);  // Free file content buffer

    pthread_mutex_unlock(&mutex);  // Unlock mutex before returning data
    return configData;
}
```
