void modifyFilenameExtension(char* filename) {
    char* extension = strrchr(filename, '.');

    if (extension == nullptr) return; // No extension found

    *extension = '\0';  // Remove the old extension

    int sequenceLength = 0;  // Calculate sequence length based on filename content
