typedef struct DynamicValueManager {
    float minValue, maxValue;
    int count;
    double sum;
    pthread_mutex_t lock;
} DynamicValueManager;

void DynamicValueManager_Init(DynamicValueManager *dvm) {
    dvm->minValue = FLT_MIN;
    dvm->maxValue = FLT_MAX;
    dvm->count = 0;
    dvm->sum = 0.0;
    pthread_mutex_init(&(dvm->lock), NULL);
}

float DynamicValueManager_GetRandomFloat(DynamicValueManager *dvm) {
    float scale = rand() / (float) RAND_MAX; 
    return dvm->minValue + scale * (dvm->maxValue - dvm->minValue);
}

int DynamicValueManager_GetRandomInt(DynamicValueManager *dvm) {
    float scale = rand() / (float) RAND_MAX; 
    return (int)(dvm->minValue + scale * (dvm->maxValue - dvm->minValue));
}

void DynamicValueManager_AdjustRange(DynamicValueManager *dvm, float newMin, float newMax) {
    pthread_mutex_lock(&(dvm->lock));

    if (newMin <= newMax && newMin >= dvm->minValue && newMax <= dvm->maxValue) {
        dvm->minValue = newMin;
        dvm->maxValue = newMax;
    }

    pthread_mutex_unlock(&(dvm->lock));
}

float DynamicValueManager_GetAdjustedValue(DynamicValueManager *dvm, float value) {
    while (value < dvm->minValue) 
        value += dvm->maxValue - dvm->minValue;

    return fmod(value - dvm->minValue, dvm->maxValue - dvm->minValue) + dvm->minValue;
}

char* DynamicValueManager_ToString(DynamicValueManager *dvm) {
    char *str = malloc(50);
    sprintf(str, "Range: [%f, %f]", dvm->minValue, dvm->maxValue);

    return str;
}
