['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    float SNR;
    float RSRP;
    float RSRQ;
    float BER;
} LTE_PHY_FRAME_STATISTICS;

// A thread-safe, dynamic list implementation for LTE_PHY_FRAME_STATISTICS.
typedef struct {
    LTE_PHY_FRAME_STATISTICS **frames;
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock;
} FrameList;

FrameList *createFrameList() {
    FrameList *list = malloc(sizeof(FrameList));
    if (!list) {
        return NULL; // Out of memory error
    }

    list->frames = calloc(500, sizeof(LTE_PHY_FRAME_STATISTICS*));
    if (!list->frames) {
        free(list);
        return NULL; // Out of memory error
    }

    list->capacity = 500;
    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyFrameList(FrameList *list) {
    for (size_t i = 0; i < atomic_load(&list->size); ++i) {
        free(list->frames[i]);
    }

    free(list->frames);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addFrameToList(FrameList *list, LTE_PHY_FRAME_STATISTICS *frame) {
    size_t index = atomic_fetch_add(&list->size, 1);

    if (index < list->capacity) {
        pthread_mutex_lock(&list->lock);

        LTE_PHY_FRAME_STATISTICS *copy = malloc(sizeof(LTE_PHY_FRAME_STATISTICS));
        if (!copy) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory error
        }

        memcpy(copy, frame, sizeof(LTE_PHY_FRAME_STATISTICS));
        list->frames[index] = copy;

        pthread_mutex_unlock(&list->lock);
        return 0; // Successfully added frame to list
    } else {
        atomic_fetch_sub(&list->size, 1);
        return -2; // List is full error
    }
}
```
