void addPacket(time_t timestamp, const char* sourceIP, const char* destIP, int protocolType) {
    if (packetCount >= maxPacketCount) {
        maxPacketCount = maxPacketCount ? maxPacketCount * 2 : 1;
        packets = realloc(packets, sizeof(*packets) * maxPacketCount);
    }

    Packet *pkt = &packets[packetCount++];
    pkt->timestamp = timestamp;
    strcpy(pkt->sourceIP, sourceIP);
    strcpy(pkt->destIP, destIP);
    pkt->protocolType = protocolType;
}

void removePacketBySourceIP(const char* ip) {
    for (size_t i = 0; i < packetCount;) {
        if (!strcmp(packets[i].sourceIP, ip)) {
            memmove(&packets[i], &packets[i + 1], sizeof(*packets) * (packetCount - i - 1));
            --packetCount;
        } else {
            ++i;
        }
    }
}

void updatePacketTimestamp(const char* ip, time_t newTimestamp) {
    for (size_t i = 0; i < packetCount; ++i) {
        if (!strcmp(packets[i].sourceIP, ip)) {
            packets[i].timestamp = newTimestamp;
        }
    }
}

Packet *findLatestPacketInRange(const char* ip, time_t startTime, time_t endTime) {
    Packet *latest = NULL;

    for (size_t i = 0; i < packetCount; ++i) {
        if (!strcmp(packets[i].sourceIP, ip) && packets[i].timestamp >= startTime && packets[i].timestamp <= endTime) {
            if (latest == NULL || latest->timestamp < packets[i].timestamp) {
                latest = &packets[i];
            }
        }
    }

    return latest;
}
