        return -1;
    }

    // populate the list
    int prevRNTI = 0, trueCount = 0;
    for (int i = 0; i < N; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = version; 

        do {
            (*list)[i].RNTI = rand() % 65535 + 1; // generate random RNTI in range [1, 65535]
        } while ((*list)[i].RNTI == prevRNTI);

        prevRNTI = (*list)[i].RNTI;

