    if (file == NULL) return -1; // return error code for failed file opening

    assert(fwrite(pdus, sizeof(*pdus), n, file) == n);

    fclose(file);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* deserializeNFAPackets(const char* filename, int *n) {
