    assert(fread(n, sizeof(*n), 1, file));

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*(*n));

    if (pdus == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
