void* setupSubscription(void *arg);

int handleUserSubscriptions(const char* userID, const char** categories, int categoryCount, const char* frequency) {
    SubscriptionRequest request;

    strncpy(request.userID, userID, MAX_BUFFER);
    strncpy(request.frequency, frequency, MAX_BUFFER);

    for (int i = 0; i < categoryCount; ++i) {
        strncpy(request.categories[i], categories[i], MAX_BUFFER);
    }

    pthread_mutex_lock(&lock);
    requests[requestIndex++] = request;
    pthread_mutex_unlock(&lock);

    return 0;
}

int startSubscriptionService() {
    if (strcmp(environment, "development") == 0) {
        logFile = fopen("devlog.txt", "w");
    } else if (strcmp(environment, "production") == 0) {
        logFile = fopen("/var/log/prod.log", "w");
    } else {
        return 1; // Invalid environment
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        if(pthread_create(&threads[i], NULL, setupSubscription, NULL)) {
            fprintf(logFile, "Error creating thread\n");
            return 1; // Error creating threads
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(logFile);
    return 0;
}

void* setupSubscription(void *arg) {
    SubscriptionRequest request;

    while (1) {
        pthread_mutex_lock(&lock);
        if (requestIndex == 0) {
            pthread_mutex_unlock(&lock);
            break;
        }

        request = requests[--requestIndex];
        pthread_mutex_unlock(&lock);

        // Handle setup logic here, including retries and error handling for network latency 
    }

    pthread_exit(NULL);
}
```

