int maxListSize = 10000; // Default maximum list size
int allocationCount = 0;
time_t startTime;
const int MAX_ALLOCATIONS_PER_SECOND = 100;

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateList(int N) {
    if (N > maxListSize) {
        printf("Cannot create more than %d nodes\n", maxListSize);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);

        if (allocationCount >= MAX_ALLOCATIONS_PER_SECOND && time(NULL) - startTime < 1) {
            printf("Reached maximum allocation limit\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (node == NULL) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        node->RX_UE_INFORMATION_TAG = 0; // Dummy value
        node->RNTI = rand() % maxListSize; // Randomly set RNTI

        CRC_INDICATION_REL8_TAG *crcTag = (CRC_INDICATION_REL8_TAG*) malloc(sizeof(CRC_INDICATION_REL8_TAG));

        if (crcTag == NULL) {
