                    printf("Duplicate RNTI found\n");
                    free(node);
                    free(crcTag);
                    pthread_mutex_unlock(&lock);
                    return NULL;
                }

                currentNode = currentNode->next;
            }

            tail->next = node;
            tail = node;
        }

        allocationCount++;

        if (time(NULL) - startTime >= 1) {
            allocationCount = 0;
            startTime = time(NULL);
        }

        pthread_mutex_unlock(&lock);
    }

    return head;
}
