pub struct FileCache {
    md5s: Mutex<HashMap<String, String>>,
    config: DirectoryConfig,
}

impl FileCache {
    pub async fn new(config: DirectoryConfig) -> Self {
        if env::var("MY_APP").is_err() || !env::var("MY_APP").unwrap().is_empty() {
            fs::create_dir(&config.directory).expect("Unable to create directory");
            env::set_var("MY_APP", config.directory);
        } else {
            info_log(format![ "Directory exists: {}", &env::var("MY_APP").unwrap()]);
        }
        Self {
            md5s: Mutex::new(HashMap::new()),
            config,
        }
    }

    pub async fn manage(&self) {
        loop {
            self.update_cache().await;
            thread::sleep(self.config.cache_refresh_interval);
        }
    }

    async fn update_cache(&self) {
        let paths = fs::read_dir(&self.config.directory).expect("Unable to read directory");

        for path in paths {
            if let Ok(path) = path {
                if path.file_type().unwrap().is_file() {
                    let filename = path.file_name().to_string_lossy().into_owned();
                    let md5 = compute_md5(&fs::read(&path).expect("Unable to read file"));
                    info_log(format![ "Updating cache for {}", filename]);

                    match self.md5s.lock().await {
                        Err(_) => error_log(format![ "Error when acquiring lock"]),
                        Ok(mut md5s) => *md5s.entry(filename).or_insert(md5),
                    }
                }
            }
        }
    }
}
