#define MAX_NODES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int count = 0;

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    if (count >= MAX_NODES) {
        printf("List is full\n");
        return;
    }
    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            if (current->data.RNTI == data.RNTI) {
                printf("Duplicate RNTI found\n");
                return;
            }
            current = current->next;
        }

        if (current->data.RNTI != data.RNTI) {
            current->next = newNode;
            count++;
        } else {
            printf("Duplicate RNTI found\n");
            return;
        }
    }
    pthread_mutex_unlock(&lock);
}

void sort() {
    if (head == NULL) return;

    for(Node *i = head; i->next != NULL; i = i->next) {
        for(Node *j = i->next; j != NULL; j = j->next) {
            if(i->data.RNTI > j->data.RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
        }
    }
}
``` 
