    if (buffer == NULL) {
        printf("Failed to allocate memory.\n");
        fclose(inputFile);
        return;
    }

    // Process the log file in chunks, handling network latency and data corruption issues
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, bufferSize, inputFile)) > 0) {
        unsigned char* encryptedOutputBuffer = malloc(bytesRead + EVP_CIPHER_CTX_block_size(ctx));
        if (encryptedOutputBuffer == NULL) {
            printf("Failed to allocate memory.\n");
            free(buffer);
            fclose(inputFile);
            return;
