        int encryptedOutputLength;
        if (EVP_EncryptUpdate(ctx, encryptedOutputBuffer, &encryptedOutputLength, buffer, bytesRead) != 1) {
            printf("Failed to encrypt data.\n");
            free(buffer);
            fclose(inputFile);
