        // Write the processed packet data to the output file
        if (fwrite(encryptedOutputBuffer, 1, encryptedOutputLength, outputFile) != encryptedOutputLength) {
            printf("Failed to write to output file.\n");
            free(buffer);
            fclose(inputFile);
            return;
        }

        free(encryptedOutputBuffer);
    }

    // Clean up resources and close files
