```java
import com.jcraft.jsch.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.*;
import java.util.concurrent.*;

public class SFTPService {
    private static final Logger logger = LoggerFactory.getLogger(SFTPService.class);
    private ExecutorService executorService;
    private ScheduledExecutorService scheduledExecutorService;
    private JSch jsch;
    private Session session;

    public SFTPService() {
        this.executorService = Executors.newFixedThreadPool(10); // Adjust based on system load
        this.scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();

        try {
            jsch = new JSch();
            session = jsch.getSession("username", "hostname", 22);
            session.setConfig("StrictHostKeyChecking", "no"); // Disable host key checking

            session.setPassword("password");
            session.connect();
        } catch (JSchException e) {
            logger.error("Failed to connect SFTP server: ", e);
        }
    }

    public void transferFiles(List<String> files, int retries) {
        for (String file : files) {
            executorService.execute(() -> {
                ChannelSftp channel = null;

                try {
                    channel = (ChannelSftp) session.openChannel("sftp");
                    channel.connect();

                    do {
                        try {
                            logger.info("Starting file transfer: {}", file);
                            channel.put(file, "remotePath");

                            logger.info("File transferred successfully: {}", file);
                            return; // File was transferred successfully
                        } catch (SftpException e) {
                            retries--;
                            if (retries > 0) {
                                try {
                                    Thread.sleep((long) Math.pow(2, 3 - retries) * 1000); // Exponential backoff
                                } catch (InterruptedException ex) {
                                    logger.error("Thread sleep interrupted: ", ex);
                                }
                            } else {
                                logger.error("Failed to transfer file after maximum attempts: {}", file);
                            }
                        }
                    } while (retries > 0);
                } catch (JSchException | SftpException e) {
                    logger.error("Error transferring file: ", e);
                } finally {
                    if (channel != null) channel.disconnect();
                }
            });
        }
    }

    public void monitorSystemHealth() {
        scheduledExecutorService.scheduleAtFixedRate(() -> {
            // Monitor system health and resource utilization here

            logger.info("Monitoring system health...");
        }, 0, 60, TimeUnit.SECONDS);
    }

    public void shutdown() {
        executorService.shutdown();
        scheduledExecutorService.shutdown();

        if (session != null && session.isConnected()) {
            session.disconnect();
        }
    }
}
```
This is a simplified example, real-world implementation would require more details and error handling for edge cases. 

