using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashProcessor
{
    private MD5 md5 = MD5.Create();

    public async Task<byte[]> ComputeHashAsync(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        byte[] inputBytes = Encoding.UTF8.GetBytes(input);
        return await md5.ComputeHashAsync(new MemoryStream(inputBytes)).ConfigureAwait(false);
    }

    public async Task<byte[]> ComputeFileHashAsync(string filePath)
    {
        if (filePath == null) throw new ArgumentNullException(nameof(filePath));

        using (var stream = File.OpenRead(filePath))
        {
            return await md5.ComputeHashAsync(stream).ConfigureAwait(false);
        }
    }
}
```
