using System.Linq;
using System.Security.Cryptography;

public class DecryptionException : Exception { public DecryptionException(string message) : base(message) { } };

class Program
{
    static byte[] DecryptAESCBCWithHMACSHA256Validation(string ciphertext, string key, string iv, string hmacKey)
    {
        // Parse the ciphertext from base64 and validate that it contains an IV and HMAC signature
        byte[] encryptedData = Convert.FromBase64String(ciphertext);
        if (encryptedData.Length < 32 + 16 + key.GetSHA256Hash().Length) { throw new DecryptionException("Ciphertext too short to contain IV, HMAC signature and data"); }

        // The first 16 bytes are the IV, followed by the rest of the data (including a SHA256 HMAC signature)
        byte[] ivBytes = encryptedData.Take(16).ToArray();
        byte[] hmacSignature = encryptedData.Skip(16 + key.GetSHA256Hash().Length).ToArray();

        // Verify the HMAC signature against a SHA256 hash of the ciphertext (minus the IV and HMAC signature)
        using var sha256 = new HMACSHA256(hmacKey.GetBytesFromHexOrBase64()))
            { byte[] computedSignature = sha256.ComputeHash(encryptedData, 32, encryptedData.Length - 32 - key.GetSHA256Hash().Length); if (!computedSignature.SequenceEqual(hmacSignature)) { throw new DecryptionException("HMAC signature verification failed"); } };

        // The decryption key can be either base64-encoded or hexadecimal, so convert it to bytes first
        byte[] aesKeyBytes = key.GetBytesFromHexOrBase64();

        using (var aesAlg = new AesCryptoServiceProvider())
        {
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;
            aesAlg.KeySize = 256;

            // Create decryptor for AES-CBC with the provided key and IV bytes
            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesKeyBytes, ivBytes);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] fromEncrypt = new byte[encryptedData.Length];

                    // Read the decrypted bytes from the decrypting stream and return them
                    csDecrypt.Read(fromEncrypt, 0, fromEncrypt.Length);
                    return fromEncrypt;
                }
            }
        }
    }

    static void Main() { /* Call your function here with proper arguments */ }
}
```
