```C
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char client_ip[INET6_ADDRSTRLEN]; // IPv4 or IPv6 address
    uint16_t client_port; 
    char server_ip[INET6_ADDRSTRLEN]; // IPv4 or IPv6 address
    uint16_t server_port; 
} TCP_REQUEST_T;

// Simplified struct for connection pool
typedef struct {
    atomic_uint active_connections;
    _Atomic(TCP_REQUEST_T*) requests[MAX_CONNECTIONS];
    // Add other necessary fields, like load balancing metrics, etc.
} CONNECTION_POOL_T;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the connection pool
void init_connection_pool(CONNECTION_POOL_T *pool) {
    memset(pool, 0, sizeof(*pool));
}

// Add a new TCP request to the connection pool
int add_tcp_request(_Atomic(TCP_REQUEST_T*) pool[MAX_CONNECTIONS], const TCP_REQUEST_T *req) {
    // Find an available slot in the pool, load balance it and ensure no duplicate IPs

    pthread_mutex_lock(&pool_lock); 
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        TCP_REQUEST_T *old = atomic_load_explicit(&pool[i], memory_order_acquire);

        // If slot is empty or the IP doesn't exist in the pool, we can use it.
        if (old == NULL || strcmp(req->client_ip, old->client_ip) != 0) { 
            atomic_store_explicit(&pool[i], req, memory_order_release);

            pthread_mutex_unlock(&pool_lock);
            return i; // Return the slot used for this request.
        } else if (strcmp(req->client_ip, old->client_ip) == 0) { 
            printf("IP address already exists in pool!\n");

            pthread_mutex_unlock(&pool_lock);
            return -1; // Return an error code. Could also add to a retry queue or similar.
        }
    }

    pthread_mutex_unlock(&pool_lock);
    printf("Connection pool is full!\n"); 
    return -2; // All slots are in use. Could add to a backpressure queue or similar.
}

// Establish TCP connections based on load balancing and handle errors, resource usage, etc.
void manage_tcp_connections(CONNECTION_POOL_T *pool) {
    // Apply various strategies for managing active connections, handling errors, etc.

    pthread_mutex_lock(&pool_lock); 
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        TCP_REQUEST_T *req = atomic_load_explicit(&(pool->requests[i]), memory_order_acquire);

        if (req != NULL) {
            // Establish a TCP connection. If successful, increment active connections counter
            ++pool->active_connections; 

            // Apply various strategies for load balancing and handling errors, etc.
        }
    }

    pthread_mutex_unlock(&pool_lock);
}
```
