    // TCP/UDP header or payload
    void *payload;
} packet_t;

int process_log_file(char *input_filename, char *output_filename, char *rules, unsigned char *keys) {
    FILE *in = fopen(input_filename, "rb");  // open input file in binary read mode
    if (in == NULL) {
        printf("Failed to open input file: %s\n", strerror(errno));
        return -1;
    }

    FILE *out = fopen(output_filename, "wb");  // open output file in binary write mode
    if (out == NULL) {
        printf("Failed to open output file: %s\n", strerror(errno));
        return -1;
    }

    OpenSSL_add_all_algorithms();  // register all openssl algorithms
    ERR_load_crypto_strings();  // load error strings for crypto functions

    EVP_CIPHER_CTX ctx;  // Create a cipher context
    int len, rv = 0;

    if (!EVP_add_cipher(rules)) {  // add the specified cipher
        printf("Failed to load cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    packet_t pkt;  // Create a packet structure

    while (fread(&pkt, sizeof(packet_t), 1, in) == 1) {  // read packets from file into pkt
        if (!EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, keys, NULL)) {
            printf("Failed to initialize encryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        if (!EVP_EncryptUpdate(&ctx, (unsigned char *)&pkt, &len, (const unsigned char *)&pkt, sizeof(packet_t))) {
            printf("Failed to encrypt data: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        if (!EVP_EncryptFinal_ex(&ctx, (unsigned char *)&pkt + len, &len)) {
            printf("Failed to finalize encryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        if (!EVP_DigestInit(&ctx, EVP_sha256())) {  // initialize digest operation
            printf("Failed to initialize hash: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        if (!EVP_DigestUpdate(&ctx, &pkt, sizeof(packet_t))) {  // feed the data
            printf("Failed to update hash: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        unsigned char md[EVP_MAX_MD_SIZE];
        unsigned int mdsz = sizeof(md);  // get the hash value
        if (!EVP_DigestFinal(&ctx, md, &mdsz)) {
            printf("Failed to finalize hash: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return -1;
        }

        fwrite(&pkt, sizeof(packet_t), 1, out);  // write the processed packet to output file
    }

    EVP_cleanup();  // clean up openssl environment
    ERR_free_strings();  // free error strings for crypto functions
    fclose(in);  // close input file
    fclose(out);  // close output file
    return rv;
}
```
