// Function to read a binary file into memory
char* read_binary(const char* filename, size_t* length) {
    FILE* f = fopen(filename, "rb");
    if(!f) {
        printf("Failed to open file %s\n", filename);
        return NULL;
    }

    // Get the file size
    fseek(f, 0, SEEK_END);
    *length = ftell(f);
    rewind(f);

    char* buffer = malloc(*length);
    if(!buffer) {
        printf("Failed to allocate memory for file %s\n", filename);
        fclose(f);
        return NULL;
    }

    // Read the data into our buffer
    if(fread(buffer, 1, *length, f) != *length) {
        printf("Failed to read file %s\n", filename);
        free(buffer);
        fclose(f);
        return NULL;
    }

    fclose(f);
    return buffer;
}

// Function to apply a cryptographic operation using OpenSSL EVP library
int apply_crypto(const char* cipher, const char* key, unsigned char* input, int inlen, unsigned char** output, int* outlen) {
    EVP_CIPHER_CTX *ctx;

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        return 0;
    }

    /* Initialise the encryption operation. IMPORTANT - ensure you have a keying string that is suitable for AES (exactly 16 bytes) */
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        return 0;
    }

